-- Imported from RepDB (repdb.co) free tier, https://github.com/RepDB/exercise-dataset.
-- License: free for personal/commercial in-app use with attribution (see LICENSE-DATA.md
-- in that repo). Images copied into /public/exercises. Idempotent via ON CONFLICT (slug).
insert into public.exercises (name, slug, primary_muscle_group_id, secondary_muscle_group_ids, equipment_id, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url, image_source, image_license)
select v.name, v.slug,
  (select id from public.muscle_groups where slug = v.muscle_slug),
  coalesce((select array_agg(id) from public.muscle_groups where slug = any(v.secondary_slugs)), '{}'),
  (select id from public.equipment where slug = v.equipment_slug),
  v.difficulty::public.exercise_difficulty,
  v.movement_type::public.movement_type,
  v.description, v.instructions, v.tips, v.image_url, v.thumbnail_url,
  'RepDB (repdb.co)', 'Free tier - commercial in-app use with attribution'
from (values
  ('Extensión de Tríceps por Encima de la Cabeza con Barra Z', 'ez-bar-overhead-extension', 'triceps', NULL, 'barbell', 'intermediate', 'isolation', 'Extensión de tríceps por encima de la cabeza con barra Z — el agarre angulado es más cómodo para las muñecas que una barra recta y mantiene la cabeza larga bajo un estiramiento profundo.', ARRAY['Ponte de pie o siéntate sujetando la barra Z por encima de la cabeza con agarre prono en las curvas internas.','Brazos completamente extendidos con la barra sobre la cabeza.','Dobla solo los codos para bajar la barra detrás de la cabeza en un arco.','Mantén los brazos verticales y cerca de la cabeza; solo los antebrazos se mueven.','Extiende los codos para volver la barra a la posición inicial.','Repite el número de repeticiones recomendado.'], ARRAY['Si los codos se abren hacia afuera, baja el peso — significa que los hombros están ayudando.','Cuanto más profundo sea el estiramiento en la parte inferior, mayor será el estímulo de hipertrofia en la cabeza larga.','La versión sentada es más cómoda para la zona lumbar.'], '/exercises/ez-bar-overhead-extension-main.webp', '/exercises/ez-bar-overhead-extension-main.webp'),
  ('Pullover con Barra EZ', 'ez-bar-pullover', 'back', ARRAY['core','triceps'], 'barbell', 'intermediate', 'compound', 'Este ejercicio compuesto trabaja los dorsales y pectorales extendiendo los brazos por encima de la cabeza con una barra EZ, promoviendo la fuerza y la hipertrofia del tren superior.', ARRAY['Acuéstate boca arriba en un banco plano con la cabeza ligeramente fuera del extremo, sosteniendo una barra EZ con agarre pronado.','Extiende la barra directamente sobre tu pecho, manteniendo una ligera flexión en los codos.','Baja lentamente la barra en un arco detrás de tu cabeza, sintiendo un estiramiento en tus dorsales y pecho.','Jala la barra de regreso a la posición inicial usando tus dorsales y pectorales.','Mantén el control durante todo el movimiento, evitando el impulso.'], ARRAY['Mantén tu core contraído para evitar arquear excesivamente la espalda baja.','Concéntrate en un estiramiento profundo en la parte inferior del movimiento.','Usa un compañero para cargas más pesadas y asegurar la seguridad.','Controla la fase excéntrica (descenso) para una máxima activación muscular.'], '/exercises/ez-bar-pullover-main.webp', '/exercises/ez-bar-pullover-main.webp'),
  ('Curl Inverso con Barra Z', 'ez-bar-reverse-curl', 'biceps', NULL, 'barbell', 'beginner', 'isolation', 'Un curl inverso con barra Z que trabaja el braquial y los extensores del antebrazo con un agarre cómodo.', ARRAY['Sujeta una barra Z con agarre prono.','Sube la barra hacia tus hombros.','Baja de forma controlada.','Repite.'], ARRAY['Mantén los codos cerca del torso.','La barra Z reduce la tensión en las muñecas.'], '/exercises/ez-bar-reverse-curl-main.webp', '/exercises/ez-bar-reverse-curl-main.webp'),
  ('Remo con Barra EZ y Agarre Supino', 'ez-bar-reverse-grip-row', 'biceps', ARRAY['shoulders','back','traps'], 'barbell', 'intermediate', 'compound', 'Este ejercicio compuesto de tracción trabaja el dorsal ancho y el bíceps, desarrollando eficazmente el grosor de la espalda y la fuerza de los brazos con un agarre supinado.', ARRAY['Ponte de pie con los pies al ancho de los hombros, sujetando una barra EZ con un agarre supino al ancho de los hombros.','Inclínate desde las caderas, manteniendo una ligera flexión de rodillas y la espalda recta, hasta que tu torso esté casi paralelo al suelo.','Deja que la barra cuelgue directamente debajo de tus hombros con los brazos completamente extendidos.','Tira de la barra hacia tu abdomen inferior, apretando los omóplatos y llevando los codos hacia arriba.','Controla la fase excéntrica, bajando lentamente la barra a la posición inicial con los brazos completamente extendidos.'], ARRAY['Mantén una columna vertebral neutra durante todo el movimiento para proteger tu espalda baja.','Concéntrate en iniciar la tracción con los dorsales, no solo con los bíceps.','Evita encogerte de hombros; manténlos deprimidos y retraídos.','Utiliza un rango completo de movimiento, extendiendo los brazos por completo en la parte inferior.'], '/exercises/ez-bar-reverse-grip-row-main.webp', '/exercises/ez-bar-reverse-grip-row-main.webp'),
  ('Peso Muerto Rumano con Barra Z', 'ez-bar-romanian-deadlift', 'glutes', ARRAY['back','forearms','traps'], 'barbell', 'beginner', 'compound', 'Un peso muerto rumano con barra Z. El agarre angulado es más cómodo para las muñecas y es ideal para trabajo de bisagra ligero o personas con codos sensibles.', ARRAY['De pie, sujeta la barra Z a la altura media del muslo con agarre prono en las curvas internas.','Pies a la anchura de las caderas, rodillas ligeramente flexionadas, pecho arriba y dorsales activados.','Empuja las caderas hacia atrás dejando que la barra deslice por la parte delantera de las piernas.','Baja hasta sentir un estiramiento profundo en los isquiotibiales sin redondear la zona lumbar.','Impulsa las caderas hacia adelante para volver a la posición erguida, manteniendo la barra cerca del cuerpo.','Repite el número de repeticiones recomendado.'], ARRAY['El movimiento es una bisagra de cadera, no una sentadilla: las rodillas apenas se doblan.','La barra Z es más corta que una barra recta; agarra las curvas internas para una posición de muñeca casi neutra.','Detente en el límite inferior de tu rango de movimiento limpio: sin estiramiento con la espalda redondeada.'], '/exercises/ez-bar-romanian-deadlift-main.webp', '/exercises/ez-bar-romanian-deadlift-main.webp'),
  ('Encogimiento de Hombros con Barra Z', 'ez-bar-shrug', 'traps', ARRAY['back'], 'barbell', 'beginner', 'isolation', 'Un encogimiento de hombros con barra Z para un agarre cómodo mientras se carga el trapecio.', ARRAY['De pie, sujeta la barra Z frente a ti.','Encoge los hombros directamente hacia arriba.','Mantén la posición arriba y luego baja.','Repite.'], ARRAY['Evita girar los hombros en círculos.','Usa un rango completo de movimiento.'], '/exercises/ez-bar-shrug-main.webp', '/exercises/ez-bar-shrug-main.webp'),
  ('Spider Curl con Barra Z', 'ez-bar-spider-curl', 'biceps', NULL, 'barbell', 'intermediate', 'isolation', 'Un curl con el pecho apoyado sobre un banco inclinado usando barra Z, aislando el bíceps con técnica estricta.', ARRAY['Túmbate boca abajo en un banco inclinado sujetando una barra Z con agarre supino.','Deja que tus brazos cuelguen rectos desde los hombros.','Sube la barra hacia tus hombros.','Aprieta los bíceps en la parte alta del movimiento.','Baja la barra de forma controlada.','Repite el número de repeticiones deseado.'], ARRAY['Deja los brazos colgando verticales y mantén fijos los brazos superiores.','Haz el curl solo con el bíceps: el banco elimina cualquier excusa para balancearte.','Baja hasta el estiramiento completo antes de empezar la siguiente repetición.'], '/exercises/ez-bar-spider-curl-main.webp', '/exercises/ez-bar-spider-curl-main.webp'),
  ('Remo al Mentón con Barra Z', 'ez-bar-upright-row', 'shoulders', ARRAY['biceps'], 'barbell', 'intermediate', 'compound', 'Una variación del remo vertical con barra Z para una posición de muñecas más cómoda.', ARRAY['De pie, sujeta la barra Z con agarre a la anchura de los hombros en las partes anguladas.','Tira de la barra hacia arriba a lo largo del cuerpo hasta la altura del mentón.','Lidera el movimiento con los codos, manteniéndolos por encima de las manos.','Baja de forma controlada.','Repite.'], ARRAY['Mantén las muñecas relajadas, sin doblarlas hacia arriba.','Evita balancear el torso para subir la barra.','Si notas molestias en los hombros, reduce el rango o la carga.'], '/exercises/ez-bar-upright-row-main.webp', '/exercises/ez-bar-upright-row-main.webp'),
  ('Curl de Muñeca con Barra Z', 'ez-bar-wrist-curl', 'forearms', NULL, 'barbell', 'beginner', 'isolation', 'Un curl de muñeca con barra Z, más amigable con las muñecas que la barra recta.', ARRAY['Siéntate en un banco con los antebrazos sobre los muslos, palmas hacia arriba.','Sujeta una barra Z por las curvas internas a la anchura de los hombros.','Deja que la barra ruede hasta las puntas de los dedos.','Sube la barra flexionando las muñecas.','Baja con control.'], ARRAY['El ángulo de la barra Z es más amable con las muñecas.','Mueve solo la muñeca — los antebrazos permanecen quietos.','Rueda la barra a las puntas de los dedos para el rango completo.'], '/exercises/ez-bar-wrist-curl-main.webp', '/exercises/ez-bar-wrist-curl-main.webp'),
  ('Face Pull en Polea', 'face-pull', 'shoulders', ARRAY['traps'], 'cable', 'beginner', 'compound', 'Un ejercicio de cable que trabaja los deltoides posteriores y los rotadores externos.', ARRAY['Engancha una cuerda en una polea alta.','Tira de la cuerda hacia tu cara, separando los extremos.','Aprieta los deltoides posteriores y los rotadores externos.','Regresa a la posición inicial de forma controlada.','Repite.'], ARRAY['Mantén los codos altos, alineados con los hombros.','Junta las escápulas al final de cada repetición.','Trabaja con peso ligero para no perder la técnica.'], '/exercises/face-pull-main.webp', '/exercises/face-pull-main.webp'),
  ('Postura del Pez', 'fish-pose', 'back', ARRAY['shoulders','core'], NULL, 'intermediate', 'mobility', 'Una extensión boca arriba apoyada en los antebrazos, con el pecho elevado y la cabeza inclinada atrás, que abre la parte frontal del pecho y la garganta.', ARRAY['Túmbate boca arriba con las piernas estiradas y los brazos junto al cuerpo, las palmas bajo las caderas.','Presiona los antebrazos contra el suelo y eleva el pecho hacia el techo.','Deja que la coronilla apoye ligeramente en el suelo sin cargar peso en el cuello.','Mantén la posición durante el tiempo indicado, respirando hacia la parte alta del pecho.','Levanta la cabeza y baja la espalda al suelo.'], ARRAY['El peso va en los antebrazos, no en la cabeza; el cuello solo guía la posición.','Coloca un bloque a lo largo bajo la espalda alta si la versión en el suelo pincha.','Mantén las piernas activas y los muslos rotando ligeramente hacia dentro.'], '/exercises/fish-pose-main.webp', '/exercises/fish-pose-main.webp'),
  ('Press en Suelo con Barra Z', 'floor-ez-bar-press', 'chest', ARRAY['shoulders','triceps'], 'barbell', 'intermediate', 'compound', 'Una variación del press en suelo con barra Z para una posición más cómoda de muñecas y codos.', ARRAY['Túmbate en el suelo sujetando una barra Z sobre el pecho.','Baja la barra hasta que los codos toquen el suelo.','Empuja de vuelta hasta la extensión completa.','Repite.'], ARRAY['La barra Z reduce la tensión en las muñecas en comparación con una barra recta.','Mantén los pies planos sobre el suelo.'], '/exercises/floor-ez-bar-press-main.webp', '/exercises/floor-ez-bar-press-main.webp'),
  ('Pullover con Pesa Rusa en Suelo', 'floor-kettlebell-pullover', 'back', ARRAY['core','triceps'], 'kettlebell', 'beginner', 'compound', 'Un pullover realizado tumbado en el suelo con una pesa rusa sujetada por el asa o por las asas laterales. El suelo limita el rango de movimiento en comparación con la versión en banco, lo que reduce la tensión en los hombros y lo convierte en una buena opción para entrenar en casa o como ejercicio de prehabilitación.', ARRAY['Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies planos.','Sujeta una pesa rusa por el asa con ambas manos sobre el pecho, brazos casi extendidos (ligera flexión de codos).','Manteniendo el ángulo de los codos fijo, baja la pesa hacia atrás en arco hasta que los brazos toquen el suelo.','Tira de la pesa de vuelta sobre el pecho siguiendo el mismo arco.','Repite el número de repeticiones recomendado.'], ARRAY['El suelo limita el rango de movimiento; si te parece demasiado corto, usa la versión en banco.','Agarra el asa con firmeza y aprieta los dorsales en la parte alta.','Mantén la zona lumbar pegada al suelo durante todo el ejercicio.'], '/exercises/floor-kettlebell-pullover-main.webp', '/exercises/floor-kettlebell-pullover-main.webp'),
  ('Press en Suelo', 'floor-press', 'chest', ARRAY['shoulders','triceps'], 'barbell', 'intermediate', 'compound', 'Un movimiento de press con barra realizado en el suelo, limitando el rango de movimiento y eliminando la participación del tren inferior.', ARRAY['Túmbate en el suelo y colócate bajo una barra en el rack.','Baja la barra hasta el pecho hasta que los codos toquen el suelo.','Empuja de vuelta hasta el bloqueo.','Repite.'], ARRAY['El contacto de los codos con el suelo proporciona un punto de parada natural.','Útil para trabajar la debilidad en la fase final de extensión.'], '/exercises/floor-press-main.webp', '/exercises/floor-press-main.webp'),
  ('Flutter Kicks', 'flutter-kicks', 'core', NULL, NULL, 'intermediate', 'compound', 'Un ejercicio de core tumbado boca arriba alternando pequeñas patadas arriba y abajo mientras la zona lumbar permanece pegada al suelo.', ARRAY['Túmbate boca arriba con las piernas extendidas.','Coloca las manos bajo los glúteos como apoyo.','Levanta ambas piernas unos centímetros del suelo.','Alterna las piernas arriba y abajo en un rango pequeño.','Mantén el core contraído y la zona lumbar presionada contra el suelo.','Continúa durante el tiempo o las repeticiones deseadas.'], ARRAY['Presiona la zona lumbar contra el suelo durante toda la serie.','Mantén las patadas pequeñas y constantes en lugar de grandes y descontroladas.','Eleva más las piernas si notas que la zona lumbar se arquea.'], '/exercises/flutter-kicks-main.webp', '/exercises/flutter-kicks-main.webp'),
  ('Front Lever', 'front-lever', 'back', ARRAY['shoulders','biceps','core'], 'bodyweight', 'advanced', 'compound', 'Una posición estática avanzada en barra donde el cuerpo se mantiene horizontal con el pecho hacia arriba, requiriendo fuerza de tracción en dorsales y core.', ARRAY['Agarra la barra con agarre prono y cuelga.','Lleva las rodillas al pecho y eleva las caderas hacia arriba, rotando hasta que el pecho mire al techo.','Extiende el cuerpo horizontalmente con brazos rectos y pecho apuntando hacia arriba.','Mantén el cuerpo rígido y paralelo al suelo.','Aguanta el tiempo deseado, luego flexiona y baja de forma controlada.'], ARRAY['Progresa con variantes de rodillas flexionadas y piernas abiertas antes del hold completo.','Aprieta core y glúteos para evitar que las caderas caigan.','Mantén los hombros activamente deprimidos, alejados de las orejas.'], '/exercises/front-lever-main.webp', '/exercises/front-lever-main.webp'),
  ('Sentadilla Frontal', 'front-squat', 'glutes', ARRAY['back','hamstrings'], 'barbell', 'intermediate', 'compound', 'Una sentadilla con barra sostenida al frente sobre los deltoides, enfatizando cuádriceps y core.', ARRAY['Limpia o coloca la barra en los deltoides frontales con los codos altos.','Baja en sentadilla manteniendo el torso erguido hasta que los muslos estén paralelos al suelo.','Vuelve a subir.','Repite.'], ARRAY['Mantén los codos altos para estabilizar la barra.','Un torso más vertical aumenta la activación de los cuádriceps.'], '/exercises/front-squat-main.webp', '/exercises/front-squat-main.webp'),
  ('Postura de la Guirnalda', 'garland-pose', 'adductors', ARRAY['quads','calves'], NULL, 'beginner', 'mobility', 'Una sentadilla profunda sostenida con los talones apoyados y los codos empujando las rodillas hacia fuera, usada para abrir caderas, tobillos y zona lumbar.', ARRAY['Ponte de pie con los pies algo más separados que las caderas y las puntas ligeramente hacia fuera.','Baja en cuclillas todo lo que permitan los tobillos, manteniendo los talones en el suelo.','Junta las palmas frente al pecho y presiona los codos contra la cara interna de las rodillas.','Mantén la posición durante el tiempo indicado, con el pecho alto y la columna larga.','Empuja con los pies para volver a ponerte de pie.'], ARRAY['Coloca una toalla enrollada bajo los talones si se levantan; forzarlos redondea la zona lumbar.','Abre más los pies para dejar espacio a la pelvis en lugar de encajarte en una sentadilla estrecha.','Presiona ligeramente rodillas y codos entre sí para que el pecho no se hunda.'], '/exercises/garland-pose-main.webp', '/exercises/garland-pose-main.webp')
) as v(name, slug, muscle_slug, secondary_slugs, equipment_slug, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url)
on conflict (slug) do nothing;
-- Imported from RepDB (repdb.co) free tier, https://github.com/RepDB/exercise-dataset.
-- License: free for personal/commercial in-app use with attribution (see LICENSE-DATA.md
-- in that repo). Images copied into /public/exercises. Idempotent via ON CONFLICT (slug).
insert into public.exercises (name, slug, primary_muscle_group_id, secondary_muscle_group_ids, equipment_id, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url, image_source, image_license)
select v.name, v.slug,
  (select id from public.muscle_groups where slug = v.muscle_slug),
  coalesce((select array_agg(id) from public.muscle_groups where slug = any(v.secondary_slugs)), '{}'),
  (select id from public.equipment where slug = v.equipment_slug),
  v.difficulty::public.exercise_difficulty,
  v.movement_type::public.movement_type,
  v.description, v.instructions, v.tips, v.image_url, v.thumbnail_url,
  'RepDB (repdb.co)', 'Free tier - commercial in-app use with attribution'
from (values
  ('Puente de Glúteos', 'glute-bridge', 'glutes', ARRAY['hamstrings'], NULL, 'beginner', 'isolation', 'Un ejercicio de activación de glúteos con el peso corporal realizado tumbado en el suelo.', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies planos en el suelo.','Eleva las caderas apretando los glúteos.','Mantén brevemente en la parte alta con las caderas totalmente extendidas.','Baja las caderas de forma controlada.','Repite.'], ARRAY['Empuja con los talones para activar mejor los glúteos.','Evita arquear la zona lumbar al extender las caderas.','Mantén las rodillas alineadas con los pies durante todo el recorrido.'], '/exercises/glute-bridge-main.webp', '/exercises/glute-bridge-main.webp'),
  ('Puente de Glúteos Isométrico', 'glute-bridge-hold', 'glutes', ARRAY['hamstrings'], NULL, 'beginner', 'isolation', 'La parte alta del puente de glúteos mantenida en el tiempo: la cadera queda completamente extendida con hombros, caderas y rodillas en línea, de modo que los glúteos permanecen bajo tensión en lugar de encadenar repeticiones.', ARRAY['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados, separados a la anchura de las caderas y lo bastante cerca como para rozar los talones con los dedos.','Empuja con los talones y eleva la cadera hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros.','Aprieta los glúteos y lleva las costillas hacia abajo para que la zona lumbar no tome el mando.','Mantén la posición alta durante el tiempo indicado, con el peso en los talones.','Baja la cadera de forma controlada para terminar la serie.'], ARRAY['Empuja ligeramente las rodillas hacia fuera durante el mantenimiento para que los glúteos sigan activos.','Deja de subir cuando la cadera quede a la altura de las rodillas; más arriba suele significar arquear la espalda.','Para añadir carga, apoya una mancuerna o un disco sobre la cadera antes de elevarla.'], '/exercises/glute-bridge-hold-main.webp', '/exercises/glute-bridge-hold-main.webp'),
  ('Patada de Glúteo', 'glute-kickback', 'glutes', ARRAY['back','hamstrings'], NULL, 'beginner', 'isolation', 'Un ejercicio de aislamiento de glúteos con peso corporal en posición de cuatro puntos para desarrollar el glúteo mayor.', ARRAY['Comienza a cuatro patas con las manos bajo los hombros y las rodillas bajo las caderas.','Manteniendo la rodilla doblada a 90 grados, empuja el talón hacia el techo.','Aprieta el glúteo en la parte superior del movimiento.','Baja la pierna a la posición inicial con control.','Completa todas las repeticiones y cambia de lado.'], ARRAY['Mantén las caderas paralelas al suelo — evita rotar.','Concéntrate en apretar el glúteo, no solo en levantar la pierna.','Agrega una banda de resistencia o cable para sobrecarga progresiva.'], '/exercises/glute-kickback-main.webp', '/exercises/glute-kickback-main.webp'),
  ('Patada de Glúteo Isométrica', 'glute-kickback-hold', 'glutes', ARRAY['back','hamstrings'], NULL, 'beginner', 'isolation', 'La posición final de la patada de glúteo mantenida en el tiempo: a cuatro apoyos con una pierna extendida hacia atrás a la altura de la cadera, la pelvis nivelada y el glúteo sosteniendo la pierna en el sitio.', ARRAY['Colócate a cuatro apoyos con las manos bajo los hombros y las rodillas bajo las caderas.','Aprieta el tronco y mantén la pelvis nivelada; no dejes que el lado que trabaja rote hacia arriba.','Extiende una pierna hacia atrás y arriba hasta que el muslo quede en línea con el torso.','Mantén esa posición durante el tiempo indicado, con el cuello largo y la zona lumbar plana.','Baja la pierna de forma controlada y repite del otro lado.'], ARRAY['Aprieta el glúteo en lugar de subir más; la altura la limita que la pelvis siga cuadrada.','Aleja del oído el hombro que te sostiene para que el tronco no se hunda.','Con la rodilla flexionada la tensión se queda en el glúteo; con la pierna estirada pasa más al isquiotibial.'], '/exercises/glute-kickback-hold-main.webp', '/exercises/glute-kickback-hold-main.webp'),
  ('Sentadilla Goblet', 'goblet-squat', 'glutes', ARRAY['hamstrings'], 'kettlebell', 'beginner', 'compound', 'Una sentadilla apta para principiantes con una pesa rusa sujetada a la altura del pecho que mejora la postura y la profundidad.', ARRAY['Sujeta una pesa rusa a la altura del pecho con ambas manos.','Baja en sentadilla manteniendo el peso cerca del pecho.','Vuelve a subir.','Repite.'], ARRAY['La posición goblet favorece de forma natural un torso erguido.','Empuja las rodillas hacia afuera en la parte baja.'], '/exercises/goblet-squat-main.webp', '/exercises/goblet-squat-main.webp'),
  ('Buenos Días', 'good-morning', 'back', NULL, 'barbell', 'intermediate', 'compound', 'Un movimiento de bisagra de cadera con barra en la espalda para el desarrollo de la cadena posterior.', ARRAY['De pie con una barra sobre la parte superior de la espalda.','Realiza una bisagra de cadera empujando las caderas hacia atrás mientras mantienes la espalda plana.','Baja el torso hasta que quede casi paralelo al suelo.','Impulsa las caderas hacia adelante para volver a la posición erguida.','Repite.'], ARRAY['Mantén una ligera flexión de rodillas durante todo el movimiento.','Empieza con la barra vacía hasta dominar la bisagra de cadera.','Si la espalda se redondea, reduce el rango de movimiento.'], '/exercises/good-morning-main.webp', '/exercises/good-morning-main.webp'),
  ('Hack Squat', 'hack-squat', 'glutes', ARRAY['calves','hamstrings'], 'machine', 'intermediate', 'compound', 'Un ejercicio guiado en la máquina hack squat que trabaja principalmente los cuádriceps mediante un patrón de sentadilla controlado sobre el trineo.', ARRAY['Carga la máquina hack squat y colócate con la espalda y los hombros contra los almohadillados.','Sitúa los pies a la anchura de los hombros sobre la plataforma con los pies ligeramente girados hacia fuera.','Suelta los asideros de seguridad y baja el trineo flexionando rodillas y caderas.','Desciende hasta que los muslos estén al menos paralelos a la plataforma.','Empuja con los talones para extender las piernas y devolver el trineo a la posición inicial.','Vuelve a enganchar los asideros de seguridad al terminar la serie.'], ARRAY['Mantén la zona lumbar pegada al almohadillado durante todo el movimiento.','Colocar los pies más arriba en la plataforma desplaza el énfasis hacia glúteos e isquiotibiales.','Controla la bajada; no te impulses desde el punto más bajo.'], '/exercises/hack-squat-main.webp', '/exercises/hack-squat-main.webp'),
  ('Elevación de Talones en Máquina Hack Squat', 'hack-squat-calf-raise', 'calves', NULL, 'machine', 'intermediate', 'isolation', 'Una elevación de talones en la máquina de sentadilla hack, cargando los gemelos con mucho peso sin tener que equilibrar una barra.', ARRAY['Colócate en la máquina hack squat con los hombros bajo los apoyos.','Apoya los metatarsos en la plataforma con los talones colgando.','Mantén las piernas rectas con una ligera flexión de rodillas.','Empuja con los metatarsos para elevar los talones.','Baja los talones por debajo de la plataforma para hacer el estiramiento.','Repite el número de repeticiones deseado.'], ARRAY['Sube tan alto como puedas sobre las puntas de los pies.','Haz una pausa en el estiramiento inferior en lugar de rebotar.','Mantén las rodillas rectas pero sin bloquear para conservar la tensión en los gemelos.'], '/exercises/hack-squat-calf-raise-main.webp', '/exercises/hack-squat-calf-raise-main.webp'),
  ('Balanceo de Flexor de Cadera en Media Rodilla', 'half-kneeling-hip-flexor-rock', 'core', ARRAY['glutes','quads'], NULL, 'beginner', 'mobility', 'La versión dinámica del estiramiento de flexor de cadera de rodillas: desde media rodilla las caderas se balancean hacia el estiramiento y vuelven, repetido en lugar de mantenido.', ARRAY['Apóyate sobre una rodilla con el otro pie plano en el suelo por delante.','Mete ligeramente el coxis y aprieta el tronco para que la zona lumbar quede neutra.','Balancea las caderas hacia delante hasta notar el alargamiento en la parte frontal del muslo trasero.','Vuelve de forma controlada y repite con ritmo.','Cambia de lado y repite el mismo número de veces.'], ARRAY['Mantén el movimiento en las caderas; si la zona lumbar se arquea, acorta el recorrido.','Aprieta el glúteo de la pierna arrodillada durante el balanceo hacia delante.','Acolcha la rodilla de apoyo con una esterilla doblada si el suelo es duro.'], '/exercises/half-kneeling-hip-flexor-rock-main.webp', '/exercises/half-kneeling-hip-flexor-rock-main.webp'),
  ('Postura de la Media Luna', 'half-moon-pose', 'glutes', ARRAY['back','quads'], NULL, 'advanced', 'compound', 'Un equilibrio lateral de pie sobre una pierna y una mano, con la pierna de arriba elevada a la altura de la cadera y el pecho abierto hacia el techo.', ARRAY['Desde una base amplia, flexiona la rodilla delantera y apoya la mano de abajo en el suelo o un bloque por delante de ese pie.','Desplaza el peso hacia delante y eleva la pierna trasera hasta dejarla paralela al suelo.','Estira la pierna de apoyo y apila la cadera de arriba sobre la de abajo, con el brazo superior hacia el techo.','Mantén el equilibrio durante el tiempo indicado, con el pie elevado en flexión.','Baja el pie trasero y repite del otro lado.'], ARRAY['Usa un bloque bajo la mano de abajo; llegar al suelo no es el objetivo de la postura.','Empuja el talón elevado hacia la pared de detrás para mantener la pierna activa.','Mira al suelo en lugar de hacia arriba si el equilibrio se rompe una y otra vez.'], '/exercises/half-moon-pose-main.webp', '/exercises/half-moon-pose-main.webp'),
  ('Flexiones en Pino', 'handstand-push-ups', 'shoulders', ARRAY['core','traps'], NULL, 'advanced', 'compound', 'Un empuje invertido contra la pared, bajando la cabeza hacia el suelo y empujando de vuelta hasta el pino completo.', ARRAY['Sube a un pino contra la pared con las manos a la anchura de los hombros.','Contrae el core y mantén el cuerpo recto.','Baja la cabeza hacia el suelo flexionando los codos.','Detente justo antes de que la cabeza toque el suelo.','Empuja con las manos para volver al pino completo.','Repite el número de repeticiones deseado.'], ARRAY['Mantén los codos a unos 45 grados en lugar de abrirlos por completo.','Contrae el core para que la espalda no se arquee alejándose de la pared.','Progresa primero con flexiones pike y rangos parciales.'], '/exercises/handstand-push-ups-main.webp', '/exercises/handstand-push-ups-main.webp'),
  ('Cargada desde Colgante', 'hang-clean', 'glutes', ARRAY['shoulders','back','hamstrings'], 'barbell', 'intermediate', 'compound', 'Una variante de la cargada que comienza con la barra a la altura de los muslos, entrenando la triple extensión explosiva y una recepción rápida.', ARRAY['De pie, sujeta la barra con agarre a la anchura de los hombros a la altura de los muslos.','Realiza una bisagra de cadera para bajar la barra justo por encima de las rodillas.','Extiende caderas, rodillas y tobillos de forma explosiva.','Encoge los hombros y tira de la barra hacia arriba.','Recibe la barra sobre los deltoides frontales en un cuarto de sentadilla.','Ponte erguido y luego vuelve a la posición de colgante.'], ARRAY['Flexiona las caderas hasta justo por encima de las rodillas antes de explotar hacia arriba.','Encoge los hombros y tira de la barra cerca del cuerpo.','Recibe la barra sobre los hombros en un cuarto de sentadilla.'], '/exercises/hang-clean-main.webp', '/exercises/hang-clean-main.webp'),
  ('Power Clean desde Colgante', 'hang-power-clean', 'glutes', ARRAY['back','hamstrings'], 'barbell', 'intermediate', 'compound', 'Una cargada desde el colgado recibida en una sentadilla parcial, que desarrolla potencia explosiva sin bajar a una sentadilla completa.', ARRAY['De pie con los pies a la anchura de las caderas sujetando la barra a la altura de los muslos.','Realiza una bisagra de cadera para bajar la barra justo por encima de las rodillas.','Extiende caderas y piernas de forma explosiva.','Tira de la barra hacia arriba y recíbela sobre los deltoides frontales en una sentadilla parcial.','Ponte erguido con la barra apoyada en los hombros.','Baja la barra de vuelta a la posición de colgante.'], ARRAY['Impulsa con caderas y piernas antes de que tiren los brazos.','Recibe la barra con los muslos por encima de la paralela.','Mantén la espalda plana al flexionar hacia la posición inicial.'], '/exercises/hang-power-clean-main.webp', '/exercises/hang-power-clean-main.webp'),
  ('Elevación de Rodillas Colgado', 'hanging-knee-raise', 'core', ARRAY['forearms'], 'bodyweight', 'beginner', 'compound', 'Un ejercicio de core colgado de una barra que trabaja el abdomen bajo y los flexores de cadera con rodillas dobladas.', ARRAY['Cuélgate de una barra con agarre prono y los brazos completamente extendidos.','Activa el core y sube las rodillas hacia el pecho.','Mantén brevemente arriba.','Baja las piernas despacio a la posición inicial.','Repite el número de repeticiones deseado.'], ARRAY['Evita el balanceo — inicia el movimiento desde el core.','Exhala al subir las rodillas.','Progresa a elevaciones de piernas rectas cuando esto resulte fácil.'], '/exercises/hanging-knee-raise-main.webp', '/exercises/hanging-knee-raise-main.webp'),
  ('Pike Colgado', 'hanging-pike', 'core', ARRAY['forearms','back'], 'bodyweight', 'advanced', 'compound', 'Una elevación de piernas estricta colgado de la barra hasta tocarla: las piernas se mantienen rectas y los pies suben hasta las manos.', ARRAY['Cuélgate de una barra de dominadas con agarre prono a la anchura de los hombros.','Activa los dorsales y contrae el core para crear un cuerpo hueco.','Manteniendo las piernas completamente rectas, súbelas en un arco suave hasta la barra.','Intenta tocar los pies a la barra entre las manos.','Baja las piernas lentamente a la posición de cuelgue y repite.'], ARRAY['Sin balanceo: cada repetición empieza desde un cuelgue muerto con el tronco activado.','Si el rango completo es demasiado difícil, sube solo hasta la horizontal y ve progresando.'], '/exercises/hanging-pike-main.webp', '/exercises/hanging-pike-main.webp'),
  ('Postura del Bebé Feliz', 'happy-baby', 'adductors', ARRAY['back','hamstrings'], NULL, 'beginner', 'mobility', 'Una apertura de cadera boca arriba en la que las rodillas se acercan a las axilas y los pies se sujetan por fuera, liberando la cara interna de los muslos y la zona lumbar.', ARRAY['Túmbate boca arriba y acerca ambas rodillas al pecho.','Agarra los bordes externos de los pies, o las espinillas si los pies quedan lejos.','Abre las rodillas más allá de las costillas y coloca los tobillos sobre las rodillas, con las plantas hacia arriba.','Empuja suavemente los pies contra las manos y mantén durante el tiempo indicado, con la zona lumbar en el suelo.','Suelta los pies y baja las piernas.'], ARRAY['Mantén el coxis pesado en el suelo en lugar de rodar hacia la espalda alta.','Agarra las espinillas o usa una cinta si el agarre despega los hombros de la esterilla.','Balancéate suavemente de lado a lado si notas tensión en la zona lumbar.'], '/exercises/happy-baby-main.webp', '/exercises/happy-baby-main.webp'),
  ('Postura de Cabeza a la Rodilla', 'head-to-knee-pose', 'back', ARRAY['adductors','glutes'], NULL, 'beginner', 'mobility', 'Una flexión sentada sobre una pierna: una queda estirada y el otro pie se apoya en la cara interna del muslo, de modo que el isquiotibial se alarga de lado en lado.', ARRAY['Siéntate con una pierna estirada al frente y la otra rodilla abierta al lado, con ese pie en la cara interna del muslo.','Gira el pecho hacia la pierna estirada para que el ombligo quede alineado con el muslo.','Bascula desde las caderas y alcanza hacia delante a lo largo de la pierna con la columna larga.','Mantén la flexión durante el tiempo indicado, respirando hacia la parte posterior de la pierna.','Sube con la espalda plana y repite del otro lado.'], ARRAY['Siéntate sobre una manta doblada para que la pelvis pueda bascular en lugar de redondear la espalda.','Mantén los dedos del pie estirado apuntando hacia arriba en lugar de dejarlos caer hacia fuera.','Usa una cinta alrededor del pie cuando las manos no lleguen con comodidad.'], '/exercises/head-to-knee-pose-main.webp', '/exercises/head-to-knee-pose-main.webp'),
  ('Sentadilla con Talones Elevados', 'heel-elevated-squat', 'glutes', ARRAY['adductors','back','hamstrings'], 'barbell', 'intermediate', 'compound', 'Una variante de sentadilla con los talones elevados sobre discos para enfatizar los cuádriceps y mejorar la profundidad.', ARRAY['Coloca discos de peso o una cuña bajo los talones, pies al ancho de los hombros.','Sostén una barra en la parte superior de la espalda o mancuernas a los lados.','Activa el core y baja en sentadilla manteniendo el torso erguido.','Baja hasta que los muslos estén paralelos al suelo o más abajo.','Empuja a través de los pies para volver a la posición inicial.'], ARRAY['Los talones elevados permiten un torso más erguido y mayor recorrido de rodilla.','Mantén las rodillas alineadas con los dedos del pie durante todo el movimiento.','Comienza con una elevación pequeña y auméntala a medida que mejore la movilidad.'], '/exercises/heel-elevated-squat-main.webp', '/exercises/heel-elevated-squat-main.webp')
) as v(name, slug, muscle_slug, secondary_slugs, equipment_slug, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url)
on conflict (slug) do nothing;
-- Imported from RepDB (repdb.co) free tier, https://github.com/RepDB/exercise-dataset.
-- License: free for personal/commercial in-app use with attribution (see LICENSE-DATA.md
-- in that repo). Images copied into /public/exercises. Idempotent via ON CONFLICT (slug).
insert into public.exercises (name, slug, primary_muscle_group_id, secondary_muscle_group_ids, equipment_id, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url, image_source, image_license)
select v.name, v.slug,
  (select id from public.muscle_groups where slug = v.muscle_slug),
  coalesce((select array_agg(id) from public.muscle_groups where slug = any(v.secondary_slugs)), '{}'),
  (select id from public.equipment where slug = v.equipment_slug),
  v.difficulty::public.exercise_difficulty,
  v.movement_type::public.movement_type,
  v.description, v.instructions, v.tips, v.image_url, v.thumbnail_url,
  'RepDB (repdb.co)', 'Free tier - commercial in-app use with attribution'
from (values
  ('Marcha en Tándem', 'heel-to-toe-walk', 'glutes', ARRAY['calves','quads','core'], NULL, 'beginner', 'compound', 'Un ejercicio de equilibrio y coordinación caminando sobre una línea imaginaria, colocando el talón de cada paso justo contra los dedos del otro pie para que la base de apoyo se reduzca casi a nada.', ARRAY['Elige una línea recta en el suelo, colócate sobre ella y extiende los brazos a los lados a la altura de los hombros.','Da un paso al frente y coloca el talón justo delante de los dedos del pie de apoyo, en contacto con ellos.','Pasa el peso al pie delantero de forma controlada y haz una pausa breve antes del siguiente paso.','Lleva el pie de atrás hacia delante y colócalo de nuevo talón contra dedos, sin salirte de la línea.','Fija la vista en un punto al frente en lugar de mirarte los pies, y corrige los desequilibrios con los brazos.','Camina el número de pasos deseado, luego date la vuelta y regresa.'], ARRAY['Ve despacio. Si te apresuras acabas caminando normal sobre una línea estrecha y desaparece por completo la exigencia de equilibrio.','Si no consigues mantener la línea, camina junto a una pared y tócala solo cuando lo necesites — eso es una regresión, no un fracaso.','Súbele la dificultad cruzando los brazos sobre el pecho, y todavía más haciéndolo con los ojos cerrados cerca de una pared.'], '/exercises/heel-to-toe-walk-main.webp', '/exercises/heel-to-toe-walk-main.webp'),
  ('Postura del Héroe', 'hero-pose', 'quads', ARRAY['back','core'], NULL, 'beginner', 'mobility', 'Un sentado de rodillas en el que las caderas descienden entre los talones, alargando el cuádriceps y la parte frontal de los tobillos mientras la columna se mantiene erguida.', ARRAY['Arrodíllate con las rodillas juntas y los pies algo más separados que las caderas, con el empeine apoyado.','Baja las caderas entre los talones, usando un bloque o cojín si el suelo queda lejos.','Alinea las costillas sobre la pelvis y apoya las manos en los muslos.','Mantén el sentado durante el tiempo indicado, con el peso repartido entre ambos isquiones.','Sal apoyándote en las manos y estirando una pierna cada vez.'], ARRAY['Siéntate sobre un bloque en cuanto las rodillas protesten; la altura forma parte normal de la postura.','Coloca una toalla enrollada bajo los tobillos si notas tensión en su parte frontal.','Mantén los pies apuntando hacia atrás en lugar de abrirlos hacia los lados.'], '/exercises/hero-pose-main.webp', '/exercises/hero-pose-main.webp'),
  ('Peso Muerto con Barra Hexagonal', 'hex-bar-deadlift', 'back', ARRAY['forearms','hamstrings','traps'], 'barbell', 'intermediate', 'compound', 'Un peso muerto de pie dentro de una barra hexagonal, manteniendo la carga centrada para un tirón más erguido y amable con la espalda.', ARRAY['Colócate dentro de una barra trampa cargada con los pies a la anchura de los hombros.','Flexiona caderas y rodillas para agarrar las asas.','Contrae el core y mantén la espalda plana.','Empuja con los talones y extiende caderas y rodillas para ponerte erguido.','Bloquea en la parte alta con los hombros hacia atrás.','Baja la barra al suelo de forma controlada.'], ARRAY['Mantén el pecho arriba y la espalda plana mientras ajustas el agarre.','Empuja el suelo en lugar de tirar de la barra con la espalda.','Ponte completamente erguido arriba sin inclinarte hacia atrás.'], '/exercises/hex-bar-deadlift-main.webp', '/exercises/hex-bar-deadlift-main.webp'),
  ('Prensa de piernas con pies altos', 'high-foot-leg-press', 'glutes', ARRAY['hamstrings','quads'], 'machine', 'beginner', 'compound', 'Una prensa de piernas con los pies colocados altos en la plataforma, que desplaza más trabajo hacia la extensión de cadera y el glúteo mayor con la espalda apoyada.', ARRAY['Ajusta el respaldo para que la zona lumbar permanezca apoyada y la pelvis no se redondee al bajar.','Coloca ambos pies altos y aproximadamente al ancho de los hombros, alineando rodillas y puntas de los pies.','Baja el carro flexionando caderas y rodillas hasta una profundidad cómoda sin despegar la zona lumbar del respaldo.','Empuja con todo el pie y extiende caderas y rodillas sin bloquearlas con fuerza.','Baja el carro bajo control y repite el número deseado de repeticiones.'], ARRAY['Mantén la pelvis pesada contra el respaldo; una posición alta de los pies no justifica redondear la espalda baja.','Mantén los talones y todo el pie apoyados en lugar de empujar solo con los dedos.','Elige una profundidad que conserve la posición de la pelvis.'], '/exercises/high-foot-leg-press-main.webp', '/exercises/high-foot-leg-press-main.webp'),
  ('Rodillas Altas', 'high-knees', 'core', ARRAY['calves'], NULL, 'beginner', 'cardio', 'Un ejercicio cardio con peso corporal en el que las rodillas suben a la altura de la cadera en alternancia rápida.', ARRAY['Mantente erguido con los pies a la anchura de las caderas.','Lleva una rodilla arriba hacia el pecho bombeando el brazo opuesto.','Cambia de pierna rápidamente, espejando la acción del brazo.','Continúa alternando a ritmo rápido.','Continúa durante el intervalo de trabajo indicado.'], ARRAY['Sube las rodillas al menos a la altura de la cadera.','Mantente ligero sobre las puntas de los pies.','Mantén el torso erguido — no te eches atrás.'], '/exercises/high-knees-main.webp', '/exercises/high-knees-main.webp'),
  ('Plancha Alta', 'high-plank', 'core', ARRAY['back'], NULL, 'beginner', 'compound', 'Una variación de plancha con los brazos totalmente extendidos en posición de push-up.', ARRAY['Empieza en posición de push-up con los brazos totalmente extendidos.','Mantén el cuerpo en línea recta de cabeza a talones.','Contrae el core y mantén la posición.','Respira de forma regular durante el ejercicio.'], ARRAY['Coloca las manos directamente debajo de los hombros.','Aprieta glúteos y abdomen para que la cadera no caiga.','Mira al suelo para mantener el cuello neutro.'], '/exercises/high-plank-main.webp', '/exercises/high-plank-main.webp'),
  ('Abducción de Cadera en Máquina', 'hip-abduction', 'glutes', ARRAY['abductors'], 'machine', 'beginner', 'isolation', 'Un ejercicio en máquina que trabaja los músculos de la cadera externa.', ARRAY['Siéntate en la máquina de abducción de cadera con los apoyos contra la parte externa de los muslos.','Empuja las piernas hacia afuera contra la resistencia.','Mantén brevemente en el punto más amplio.','Vuelve a la posición inicial de forma controlada.','Repite.'], ARRAY['Mantén la espalda apoyada en el respaldo de la máquina.','Abre las piernas sin impulso, con un ritmo controlado.','Resiste la vuelta al centro en lugar de soltar el peso de golpe.'], '/exercises/hip-abduction-main.webp', '/exercises/hip-abduction-main.webp'),
  ('Aducción de cadera', 'hip-adduction', 'adductors', NULL, 'machine', 'intermediate', 'isolation', 'Un ejercicio en máquina apretando las piernas una contra otra frente a la resistencia, aislando y fortaleciendo los aductores de la cara interna del muslo.', ARRAY['Siéntate en la máquina de aducción de cadera con la espalda contra el respaldo.','Coloca las piernas contra las almohadillas con la máquina ajustada a un estiramiento cómodo.','Aprieta las piernas hasta que las almohadillas se junten en el centro.','Mantén brevemente la contracción en la posición completamente cerrada.','Deja que las piernas se abran de vuelta con control hasta el inicio.','Repite el número deseado de repeticiones.'], ARRAY['Elige una apertura inicial que estire sin forzar la ingle.','Recorre todo el rango a una velocidad uniforme y controlada.','No dejes que la placa de peso golpee al abrir las piernas.'], '/exercises/hip-adduction-main.webp', '/exercises/hip-adduction-main.webp'),
  ('Hip thrust con barra', 'hip-thrust', 'glutes', ARRAY['hamstrings'], 'barbell', 'intermediate', 'compound', 'Un ejercicio compuesto para glúteos que utiliza una barra apoyada sobre las caderas.', ARRAY['Siéntate en el suelo con la parte superior de la espalda contra un banco y la barra sobre las caderas.','Empuja las caderas hacia arriba hasta que los muslos queden paralelos al suelo.','Aprieta los glúteos en la parte superior.','Baja las caderas de nuevo con control.','Repite.'], ARRAY['Mantén la barbilla recogida y las costillas abajo.','Empuja a través de los talones, no de las puntas.','Evita arquear la zona lumbar en la parte alta.'], '/exercises/hip-thrust-main.webp', '/exercises/hip-thrust-main.webp'),
  ('Mantenimiento del Cuerpo Hueco', 'hollow-body-hold', 'core', NULL, NULL, 'intermediate', 'compound', 'Un mantenimiento isométrico de core de la gimnasia, que entrena la tensión de cuerpo completo con la columna en ligera forma de C.', ARRAY['Acuéstate boca arriba con los brazos extendidos sobre la cabeza y las piernas rectas.','Presiona la zona lumbar firmemente contra el suelo.','Levanta ligeramente los hombros, la cabeza y las piernas del suelo.','Mantén la posición con brazos y piernas extendidos, cuerpo en forma de plátano poco profundo.','Sostén durante el tiempo indicado.'], ARRAY['Mantén la zona lumbar pegada al suelo — si se levanta, sube más las piernas.','Mete ligeramente la barbilla para activar los abdominales superiores.','Flexiona las rodillas para escalar si la posición se rompe.'], '/exercises/hollow-body-hold-main.webp', '/exercises/hollow-body-hold-main.webp'),
  ('Prensa de piernas horizontal', 'horizontal-leg-press', 'glutes', ARRAY['hamstrings'], 'machine', 'beginner', 'compound', 'Una prensa de piernas en máquina realizada en posición horizontal, que trabaja cuádriceps, glúteos e isquiotibiales.', ARRAY['Siéntate en la máquina de prensa de piernas horizontal y coloca los pies a la anchura de los hombros.','Desbloquea la máquina y baja la plataforma hacia tu pecho.','Empuja la plataforma de vuelta a la posición inicial.','Repite.'], ARRAY['No dejes que la zona lumbar se separe del asiento.','Evita bloquear completamente las rodillas.'], '/exercises/horizontal-leg-press-main.webp', '/exercises/horizontal-leg-press-main.webp'),
  ('Human Flag', 'human-flag', 'back', ARRAY['shoulders','glutes','chest','core','triceps'], 'bodyweight', 'advanced', 'compound', 'Un sostén isométrico avanzado de calistenia con el cuerpo horizontal sobre un poste vertical, paralelo al suelo.', ARRAY['Ponte de pie cerca de un poste vertical resistente.','Agarra el poste arriba con la mano superior (en pronación) y abajo con la mano inferior (en supinación).','Impulsa las piernas hacia arriba y afuera mientras empujas con fuerza el brazo inferior contra el poste.','Extiende el cuerpo en horizontal hasta formar una línea recta paralela al suelo.','Mantén la posición con el cuerpo rígido durante el tiempo objetivo.','Baja de forma controlada.'], ARRAY['Llega a la bandera completa pasando antes por progresiones agrupada y en straddle.','El brazo inferior empuja y el superior tira; juntos equilibran la palanca.','Activa con fuerza dorsales, oblicuos y glúteos para mantenerte rígido.'], '/exercises/human-flag-main.webp', '/exercises/human-flag-main.webp'),
  ('Press en banco inclinado con barra Z', 'incline-bench-ez-bar-press', 'chest', ARRAY['shoulders','triceps'], 'barbell', 'intermediate', 'compound', 'Un press en banco inclinado con barra Z que trabaja la parte superior del pecho con un agarre cómodo para las articulaciones.', ARRAY['Ajusta el banco a 30–45 grados. Agarra la barra Z con las manos en las secciones anguladas.','Baja la barra hasta la parte superior del pecho.','Empuja de vuelta hasta la extensión completa.','Repite.'], ARRAY['La inclinación desplaza el énfasis hacia la parte superior del pectoral.','Controla el descenso para evitar tensión en los hombros.'], '/exercises/incline-bench-ez-bar-press-main.webp', '/exercises/incline-bench-ez-bar-press-main.webp'),
  ('Press en banco inclinado con barra', 'incline-bench-press', 'chest', ARRAY['shoulders','triceps'], 'barbell', 'intermediate', 'compound', 'Un movimiento de press con barra en banco inclinado que trabaja la parte superior del pecho.', ARRAY['Acuéstate en un banco inclinado a 30-45 grados.','Agarra la barra ligeramente más ancha que los hombros y desrackea.','Baja la barra hasta la parte superior del pecho.','Empuja la barra de vuelta hasta la extensión completa.','Repite.'], ARRAY['Retrae las escápulas y mantenlas pegadas al banco.','Evita rebotar la barra en el pecho.','Pide asistencia cuando trabajes con cargas pesadas.'], '/exercises/incline-bench-press-main.webp', '/exercises/incline-bench-press-main.webp'),
  ('Curl con mancuernas en banco inclinado', 'incline-db-curl', 'biceps', NULL, 'dumbbell', 'intermediate', 'isolation', 'Un curl de bíceps en banco inclinado para un mayor estiramiento de la cabeza larga.', ARRAY['Siéntate en un banco inclinado a 45 grados con mancuernas a los lados.','Deja que los brazos cuelguen rectos con las palmas hacia adelante.','Sube las mancuernas hacia los hombros.','Baja con control hasta la extensión completa.','Repite.'], ARRAY['Mantén los hombros y la espalda apoyados en el banco.','No adelantes los hombros al subir las mancuernas.','Aprovecha el estiramiento abajo con una bajada lenta.'], '/exercises/incline-db-curl-main.webp', '/exercises/incline-db-curl-main.webp'),
  ('Press con mancuernas en banco inclinado', 'incline-db-press', 'chest', ARRAY['shoulders','triceps'], 'dumbbell', 'intermediate', 'compound', 'Un movimiento de press en banco inclinado que enfatiza la parte superior del pecho.', ARRAY['Ajusta el banco a 30 grados de inclinación y siéntate con las mancuernas a la altura de los hombros.','Empuja las mancuernas hacia arriba y juntas hasta que los brazos estén completamente extendidos.','Baja las mancuernas de vuelta a la altura de los hombros con control.','Repite.'], ARRAY['Mantén los pies firmes en el suelo y las escápulas retraídas.','Evita chocar las mancuernas en la parte alta.','Baja hasta sentir un estiramiento suave en el pecho.'], '/exercises/incline-db-press-main.webp', '/exercises/incline-db-press-main.webp'),
  ('Apertura con mancuernas en banco inclinado', 'incline-dumbbell-fly', 'chest', ARRAY['shoulders','biceps'], 'dumbbell', 'intermediate', 'isolation', 'Un ejercicio de aislamiento en banco inclinado que abre las mancuernas en un arco amplio, estirando y trabajando el pecho superior.', ARRAY['Acuéstate en un banco inclinado con mancuernas sobre el pecho.','Sube las mancuernas con las palmas enfrentadas.','Mantén una ligera flexión en los codos durante todo el movimiento.','Baja las mancuernas en un arco amplio hasta sentir el estiramiento del pecho.','Aprieta el pecho para juntar las mancuernas de nuevo.','Repite el número deseado de repeticiones.'], ARRAY['Mantén una ligera flexión fija en los codos en todo momento.','Baja solo hasta donde permita un estiramiento cómodo del pecho.','Aprieta el pecho para volver a juntar las mancuernas.'], '/exercises/incline-dumbbell-fly-main.webp', '/exercises/incline-dumbbell-fly-main.webp'),
  ('Curl martillo en banco inclinado', 'incline-hammer-curl', 'biceps', ARRAY['forearms'], 'dumbbell', 'intermediate', 'isolation', 'Un curl martillo realizado en banco inclinado para mayor estiramiento y activación de la cabeza larga del bíceps.', ARRAY['Siéntate en un banco inclinado con mancuernas en agarre neutro.','Deja que los brazos cuelguen rectos.','Sube las mancuernas en un movimiento de martillo.','Baja lentamente.','Repite.'], ARRAY['La inclinación proporciona un mayor estiramiento.','Evita balancear el cuerpo.'], '/exercises/incline-hammer-curl-main.webp', '/exercises/incline-hammer-curl-main.webp')
) as v(name, slug, muscle_slug, secondary_slugs, equipment_slug, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url)
on conflict (slug) do nothing;
-- Imported from RepDB (repdb.co) free tier, https://github.com/RepDB/exercise-dataset.
-- License: free for personal/commercial in-app use with attribution (see LICENSE-DATA.md
-- in that repo). Images copied into /public/exercises. Idempotent via ON CONFLICT (slug).
insert into public.exercises (name, slug, primary_muscle_group_id, secondary_muscle_group_ids, equipment_id, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url, image_source, image_license)
select v.name, v.slug,
  (select id from public.muscle_groups where slug = v.muscle_slug),
  coalesce((select array_agg(id) from public.muscle_groups where slug = any(v.secondary_slugs)), '{}'),
  (select id from public.equipment where slug = v.equipment_slug),
  v.difficulty::public.exercise_difficulty,
  v.movement_type::public.movement_type,
  v.description, v.instructions, v.tips, v.image_url, v.thumbnail_url,
  'RepDB (repdb.co)', 'Free tier - commercial in-app use with attribution'
from (values
  ('Push-up inclinado', 'incline-push-ups', 'chest', ARRAY['shoulders','triceps'], NULL, 'beginner', 'compound', 'Una variación del push-up apta para principiantes con las manos elevadas sobre un banco o escalón.', ARRAY['Coloca las manos sobre un banco o superficie elevada, a la anchura de los hombros.','Extiende las piernas hacia atrás en posición de plancha.','Baja el pecho hacia el banco flexionando los codos.','Empuja de vuelta a la posición inicial.','Repite.'], ARRAY['Aprieta el abdomen para que la cadera no se hunda.','Cuanto más alta la superficie, más fácil el ejercicio.','Asegúrate de que el banco no se mueva antes de empezar.'], '/exercises/incline-push-ups-main.webp', '/exercises/incline-push-ups-main.webp'),
  ('Caminata en Cinta Inclinada', 'incline-treadmill-walk', 'glutes', ARRAY['calves','hamstrings'], 'machine', 'beginner', 'cardio', 'Una caminata cuesta arriba sostenida sobre una cinta inclinada, manteniendo siempre un pie en contacto con la banda para que glúteos e isquiotibiales trabajen duro casi sin impacto.', ARRAY['Arranca la banda a velocidad de caminata lenta, súbete y luego eleva la inclinación hasta la pendiente que buscas.','Camina con una zancada larga y deliberada, rodando del talón a la punta y empujando la banda hacia atrás en cada paso.','Mantente erguido e inclínate hacia la cuesta desde los tobillos, sin doblarte hacia delante por la cintura.','Mantén al menos un pie sobre la banda en todo momento — camina la cuesta, no la trotes.','Deja que los brazos se balanceen con naturalidad o apóyalos suavemente en los raíles para equilibrarte, sin descargar el peso en ellos.','Sostén la pendiente durante el tiempo deseado, luego bájala y camina en llano unos minutos para terminar.'], ARRAY['Elige una velocidad a la que todavía puedas caminar. En cuanto necesites una fase de vuelo para seguir el ritmo, baja la velocidad o la inclinación — es una caminata, no una carrera.','Colgar el peso del cuerpo de los pasamanos elimina casi todo el trabajo que la cuesta está ahí para generar; tócalos solo para equilibrarte.','Es la pendiente pronunciada la que traslada el esfuerzo del cuádriceps a glúteos e isquiotibiales, así que sube la inclinación antes que la velocidad.'], '/exercises/incline-treadmill-walk-main.webp', '/exercises/incline-treadmill-walk-main.webp'),
  ('Remo invertido', 'inverted-row', 'back', ARRAY['biceps','shoulders','core'], 'barbell', 'intermediate', 'compound', 'Un ejercicio de jalón horizontal con el peso corporal realizado bajo una barra fija, tirando del pecho hacia la barra mientras se mantiene el cuerpo rígido.', ARRAY['Coloca una barra en un rack a la altura de la cintura aproximadamente.','Acuéstate debajo y agarra la barra ligeramente más ancha que los hombros con agarre prono.','Cuélgate con los brazos extendidos, los talones en el suelo y el cuerpo recto de la cabeza a los tobillos.','Tira del pecho hacia la barra, apretando los omóplatos.','Bájate con control hasta que los brazos estén completamente extendidos.','Repite.'], ARRAY['Mantén el core contraído — sin que las caderas se hundan.','Para hacerlo más difícil, eleva los pies; para hacerlo más fácil, camina los pies hacia la barra.','Haz una breve pausa en la parte superior con el pecho contra la barra.'], '/exercises/inverted-row-main.webp', '/exercises/inverted-row-main.webp'),
  ('Flexión Lateral Isométrica de Cuello', 'isometric-neck-side', 'traps', NULL, NULL, 'beginner', 'isolation', 'Un ejercicio estático de cuello que usa la mano como resistencia contra la cabeza, trabajando el esternocleidomastoideo y los escalenos sin equipo.', ARRAY['Siéntate o ponte de pie erguido. Coloca la palma de una mano en el lado de la cabeza, por encima de la oreja.','Empuja la cabeza contra la mano resistiendo por igual con la mano: la cabeza no se mueve.','Mantén la contracción isométrica de 5 a 10 segundos.','Suelta lentamente y repite en el mismo lado durante la serie.','Cambia de lado y repite.'], ARRAY['Ajusta la presión; es un 50 % de esfuerzo, no un pulso.','Mantén la mandíbula relajada y los hombros bajos.'], '/exercises/isometric-neck-side-main.webp', '/exercises/isometric-neck-side-main.webp'),
  ('Abdominal navaja', 'jackknife-sit-up', 'core', NULL, NULL, 'intermediate', 'compound', 'Un crunch de cuerpo completo realizado desde el suelo, levantando las piernas y el torso simultáneamente para tocar las manos con los pies.', ARRAY['Acuéstate boca arriba en el suelo con los brazos extendidos por encima de la cabeza y las piernas estiradas.','Levanta simultáneamente el torso y las piernas rectas del suelo.','Lleva las manos hacia los pies mientras estos suben — encuéntralos sobre las caderas.','Baja el torso y las piernas de vuelta al suelo con control.','Repite el número recomendado de repeticiones.'], ARRAY['Brazos y piernas se mueven a la misma velocidad — evita hacer trampa levantando primero las piernas.','Si la zona lumbar se arquea al bajar, reduce la velocidad y no toques completamente el suelo.'], '/exercises/jackknife-sit-up-main.webp', '/exercises/jackknife-sit-up-main.webp'),
  ('Jefferson curl', 'jefferson-curl', 'back', ARRAY['glutes'], 'dumbbell', 'intermediate', 'compound', 'Un ejercicio de flexión espinal con carga: de pie y con un peso ligero, redondeas la columna vértebra a vértebra y la vuelves a apilar, desarrollando control segmentario y flexibilidad de isquiotibiales y erectores bajo carga.', ARRAY['Ponte de pie sujetando una mancuerna ligera con los brazos estirados, pies aproximadamente al ancho de las caderas.','Mete la barbilla y empieza a redondear la columna desde arriba, vértebra a vértebra.','Baja despacio dejando colgar el peso y manteniendo las piernas casi rectas.','Llega abajo con la espalda totalmente redondeada y un estiramiento en los isquiotibiales.','Invierte el movimiento, reapilando la columna de abajo hacia arriba hasta ponerte de pie.'], ARRAY['Usa un peso muy ligero: es un ejercicio de movilidad controlado, no un levantamiento pesado.','Redondea segmento a segmento; no bisagres desde la cadera como en un peso muerto rígido.','Muévete despacio y nunca rebotes abajo.'], '/exercises/jefferson-curl-main.webp', '/exercises/jefferson-curl-main.webp'),
  ('Saltar la Cuerda', 'jump-rope', 'calves', ARRAY['forearms','quads'], 'bodyweight', 'beginner', 'cardio', 'Un ejercicio cardio clásico que trabaja gemelos, tobillos y ritmo con una cuerda y saltos rítmicos.', ARRAY['Sujeta el mango de la cuerda en cada mano con la cuerda detrás de ti.','Balancea la cuerda sobre la cabeza y al frente en un arco fluido.','Salta justo lo suficiente para que la cuerda pase bajo los pies.','Aterriza suave sobre las puntas, rodillas ligeramente flexionadas.','Mantén un ritmo constante durante el intervalo indicado.'], ARRAY['Gira la cuerda con las muñecas, no con los hombros.','Salta bajo — apenas dos o tres centímetros del suelo.','Mantente erguido con los codos cerca del cuerpo.'], '/exercises/jump-rope-main.webp', '/exercises/jump-rope-main.webp'),
  ('Sentadilla con Salto', 'jump-squat', 'glutes', ARRAY['calves','hamstrings'], NULL, 'beginner', 'compound', 'Una sentadilla pliométrica con peso corporal donde explotas hacia arriba en un salto vertical.', ARRAY['Mantente con los pies a la anchura de los hombros.','Baja a una media sentadilla con los brazos atrás.','Explota hacia arriba, balanceando los brazos y saltando lo más alto posible.','Aterriza suave en media sentadilla para absorber el impacto.','Repite sin pausa el número de repeticiones indicado.'], ARRAY['Aterriza suave con las rodillas flexionadas.','Lanza los brazos arriba para ganar altura en el salto.','Mantén el pecho arriba — no dejes que el torso colapse.'], '/exercises/jump-squat-main.webp', '/exercises/jump-squat-main.webp'),
  ('Saltos de Tijera', 'jumping-jacks', 'calves', ARRAY['abductors','quads'], NULL, 'beginner', 'cardio', 'Este clásico ejercicio dinámico de cuerpo completo eleva la frecuencia cardíaca y trabaja pantorrillas, hombros, cuádriceps y glúteos, siendo excelente para calentar o acondicionar.', ARRAY['Ponte de pie con los pies juntos y los brazos a los lados.','Simultáneamente, salta abriendo las piernas y levantando los brazos por encima de la cabeza.','Asegúrate de que tus brazos se junten o casi se junten por encima de tu cabeza.','Salta juntando los pies de nuevo mientras bajas los brazos a los lados.','Mantén un movimiento continuo y rítmico.'], ARRAY['Aterriza suavemente sobre las puntas de los pies para absorber el impacto.','Mantén tu core activado durante todo el movimiento.','Controla tu respiración; inhala al saltar hacia afuera, exhala al saltar hacia adentro.','Aumenta la velocidad para un mayor desafío cardiovascular.'], '/exercises/jumping-jacks-main.webp', '/exercises/jumping-jacks-main.webp'),
  ('Sentadilla Búlgara con Kettlebell', 'kettlebell-bulgarian-split-squat', 'glutes', ARRAY['hamstrings'], 'kettlebell', 'intermediate', 'compound', 'Esta variación unilateral de sentadilla desarrolla fuerza, músculo y estabilidad en la parte inferior del cuerpo al elevar el pie trasero y sostener una kettlebell, apuntando principalmente a los cuádriceps y glúteos.', ARRAY['Párate de espaldas a un banco, colocando un pie sobre él detrás de ti, con los cordones hacia abajo. Sostén una kettlebell en la mano opuesta.','Mantén el torso erguido y activa tu core.','Baja tu cuerpo doblando ambas rodillas, permitiendo que tu rodilla delantera se alinee con tus dedos del pie.','Desciende hasta que tu muslo delantero esté paralelo al suelo o ligeramente por debajo, manteniendo tu rodilla trasera cerca del suelo.','Impúlsate a través del talón delantero para regresar a la posición inicial, extendiendo tus caderas y rodillas.','Completa todas las repeticiones por lado antes de cambiar.'], ARRAY['Asegúrate de que tu pie delantero esté lo suficientemente lejos del banco para permitir un rango completo de movimiento sin molestias.','Mantén tu torso erguido durante todo el movimiento para maximizar la activación de glúteos y cuádriceps.','Controla la fase excéntrica (descenso) para desarrollar fuerza y estabilidad.','Experimenta sosteniendo la kettlebell en la misma mano que la pierna que trabaja (ipsilateral) o en la mano opuesta (contralateral) para diferentes desafíos.'], '/exercises/kettlebell-bulgarian-split-squat-main.webp', '/exercises/kettlebell-bulgarian-split-squat-main.webp'),
  ('Press de Suelo con Agarre Cerrado con Pesa Rusa', 'kettlebell-close-grip-floor-press', 'triceps', ARRAY['shoulders','chest'], 'kettlebell', 'intermediate', 'compound', 'Un press de suelo con una sola pesa rusa agarrada con ambas manos juntas, que desplaza el énfasis del pecho a los tríceps.', ARRAY['Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies apoyados.','Sujeta una única pesa rusa por el asa con ambas manos juntas, con la pesa apoyada en el pecho y los codos bien pegados a las costillas.','Activa el core y empuja la pesa rusa recto hacia arriba hasta estirar del todo los brazos.','Baja de forma controlada hasta que la parte alta de los brazos toque el suelo y haz una breve pausa.','Vuelve a empujar hacia arriba hasta la extensión completa.','Repite el número de repeticiones recomendado.'], ARRAY['Mantén los codos pegados a unos 30–45 grados del torso; abrirlos lo convierte en press de pecho.','La breve pausa al tocar el suelo con los codos elimina el rebote y fuerza un empuje limpio.','Elige una pesa que puedas controlar con dos manos; el agarre estrecho no perdona si se ladea.'], '/exercises/kettlebell-close-grip-floor-press-main.webp', '/exercises/kettlebell-close-grip-floor-press-main.webp'),
  ('Curl de concentración con kettlebell', 'kettlebell-concentration-curl', 'biceps', NULL, 'kettlebell', 'beginner', 'isolation', 'Un ejercicio de aislamiento de bíceps a una mano, sentado: el codo se apoya contra la cara interna del muslo mientras se curla una kettlebell, manteniendo el brazo quieto para que el bíceps haga todo el trabajo.', ARRAY['Siéntate en un banco con los pies bien separados, sujetando una kettlebell con una mano.','Apoya la parte posterior del brazo contra la cara interna del muslo y deja colgar la kettlebell.','Curla la kettlebell hacia el hombro, manteniendo el codo fijo contra la pierna.','Contrae el bíceps arriba y luego baja despacio y de forma controlada.','Termina todas las repeticiones de un lado y cambia de brazo.'], ARRAY['Mantén el brazo fijo y quieto: solo el antebrazo se mueve.','Rota ligeramente la muñeca al curlar para una contracción máxima más fuerte.','Usa un peso más ligero que en un curl normal: aquí importa más la técnica estricta.'], '/exercises/kettlebell-concentration-curl-main.webp', '/exercises/kettlebell-concentration-curl-main.webp'),
  ('Peso muerto con pesa rusa', 'kettlebell-deadlift', 'back', ARRAY['forearms','quads'], 'kettlebell', 'intermediate', 'compound', 'Un peso muerto con pesa rusa que fortalece glúteos, isquiotibiales y zona lumbar con un patrón de bisagra de cadera.', ARRAY['Párate con los pies a la anchura de los hombros y la pesa rusa entre los pies.','Bisagra en las caderas y flexiona las rodillas para agarrar el asa.','Contrae el core y mantén la espalda plana.','Empuja a través de los talones para ponerte de pie con la pesa rusa.','Bloquea en la parte superior con los hombros hacia atrás.','Baja la pesa rusa de vuelta al suelo con control.'], ARRAY['Mantén la pesa rusa cerca del cuerpo durante todo el recorrido.','Piensa en empujar el suelo con los talones, no en tirar con la espalda.','Lleva las caderas atrás, no las rodillas adelante, al bajar.'], '/exercises/kettlebell-deadlift-main.webp', '/exercises/kettlebell-deadlift-main.webp'),
  ('Paseo del Granjero con Pesa Rusa', 'kettlebell-farmers-walk', 'forearms', ARRAY['back','glutes','quads','core'], 'kettlebell', 'intermediate', 'compound', 'Un acarreo cargado caminando con un peso pesado en cada mano, que reta el agarre, los trapecios y la estabilidad de todo el cuerpo.', ARRAY['Ponte de pie entre dos mancuernas pesadas o asas de granjero.','Flexiona las caderas y agarra las asas con firmeza en agarre neutro.','Ponte erguido con los hombros atrás y el core activado.','Camina hacia delante con pasos cortos y controlados.','Mantén una postura erguida durante todo el recorrido.','Deja los pesos en el suelo al final de la distancia.'], ARRAY['Aprieta las asas con fuerza para que el peso no te resbale de las manos.','Mantén el core firme y no te balancees de lado a lado al caminar.','Da pasos cortos y rápidos; las zancadas largas rompen el equilibrio.'], '/exercises/kettlebell-farmers-walk-main.webp', '/exercises/kettlebell-farmers-walk-main.webp'),
  ('Press de suelo con pesas rusas', 'kettlebell-floor-press', 'chest', ARRAY['shoulders','triceps'], 'kettlebell', 'intermediate', 'compound', 'Un press de pecho con dos brazos realizado tumbado en el suelo con una pesa rusa en cada mano. El suelo limita el rango de movimiento (los tríceps tocan el suelo antes del estiramiento completo), haciéndolo amigable para los hombros y una excelente opción en casa.', ARRAY['Acuéstate boca arriba en el suelo con las rodillas flexionadas y los pies apoyados.','Sostén una pesa rusa en cada mano a la altura del pecho, con las campanas apoyadas en el antebrazo externo.','Empuja ambas pesas rusas hacia arriba hasta que los brazos estén completamente extendidos.','Baja con control hasta que los tríceps toquen el suelo — no rebotes.','Repite el número recomendado de repeticiones.'], ARRAY['Los codos se mantienen a unos 45 grados del torso; no los abras.','El agarre importa: mantén las campanas estables contra el exterior de los antebrazos.','El suelo limita el rango de movimiento por diseño — esta es la ventaja, no el problema.'], '/exercises/kettlebell-floor-press-main.webp', '/exercises/kettlebell-floor-press-main.webp'),
  ('Zancada Goblet con Kettlebell', 'kettlebell-goblet-lunge', 'glutes', ARRAY['hamstrings'], 'kettlebell', 'beginner', 'compound', 'Este ejercicio compuesto unilateral fortalece los cuádriceps, glúteos e isquiotibiales al realizar una zancada con una kettlebell en posición de copa, mejorando la fuerza y estabilidad del tren inferior.', ARRAY['Ponte de pie sosteniendo una kettlebell por sus cuernos a la altura del pecho, con los codos pegados al cuerpo, en la posición de copa.','Da un paso controlado hacia adelante con una pierna, bajando las caderas hasta que ambas rodillas estén flexionadas aproximadamente a 90 grados.','Asegúrate de que tu rodilla delantera esté alineada sobre tu tobillo y tu rodilla trasera flote justo por encima del suelo.','Impúlsate a través del talón de tu pie delantero para volver a la posición inicial, manteniendo el equilibrio y la tensión del core.','Completa todas las repeticiones por lado antes de cambiar, o alterna las piernas por serie.'], ARRAY['Mantén el pecho erguido y el core contraído durante todo el movimiento para proteger tu columna y mantener la estabilidad.','Concéntrate en un descenso controlado y un impulso potente hacia arriba, activando tus glúteos y cuádriceps.','Evita que tu rodilla delantera se colapse hacia adentro; mantenla alineada con tus dedos del pie.'], '/exercises/kettlebell-goblet-lunge-main.webp', '/exercises/kettlebell-goblet-lunge-main.webp'),
  ('Halo con pesa rusa', 'kettlebell-halo', 'shoulders', ARRAY['traps'], 'kettlebell', 'beginner', 'isolation', 'Un ejercicio de movilidad de hombros donde se hace girar una pesa rusa alrededor de la cabeza. Calienta el manguito rotador, la columna torácica y la cintura escapular con carga mínima.', ARRAY['Párate erguido con el core contraído, sosteniendo una pesa rusa ligera por las asas (boca abajo) a la altura del pecho.','Sube la campana a un lado de la cabeza y hazla pasar por detrás en un círculo suave.','Tráela de vuelta a la posición inicial frente a tu cara.','Invierte la dirección cada pocas repeticiones.','Repite el número recomendado de repeticiones o tiempo.'], ARRAY['Solo peso ligero — esto es movilidad, no fuerza.','Mantén la cabeza quieta; la campana gira alrededor, no la cabeza.','Si la campana se aleja, reduce el círculo — órbita ajustada, cerca del cráneo.'], '/exercises/kettlebell-halo-main.webp', '/exercises/kettlebell-halo-main.webp'),
  ('Curl martillo con pesa rusa', 'kettlebell-hammer-curl', 'biceps', NULL, 'kettlebell', 'beginner', 'isolation', 'Un curl con agarre neutro sosteniendo el asa de una pesa rusa de modo que la campana cuelgue junto a la muñeca. La masa descentrada y el agarre neutro trabajan principalmente el braquial y el braquiorradial.', ARRAY['Párate sosteniendo una pesa rusa en una mano, agarrando el asa en posición neutra (palma hacia el cuerpo).','La campana descansa sobre o junto al antebrazo.','Mantén el codo pegado al costado y sube la campana hacia el hombro.','Aprieta en la parte superior y baja con control.','Completa todas las repeticiones en un lado y luego cambia.'], ARRAY['Controla la masa descentrada — la campana tiende a rotar en la parte inferior del recorrido.','El codo se mantiene quieto; solo el antebrazo se mueve.','Carga ligera — esto trabaja el braquial, no el volumen máximo del bíceps.'], '/exercises/kettlebell-hammer-curl-main.webp', '/exercises/kettlebell-hammer-curl-main.webp')
) as v(name, slug, muscle_slug, secondary_slugs, equipment_slug, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url)
on conflict (slug) do nothing;
insert into public.exercises (name, slug, primary_muscle_group_id, secondary_muscle_group_ids, equipment_id, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url, image_source, image_license)
select v.name, v.slug,
  (select id from public.muscle_groups where slug = v.muscle_slug),
  coalesce((select array_agg(id) from public.muscle_groups where slug = any(v.secondary_slugs)), '{}'),
  (select id from public.equipment where slug = v.equipment_slug),
  v.difficulty::public.exercise_difficulty,
  v.movement_type::public.movement_type,
  v.description, v.instructions, v.tips, v.image_url, v.thumbnail_url,
  'RepDB (repdb.co)', 'Free tier - commercial in-app use with attribution'
from (values
('Empuje de Cadera con Kettlebell', 'kettlebell-hip-thrust', 'glutes', ARRAY['hamstrings','quads'], 'kettlebell', 'beginner', 'compound', 'Este ejercicio trabaja eficazmente el glúteo mayor y los isquiotibiales, utilizando una kettlebell para añadir resistencia y lograr una potente extensión de cadera y desarrollo de glúteos.', ARRAY['Siéntate en el suelo con la parte superior de tu espalda apoyada en un banco, las rodillas flexionadas y los pies planos.','Coloca una kettlebell sobre tus caderas, sujetándola firmemente con ambas manos.','Impúlsate a través de tus talones, levantando tus caderas del suelo hasta que tu cuerpo forme una línea recta desde los hombros hasta las rodillas.','Contrae tus glúteos con fuerza en la parte superior del movimiento.','Baja lentamente tus caderas de vuelta a la posición inicial con control.'], ARRAY['Mantén tu barbilla pegada al pecho para mantener una columna vertebral neutra.','Concéntrate en empujar a través de tus talones para maximizar la activación de los glúteos.','Asegúrate de que tus rodillas sigan la línea de tus dedos de los pies durante todo el movimiento.','Controla la fase excéntrica, resistiendo el peso mientras bajas tus caderas.'], '/exercises/kettlebell-hip-thrust-main.webp', '/exercises/kettlebell-hip-thrust-main.webp'),
  ('Peso Muerto Kickstand con Kettlebell', 'kettlebell-kickstand-deadlift', 'glutes', ARRAY['adductors','back'], 'kettlebell', 'intermediate', 'compound', 'Un movimiento de bisagra de cadera en postura escalonada con una kettlebell que carga la pierna delantera mientras el pie trasero estabiliza.', ARRAY['Coloca un pie detrás de modo que solo los dedos toquen el suelo.','Sostén una kettlebell en la mano del lado del pie trasero.','Bisagra en la cadera bajando la kettlebell hacia la espinilla con la espalda recta.','Mantén la mayor parte del peso en el pie delantero.','Empuja con el talón delantero para volver a la posición inicial. Cambia de lado.'], ARRAY['Mantén la kettlebell cerca de la pierna.','Para al sentir el estiramiento en el isquiotibial.','Todas las repeticiones en un lado antes de cambiar.'], '/exercises/kettlebell-kickstand-deadlift-main.webp', '/exercises/kettlebell-kickstand-deadlift-main.webp'),
  ('Zancada con press de pesa rusa', 'kettlebell-lunge-press', 'shoulders', ARRAY['hamstrings','core','triceps'], 'kettlebell', 'intermediate', 'compound', 'Un ejercicio de cuerpo completo que combina una zancada con un press de pesa rusa a un brazo.', ARRAY['Sostén una pesa rusa a la altura del hombro con un brazo.','Da un paso adelante en zancada con la pierna contraria.','Mientras haces la zancada, empuja la pesa rusa por encima de la cabeza.','Bloquea el brazo en la parte superior del press.','Da un paso atrás de vuelta a la posición de pie mientras bajas la pesa rusa.','Completa las repeticiones en un lado y luego cambia.'], ARRAY['Mantén el abdomen firme para no inclinarte hacia el lado cargado.','La rodilla delantera debe apuntar en la dirección del pie.','Empieza con poco peso hasta dominar la coordinación del movimiento.'], '/exercises/kettlebell-lunge-press-main.webp', '/exercises/kettlebell-lunge-press-main.webp'),
  ('Zancada inversa con press desequilibrado de pesa rusa', 'kettlebell-offset-reverse-lunge-and-press', 'shoulders', ARRAY['hamstrings','core','triceps'], 'kettlebell', 'intermediate', 'compound', 'Una zancada inversa combinada con un press de pesa rusa a un brazo, con carga descompensada que exige estabilidad del core.', ARRAY['Sostén una pesa rusa a la altura del hombro en un lado.','Da un paso hacia atrás en zancada inversa con la pierna contraria.','Al llegar a la parte inferior de la zancada, empuja la pesa rusa por encima de la cabeza.','Empuja con el talón delantero para volver a ponerte de pie.','Baja la pesa rusa de vuelta a la altura del hombro.','Completa las repeticiones en un lado y luego cambia.'], ARRAY['Mantén el torso erguido frente a la carga descompensada.','Bloquea el codo arriba con la muñeca firme y recta.','Si pierdes el equilibrio, acorta un poco el paso atrás.'], '/exercises/kettlebell-offset-reverse-lunge-and-press-main.webp', '/exercises/kettlebell-offset-reverse-lunge-and-press-main.webp'),
  ('Paseo con Kettlebell sobre la Cabeza', 'kettlebell-overhead-carry', 'shoulders', ARRAY['forearms','core','lower_back','traps','triceps'], 'kettlebell', 'intermediate', 'compound', 'Un paseo cargado con una sola kettlebell bloqueada por encima de la cabeza, donde la bola cuelga por detrás de la muñeca y tira del brazo hacia atrás, lo que la hace más difícil de sostener quieta que una mancuerna.', ARRAY['Lleva una kettlebell en cargada y press hasta el bloqueo, dejando que la bola se asiente sobre el dorso del antebrazo.','Estira el codo del todo y gira el brazo para que la bola quede por detrás y por encima de la muñeca, no desplazada a un lado.','Empaqueta el hombro — empuja el peso hacia arriba y deja que la escápula acompañe, en lugar de hundirla a la fuerza.','Aprieta el tronco y camina hacia delante con zancadas regulares, con la bola alineada sobre hombro y cadera.','Mantén la muñeca recta; dejar que se doble hacia atrás es lo que hace que una kettlebell arriba se sienta inestable.','Carga la distancia deseada, baja de forma controlada y repite por el otro lado.'], ARRAY['Usa menos peso que con mancuerna. La masa descentrada hace que el mismo kilaje cueste bastante más de sostener quieto.','La muñeca doblada es el fallo habitual. Si se te vence una y otra vez, baja el peso en lugar de pelear con él todo el recorrido.','Haz ambos lados la misma distancia — la carga unilateral es el sentido del ejercicio.'], '/exercises/kettlebell-overhead-carry-main.webp', '/exercises/kettlebell-overhead-carry-main.webp'),
  ('Extensión de tríceps por encima de la cabeza con pesa rusa', 'kettlebell-overhead-tricep-extension', 'triceps', NULL, 'kettlebell', 'intermediate', 'isolation', 'Una extensión de tríceps por encima de la cabeza sosteniendo una pesa rusa por las asas con ambas manos. La carga descentrada jala la campana detrás de la cabeza para un estiramiento profundo de la cabeza larga.', ARRAY['Párate o siéntate sosteniendo una pesa rusa por las asas (boca abajo) con ambas manos por encima de la cabeza.','Brazos completamente extendidos, campana sobre la cabeza.','Flexiona solo los codos para bajar la campana detrás de la cabeza en un arco controlado.','Mantén los brazos verticales y pegados a la cabeza; solo los antebrazos se mueven.','Extiende los codos para devolver la campana por encima de la cabeza.','Repite el número recomendado de repeticiones.'], ARRAY['Agarra las asas firmemente — la campana tiende a rotar en la parte inferior.','Los codos se mantienen pegados; si se abren, reduce la carga.','Una versión sentado en un banco con respaldo es más fácil para la zona lumbar.'], '/exercises/kettlebell-overhead-tricep-extension-main.webp', '/exercises/kettlebell-overhead-tricep-extension-main.webp'),
  ('Sentadilla pistola con pesa rusa', 'kettlebell-pistol-squat', 'glutes', ARRAY['hamstrings','core'], 'kettlebell', 'advanced', 'compound', 'Una sentadilla a una pierna con la pesa rusa al pecho que exige fuerza y equilibrio avanzados.', ARRAY['Sostén una pesa rusa a la altura del pecho con ambas manos.','Párate en una pierna con la otra extendida hacia adelante.','Baja las caderas en una sentadilla a una sola pierna.','Mantén la pierna elevada fuera del suelo durante todo el movimiento.','Empuja a través del talón de apoyo para volver a ponerte de pie.','Completa las repeticiones en un lado y luego cambia.'], ARRAY['Mantén la pesa rusa cerca del pecho como contrapeso.','Baja despacio para no desplomarte en la parte final.','El talón de apoyo no se despega del suelo.'], '/exercises/kettlebell-pistol-squat-main.webp', '/exercises/kettlebell-pistol-squat-main.webp'),
  ('Pullover con pesa rusa', 'kettlebell-pullover', 'back', ARRAY['core','triceps'], 'kettlebell', 'intermediate', 'compound', 'Un pullover en banco plano con una pesa rusa sostenida por las asas. El profundo estiramiento por encima de la cabeza trabaja los dorsales, el tríceps (cabeza larga) y el serrato.', ARRAY['Acuéstate en un banco plano sosteniendo una pesa rusa por las asas con ambas manos sobre el pecho, brazos casi rectos (ligera flexión de codos).','Con el ángulo de los codos fijo, baja la campana por encima de la cabeza en arco hasta que los brazos estén en línea con el torso.','Tira de la campana de vuelta sobre el pecho siguiendo el mismo arco.','Repite el número recomendado de repeticiones.'], ARRAY['Mantén la zona lumbar presionada contra el banco — no arquees para ganar recorrido.','Agarra las asas con fuerza; la campana intentará voltearse en la parte inferior.','Baja solo hasta donde tu movilidad de hombros lo permita sin dolor.'], '/exercises/kettlebell-pullover-main.webp', '/exercises/kettlebell-pullover-main.webp'),
  ('Zancada Inversa con Kettlebell', 'kettlebell-reverse-lunge', 'glutes', ARRAY['hamstrings','core'], 'kettlebell', 'beginner', 'compound', 'Este ejercicio compuesto unilateral desarrolla fuerza y estabilidad en la parte inferior del cuerpo, trabajando principalmente glúteos y cuádriceps, e involucrando isquiotibiales, glúteo medio y oblicuos.', ARRAY['Ponte de pie con una kettlebell en una mano, el brazo extendido hacia abajo, en el mismo lado de la pierna que retrocederá.','Da un paso hacia atrás con una pierna, bajando las caderas hasta que ambas rodillas estén flexionadas aproximadamente a 90 grados.','Mantén la espinilla delantera vertical y el pecho erguido, asegurándote de que la rodilla trasera flote justo por encima del suelo.','Impúlsate a través del talón delantero para volver a la posición inicial.','Completa todas las repeticiones por lado antes de cambiar al otro lado.'], ARRAY['Mantén un core estable durante todo el movimiento para proteger tu columna vertebral.','Concéntrate en un descenso controlado y un ascenso potente.','Mantén el pie delantero plano y distribuye el peso uniformemente entre el talón y la parte media del pie.','Evita que la rodilla delantera se colapse hacia adentro; mantenla alineada con los dedos del pie.'], '/exercises/kettlebell-reverse-lunge-main.webp', '/exercises/kettlebell-reverse-lunge-main.webp'),
  ('Curl de Muñeca Inverso con Kettlebell', 'kettlebell-reverse-wrist-curl', 'forearms', NULL, 'kettlebell', 'beginner', 'isolation', 'Un curl de muñeca inverso unilateral con kettlebell, que entrena los extensores del antebrazo.', ARRAY['Siéntate en un banco con el antebrazo sobre el muslo, palma hacia abajo.','Sujeta una kettlebell por el asa, muñeca fuera de la rodilla.','Deja caer la muñeca, bajando la kettlebell.','Levanta el dorso de la mano extendiendo la muñeca.','Baja con control. Repeticiones por lado.'], ARRAY['Usa una kettlebell muy ligera — los extensores se fatigan rápido.','Mueve solo la muñeca.','Sujeta el asa, no la bola.'], '/exercises/kettlebell-reverse-wrist-curl-main.webp', '/exercises/kettlebell-reverse-wrist-curl-main.webp'),
  ('Zancada rotacional con pesa rusa', 'kettlebell-rotational-lunge', 'glutes', ARRAY['hamstrings','core'], 'kettlebell', 'intermediate', 'compound', 'Una zancada lateral con pesa rusa y rotación del torso que trabaja piernas, glúteos y oblicuos en varios planos.', ARRAY['Sostén una pesa rusa con ambas manos a la altura del pecho.','Da un paso hacia un lado en una zancada lateral.','Rota el torso hacia la pierna que hace la zancada.','Lleva la pesa rusa hacia la rodilla flexionada.','Empuja con la pierna de la zancada para volver al centro.','Completa las repeticiones en un lado y luego cambia.'], ARRAY['Gira desde el torso, no desde las rodillas.','Mantén la espalda larga al bajar la pesa hacia la rodilla.','Controla la rotación, sin movimientos bruscos.'], '/exercises/kettlebell-rotational-lunge-main.webp', '/exercises/kettlebell-rotational-lunge-main.webp'),
  ('Giro ruso con pesa rusa', 'kettlebell-russian-twist', 'core', NULL, 'kettlebell', 'intermediate', 'compound', 'Un Russian Twist con pesa rusa realizado sentado con los pies en el aire, que entrena los oblicuos mediante rotaciones del torso.', ARRAY['Siéntate en el suelo con las rodillas flexionadas y los pies levantados del suelo.','Sostén una pesa rusa con ambas manos frente al pecho.','Inclínate ligeramente hacia atrás para activar el core.','Rota el torso hacia un lado llevando la pesa rusa junto a la cadera.','Rota hacia el lado opuesto en un movimiento controlado.','Repite el número deseado de repeticiones.'], ARRAY['Gira los hombros, no solo los brazos.','Mantén la espalda recta aunque el torso esté inclinado hacia atrás.','Apoya los pies en el suelo si te cuesta mantener el equilibrio.'], '/exercises/kettlebell-russian-twist-main.webp', '/exercises/kettlebell-russian-twist-main.webp'),
  ('Encogimiento de Hombros con Kettlebell', 'kettlebell-shrug', 'traps', ARRAY['forearms'], 'kettlebell', 'beginner', 'isolation', 'Este ejercicio de aislamiento trabaja los músculos trapecios superiores elevando los hombros, mejorando la estabilidad del hombro y la fuerza del cuello.', ARRAY['Ponte de pie con los pies al ancho de las caderas, sosteniendo una kettlebell en cada mano con las palmas hacia tu cuerpo.','Mantén los brazos rectos y los hombros relajados.','Eleva los hombros directamente hacia tus orejas, contrayendo los trapecios en la parte superior.','Mantén la contracción brevemente.','Baja lentamente los hombros a la posición inicial con control.','Repite el movimiento para el número deseado de repeticiones.'], ARRAY['Concéntrate en mover solo los hombros, manteniendo los brazos rectos durante todo el movimiento.','Evita rodar los hombros; muévelos directamente hacia arriba y hacia abajo.','Mantén una columna vertebral neutra y el core activado para prevenir la tensión en la espalda baja.','Usa un peso que permita un rango completo de movimiento y una ejecución controlada.'], '/exercises/kettlebell-shrug-main.webp', '/exercises/kettlebell-shrug-main.webp'),
  ('Peso muerto a una pierna con pesa rusa', 'kettlebell-single-leg-deadlift', 'glutes', ARRAY['back'], 'kettlebell', 'intermediate', 'compound', 'Un peso muerto a una pierna con pesa rusa que fortalece glúteos e isquiotibiales y pone a prueba el equilibrio.', ARRAY['Sostén una pesa rusa en una mano y párate en la pierna contraria.','Bisagra en la cadera y baja la pesa rusa hacia el suelo.','Extiende la pierna libre hacia atrás para mantener el equilibrio.','Baja hasta que el torso quede paralelo al suelo.','Empuja a través del talón de apoyo para volver a ponerte de pie.','Completa las repeticiones en un lado y luego cambia.'], ARRAY['Mantén la cadera cuadrada, sin abrirla hacia el lado libre.','Fija la mirada en un punto del suelo para equilibrarte mejor.','Flexiona ligeramente la rodilla de apoyo durante la bisagra.'], '/exercises/kettlebell-single-leg-deadlift-main.webp', '/exercises/kettlebell-single-leg-deadlift-main.webp'),
  ('Skull crusher con pesa rusa', 'kettlebell-skull-crusher', 'triceps', NULL, 'kettlebell', 'intermediate', 'isolation', 'Un skull crusher tumbado en un banco plano, sosteniendo una pesa rusa por las asas con ambas manos. La masa descentrada cuelga por debajo de las muñecas, añadiendo un reto de agarre y control.', ARRAY['Acuéstate en un banco plano sosteniendo una pesa rusa por las asas con ambas manos, brazos extendidos sobre el pecho.','Flexiona solo los codos para bajar la campana hacia la frente en un arco controlado.','Mantén los brazos verticales; solo los antebrazos se mueven.','Extiende los codos para empujar la campana de vuelta arriba.','Repite el número recomendado de repeticiones.'], ARRAY['Agarra las asas firmemente — la campana tiende a rotar hacia adelante en la parte inferior.','Los codos se mantienen pegados — si se abren, la carga es demasiado pesada.','Inclina los brazos ligeramente hacia atrás en dirección a la cabeza para mantener tensión en los tríceps al bloquear.'], '/exercises/kettlebell-skull-crusher-main.webp', '/exercises/kettlebell-skull-crusher-main.webp'),
  ('Sentadilla con Kettlebell', 'kettlebell-squat', 'quads', ARRAY['glutes'], 'kettlebell', 'beginner', 'compound', 'Una variante de sentadilla sosteniendo una kettlebell con ambas manos colgando baja entre las piernas, añadiendo carga a un patrón de sentadilla estándar.', ARRAY['Ponte de pie con los pies separados al ancho de los hombros, sosteniendo una kettlebell con ambas manos frente a ti.','Deja que la kettlebell cuelgue naturalmente entre tus piernas mientras contraes el core.','Flexiona las caderas y las rodillas para bajar en sentadilla, manteniendo la kettlebell cerca del cuerpo.','Empuja con los pies para volver a la posición inicial.','Repite el número deseado de repeticiones.'], ARRAY['Mantén el pecho arriba y la espalda recta durante todo el movimiento.','Usa la kettlebell como contrapeso para ayudarte a bajar más profundo en la sentadilla.','Empuja las rodillas hacia afuera, en línea con los dedos de los pies, al descender.'], '/exercises/kettlebell-squat-main.webp', '/exercises/kettlebell-squat-main.webp'),
  ('Peso muerto sumo con pesa rusa', 'kettlebell-sumo-deadlift', 'glutes', ARRAY['adductors','back','hamstrings','traps'], 'kettlebell', 'beginner', 'compound', 'Un peso muerto con postura amplia usando una sola pesa rusa entre los pies. La postura amplia y la carga cerca del cuerpo hacen de este un patrón dominante de cuádriceps y glúteos que es fácil de aprender.', ARRAY['Párate con una postura amplia y los pies ligeramente girados hacia afuera, con una pesa rusa en el suelo entre los pies.','Baja con la espalda plana, las rodillas alineadas con los pies, y agarra el asa con ambas manos.','Empuja el suelo y extiende caderas y rodillas juntas para ponerte de pie.','Aprieta los glúteos en la parte superior.','Baja la campana con control de vuelta al suelo empujando las caderas hacia atrás.','Repite el número recomendado de repeticiones.'], ARRAY['Las rodillas se alinean con los pies — no dejes que colapsen hacia adentro.','Los hombros permanecen por encima de las caderas en la parte inferior; si los hombros caen, estrecha la postura.','Mantén la campana cerca del cuerpo durante todo el levantamiento.'], '/exercises/kettlebell-sumo-deadlift-main.webp', '/exercises/kettlebell-sumo-deadlift-main.webp'),
  ('Jalón sumo al mentón con pesa rusa', 'kettlebell-sumo-high-pull', 'adductors', ARRAY['glutes','hamstrings','shoulders'], 'kettlebell', 'intermediate', 'compound', 'Un jalón con pesa rusa desde el suelo hasta la altura del mentón con postura amplia, combinando una bisagra con un remo en pie para desarrollar el trapecio superior de forma explosiva.', ARRAY['Párate con los pies más anchos que los hombros, los dedos ligeramente girados hacia afuera y una pesa rusa en el suelo entre los pies.','Bisagra hacia abajo y agarra el asa con ambas manos.','Empuja con los pies y extiende las caderas de forma explosiva para jalar la pesa rusa hacia arriba.','Al subir, lleva los codos hacia arriba y afuera hasta que el asa alcance la altura del mentón.','Baja la pesa rusa de vuelta entre las piernas con control.','Repite el número recomendado de repeticiones.'], ARRAY['Impulsa primero con las caderas; los brazos terminan el movimiento.','Mantén los codos más altos que las manos en la parte superior — piensa: ancho y alto, no estrecho.'], '/exercises/kettlebell-sumo-high-pull-main.webp', '/exercises/kettlebell-sumo-high-pull-main.webp'),
('Press Svend con Kettlebells', 'kettlebell-svend-press', 'chest', ARRAY['shoulders','triceps'], 'kettlebell', 'beginner', 'isolation', 'Un ejercicio de pecho de pie presionando dos kettlebells unidas por las bolas, aísla el pecho interno.', ARRAY['De pie, junta dos kettlebells por las bolas a la altura del pecho.','Mantén las kettlebells horizontales — bolas tocándose, asas hacia afuera.','Empuja las kettlebells al frente hasta extender los brazos.','Tíralas de regreso al pecho con control.','Repite el número de repeticiones indicado.'], ARRAY['La presión entre las bolas hace el ejercicio.','Usa kettlebells muy ligeras — el agarre incómodo dicta la carga.','Mantén los codos ligeramente flexionados en el lockout.'], '/exercises/kettlebell-svend-press-main.webp', '/exercises/kettlebell-svend-press-main.webp'),
  ('Swing con pesa rusa', 'kettlebell-swing', 'glutes', ARRAY['back','quads'], 'kettlebell', 'intermediate', 'compound', 'Un movimiento explosivo de bisagra de cadera con pesa rusa para potencia y acondicionamiento físico.', ARRAY['Párate con los pies a la anchura de los hombros y la pesa rusa en el suelo por delante.','Bisagra en las caderas, agarra la pesa rusa y llévala hacia atrás entre las piernas.','Extiende las caderas de forma explosiva para balancear la pesa rusa hasta la altura del pecho.','Deja que la pesa rusa vuelva a balancearse entre las piernas.','Repite en un movimiento fluido.'], ARRAY['La fuerza nace de la cadera, no de los brazos.','Aprieta glúteos y abdomen en la parte alta del swing.','Es una bisagra de cadera, no una sentadilla.'], '/exercises/kettlebell-swing-main.webp', '/exercises/kettlebell-swing-main.webp'),
  ('Swing y cargada con pesa rusa', 'kettlebell-swing-clean', 'glutes', ARRAY['shoulders','back','traps'], 'kettlebell', 'intermediate', 'compound', 'Un clean con pesa rusa iniciado desde el swing, que lleva el peso hasta la posición de rack en el hombro.', ARRAY['Párate con los pies a la anchura de los hombros y la pesa rusa entre los pies.','Bisagra en las caderas y agarra el asa con una mano.','Balancea la pesa rusa hacia atrás entre las piernas.','Extiende las caderas hacia adelante para jalar la pesa rusa hasta el hombro.','Recibe la pesa rusa en la posición de rack sobre el hombro.','Completa las repeticiones en un lado y luego cambia.'], ARRAY['Mantén la pesa cerca del cuerpo en la subida.','Recibe la pesa con suavidad, sin golpearte el antebrazo.','Genera la potencia con la cadera, no tirando con el brazo.'], '/exercises/kettlebell-swing-clean-main.webp', '/exercises/kettlebell-swing-clean-main.webp'),
  ('Levantamiento Turco con Kettlebell', 'kettlebell-turkish-get-ups', 'shoulders', ARRAY['core','quads','triceps'], 'kettlebell', 'intermediate', 'compound', 'Un ejercicio de cuerpo completo con kettlebell que pasa de estar tumbado a de pie mientras se mantiene el peso bloqueado por encima de la cabeza, trabajando la fuerza, la estabilidad y la movilidad de todo el cuerpo.', ARRAY['Túmbate boca arriba sosteniendo una kettlebell por encima de la cabeza con una mano.','Flexiona la rodilla del mismo lado y apoya el pie plano.','Rueda hasta apoyarte en el codo opuesto y luego en la mano.','Empuja las caderas hacia arriba y lleva la pierna estirada hacia atrás a una zancada.','Ponte de pie por completo manteniendo la kettlebell bloqueada por encima de la cabeza.','Invierte la secuencia para volver a la posición inicial.'], ARRAY['Mantén la vista en la kettlebell hasta que estés de pie, luego mira al frente.','Muévete despacio en cada paso: el levantamiento es una secuencia, no un solo movimiento.'], '/exercises/kettlebell-turkish-get-ups-main.webp', '/exercises/kettlebell-turkish-get-ups-main.webp'),
  ('Molino de Viento con Pesa Rusa', 'kettlebell-windmills', 'adductors', ARRAY['back','glutes','hamstrings'], 'kettlebell', 'intermediate', 'compound', 'Un ejercicio de pesa rusa con el brazo bloqueado por encima de la cabeza, que combina estabilidad de hombro y bisagra lateral de cadera.', ARRAY['Párate sosteniendo una pesa rusa bloqueada sobre la cabeza con una mano.','Gira los pies unos 45 grados alejándolos del brazo de trabajo.','Con la pesa rusa arriba, inclínate lateralmente desde las caderas.','Lleva la mano opuesta hacia el pie.','Empuja las caderas hacia atrás para volver a la posición erguida.','Completa las repeticiones de un lado y luego cambia.'], ARRAY['No pierdas de vista la pesa durante todo el movimiento.','El brazo de arriba permanece bloqueado y vertical en todo momento.','Empieza sin peso para aprender el patrón del movimiento.'], '/exercises/kettlebell-windmills-main.webp', '/exercises/kettlebell-windmills-main.webp'),
  ('Curl de Muñeca con Kettlebell', 'kettlebell-wrist-curl', 'forearms', NULL, 'kettlebell', 'beginner', 'isolation', 'Un curl de muñeca unilateral con kettlebell — el peso descentrado añade un reto extra al agarre.', ARRAY['Siéntate en un banco con el antebrazo sobre el muslo, palma hacia arriba.','Sujeta una kettlebell por el asa, muñeca fuera de la rodilla.','Deja que la kettlebell rote hacia las puntas de los dedos.','Súbela flexionando la muñeca, controlando el peso descentrado.','Baja con control. Repeticiones por lado.'], ARRAY['Sujeta el asa, no la bola, para que el peso descentrado cargue el agarre.','Mueve solo la muñeca.','Usa una carga más ligera que con una mancuerna.'], '/exercises/kettlebell-wrist-curl-main.webp', '/exercises/kettlebell-wrist-curl-main.webp'),
  ('Push-Up en Rodillas', 'knee-push-ups', 'chest', ARRAY['shoulders','core','triceps'], NULL, 'beginner', 'compound', 'Una variante de flexión apta para principiantes, con las rodillas apoyadas en el suelo para reducir la carga sobre el tren superior.', ARRAY['Comienza en posición de push-up con las rodillas en el suelo.','Coloca las manos a la anchura de los hombros en el suelo.','Mantén el cuerpo en línea recta desde las rodillas hasta los hombros.','Baja el pecho hacia el suelo doblando los codos.','Empuja con las manos para volver a la posición inicial.','Repite el número de repeticiones deseado.'], ARRAY['No abras los codos en exceso hacia los lados.','Aprieta los glúteos y el abdomen durante todo el movimiento.','Mira al suelo para mantener el cuello neutro.'], '/exercises/knee-push-ups-main.webp', '/exercises/knee-push-ups-main.webp'),
  ('Estiramiento Rodilla al Pecho', 'knee-to-chest-stretch', 'glutes', ARRAY['back'], NULL, 'beginner', 'mobility', 'Un estiramiento tumbado que libera los glúteos y la zona lumbar al abrazar una rodilla contra el pecho.', ARRAY['Acuéstate boca arriba con ambas piernas estiradas.','Lleva una rodilla y abrázala al pecho con ambas manos.','Mantén la otra pierna relajada en el suelo.','Mantén de 20 a 30 segundos, respirando de forma constante.','Cambia de lado y repite.'], ARRAY['Mantén la cabeza y los hombros relajados en el suelo.','Relájate y sigue respirando todo el tiempo.'], '/exercises/knee-to-chest-stretch-main.webp', '/exercises/knee-to-chest-stretch-main.webp'),
  ('Remo en Polea Arrodillado', 'kneeling-cable-row', 'back', ARRAY['biceps','shoulders','traps'], 'cable', 'beginner', 'compound', 'Un remo en polea ejecutado desde una posición de rodillas erguida, eliminando el impulso de cadera y manteniendo la tensión en la parte superior de la espalda durante todo el movimiento.', ARRAY['Ajusta la polea a la altura del pecho y conecta una cuerda o un mango doble en D.','Arrodíllate erguido frente a la máquina lo suficientemente lejos para que el peso no llegue al tope.','Agarra el mango con ambas manos y sostenlo extendido frente a ti a la altura del pecho.','Lleva el mango hacia el esternón llevando los codos hacia atrás y apretando los omóplatos.','Regresa de forma controlada a la posición inicial con estiramiento.','Repite el número de repeticiones recomendado.'], ARRAY['Mantente erguido: no te inclines hacia atrás para terminar la repetición.','La postura de rodillas erguidas obliga al core a resistir la rotación en cada tirón.'], '/exercises/kneeling-cable-row-main.webp', '/exercises/kneeling-cable-row-main.webp'),
  ('Estiramiento de Flexores de Cadera Arrodillado', 'kneeling-hip-flexor-stretch', 'core', ARRAY['adductors','quads'], NULL, 'beginner', 'mobility', 'Un estiramiento en semiarrodillado que abre los flexores de cadera de la pierna trasera empujando la cadera adelante.', ARRAY['Arrodíllate sobre una rodilla con el otro pie plano al frente.','Mantén el torso erguido y el core ligeramente activado.','Empuja la cadera adelante hasta sentir el estiramiento en el frente de la cadera trasera.','Mantén de 20 a 30 segundos, respirando de forma constante.','Cambia de lado y repite.'], ARRAY['Aprieta el glúteo de la pierna arrodillada para proteger la zona lumbar.','Evita arquear la zona lumbar.'], '/exercises/kneeling-hip-flexor-stretch-main.webp', '/exercises/kneeling-hip-flexor-stretch-main.webp'),
  ('Estiramiento de Muñecas Arrodillado', 'kneeling-wrist-stretch', 'forearms', NULL, NULL, 'beginner', 'mobility', 'Un estiramiento de rodillas para los flexores del antebrazo y las muñecas, con las palmas abajo y los dedos hacia atrás.', ARRAY['Ponte en cuadrupedia y apoya las palmas planas en el suelo.','Gira las manos para que los dedos apunten hacia las rodillas.','Mantén las palmas abajo y desplaza el peso atrás suavemente.','Mantén de 20 a 30 segundos, respirando de forma constante.'], ARRAY['Mantén las palmas planas mientras te inclinas atrás.','Estira hasta una tensión leve, nunca hasta el dolor.'], '/exercises/kneeling-wrist-stretch-main.webp', '/exercises/kneeling-wrist-stretch-main.webp'),
  ('L-Sit', 'l-sit', 'core', ARRAY['back','quads','triceps'], 'bodyweight', 'advanced', 'compound', 'Un ejercicio isométrico avanzado en el que el cuerpo forma una L con las piernas extendidas, exigente para el core y los flexores de cadera.', ARRAY['Siéntate en el suelo o empuja hacia arriba en barras paralelas con los brazos rectos.','Bloquea los codos y deprime los hombros.','Eleva las piernas rectas al frente paralelas al suelo.','Forma una L con el cuerpo.','Mantén la posición durante el tiempo indicado.','Baja las piernas con control para salir.'], ARRAY['Mantén las puntas de los pies estiradas hacia delante.','Si no llegas, empieza con las rodillas recogidas.','Respira de forma constante; no aguantes el aire durante el sostén.'], '/exercises/l-sit-main.webp', '/exercises/l-sit-main.webp'),
  ('Press Landmine', 'landmine-press', 'shoulders', ARRAY['core','triceps'], 'barbell', 'intermediate', 'compound', 'Un press de hombros a dos manos con una barra fijada en un accesorio landmine, cuyo arco natural reduce el estrés en la articulación del hombro.', ARRAY['Inserta un extremo de la barra en el accesorio landmine y carga el extremo libre con un disco.','Párate en postura escalonada o paralela y sujeta el extremo libre de la barra con ambas manos a la altura del pecho.','Activa el core y empuja la barra hacia adelante y arriba siguiendo su arco natural.','Extiende completamente los brazos sin bloquear los codos, luego baja con control.','Mantén ambas manos en la barra y repite el número de repeticiones deseado.'], ARRAY['Mantén el torso erguido y evita inclinarte excesivamente hacia el press.','La trayectoria angular es más amigable para el hombro que un press estricto sobre la cabeza.','Usa impulso de piernas estilo push press para cargas más pesadas.'], '/exercises/landmine-press-main.webp', '/exercises/landmine-press-main.webp'),
  ('Elevación Lateral con Mancuernas', 'lateral-raise', 'shoulders', NULL, 'dumbbell', 'beginner', 'isolation', 'Un movimiento de aislamiento que trabaja el deltoides lateral para ganar anchura en los hombros.', ARRAY['Párate con mancuernas a los costados.','Eleva las mancuernas hacia los lados hasta que los brazos queden paralelos al suelo.','Baja de forma controlada.','Repite.'], ARRAY['Ligera flexión en los codos.','Guía con los codos, no con las manos.'], '/exercises/lateral-raise-main.webp', '/exercises/lateral-raise-main.webp'),
  ('Curl de Piernas Tumbado', 'leg-curl', 'hamstrings', ARRAY['calves'], 'machine', 'beginner', 'isolation', 'Un ejercicio de aislamiento para los isquiotibiales usando la máquina de curl de piernas.', ARRAY['Túmbate boca abajo en la máquina de curl de piernas con los tobillos bajo el rodillo.','Lleva los talones hacia los glúteos.','Aprieta los isquiotibiales en la parte superior.','Baja con control.','Repite.'], ARRAY['Mantén las caderas pegadas al banco durante todo el recorrido.','Evita arquear la zona lumbar al subir los talones.','Elige un peso que permita un recorrido completo y controlado.'], '/exercises/leg-curl-main.webp', '/exercises/leg-curl-main.webp'),
  ('Piernas en la Pared', 'legs-up-the-wall', 'hamstrings', ARRAY['back'], NULL, 'beginner', 'mobility', 'Una posición restaurativa con las caderas cerca de una pared y las piernas apoyadas en vertical, pensada para recuperar y no para esforzarse.', ARRAY['Siéntate de lado junto a una pared con una cadera en contacto con ella.','Sube las piernas por la pared mientras te tumbas, de modo que las caderas queden cerca de la base.','Deja las piernas apoyadas en la pared, los pies relajados y los brazos abiertos a los lados.','Permanece durante el tiempo indicado, respirando despacio.','Flexiona las rodillas y rueda hacia un lado para salir.'], ARRAY['Aleja las caderas unos centímetros de la pared si notas tirón en los isquiotibiales.','Coloca una manta doblada bajo la pelvis para una versión más suave y sostenida.','Mantén las piernas pasivas; esta posición no debe costar esfuerzo.'], '/exercises/legs-up-the-wall-main.webp', '/exercises/legs-up-the-wall-main.webp'),
  ('Estiramiento del Lagarto', 'lizard-stretch', 'adductors', ARRAY['glutes','hamstrings'], NULL, 'beginner', 'mobility', 'Un estiramiento en zancada profunda que abre los flexores de cadera, la ingle y los glúteos con los antebrazos hacia el suelo.', ARRAY['Da un paso adelante a una zancada profunda, con el pie bien abierto.','Baja ambos antebrazos hacia el suelo por dentro del pie delantero.','Extiende la pierna trasera y deja que la cadera baje.','Mantén de 20 a 30 segundos, respirando de forma constante.','Cambia de lado y repite.'], ARRAY['Apóyate en las manos en vez de los antebrazos para una versión más fácil.','Estira hasta una tensión leve, nunca hasta el dolor.'], '/exercises/lizard-stretch-main.webp', '/exercises/lizard-stretch-main.webp'),
  ('Postura del Saltamontes', 'locust-pose', 'back', ARRAY['hamstrings','shoulders'], NULL, 'beginner', 'compound', 'Un sostén boca abajo en el que pecho, brazos y piernas se despegan del suelo, de modo que toda la cadena posterior trabaja de forma isométrica sin carga externa.', ARRAY['Túmbate boca abajo con los brazos junto al cuerpo y la frente en la esterilla.','Alarga la nuca y estira las yemas de los dedos hacia los pies.','Eleva a la vez el pecho, los brazos y ambas piernas.','Mantén la posición elevada durante el tiempo indicado, con la mirada hacia el suelo.','Baja todo a la vez y descansa.'], ARRAY['Eleva desde el alargamiento de la columna en lugar de tirar de la cabeza hacia arriba.','Mantén las piernas a la anchura de las caderas y las rodillas estiradas.','Empieza elevando solo las piernas y añade el pecho después si la versión completa es demasiado.'], '/exercises/locust-pose-main.webp', '/exercises/locust-pose-main.webp'),
('Zancada Baja', 'low-lunge', 'core', ARRAY['back','glutes'], NULL, 'beginner', 'mobility', 'Un estiramiento en paso largo con la rodilla trasera apoyada: las caderas se hunden hacia delante y alargan el flexor de la cadera de la pierna de atrás.', ARRAY['Desde la posición de rodillas, adelanta un pie para que la rodilla quede sobre el tobillo.','Apoya la rodilla trasera en el suelo y deja el empeine estirado.','Mete ligeramente el coxis y empuja las caderas hacia delante hasta notar el alargamiento en la parte frontal del muslo trasero.','Eleva el pecho, sube los brazos si te resulta agradable y mantén durante el tiempo indicado.','Vuelve atrás y repite del otro lado.'], ARRAY['Acolcha la rodilla trasera con una esterilla doblada si el suelo es duro.','Aprieta el glúteo de atrás para profundizar el estiramiento sin arquear la zona lumbar.','Mantén la rodilla delantera sobre el tobillo en lugar de dejarla deslizarse hacia delante.'], '/exercises/low-lunge-main.webp', '/exercises/low-lunge-main.webp'),
  ('Zancada Baja a Medio Split', 'low-lunge-to-half-split', 'hamstrings', ARRAY['calves','core'], NULL, 'beginner', 'mobility', 'Una secuencia en movimiento para isquiotibiales y flexores de cadera: desde una zancada baja las caderas retroceden sobre la rodilla trasera y la pierna delantera se estira en medio split, y después las caderas vuelven a deslizarse hacia delante.', ARRAY['Empieza en zancada baja con la rodilla trasera en el suelo y la delantera sobre el tobillo.','Apoya las manos en el suelo o en bloques a ambos lados del pie delantero.','Lleva las caderas atrás sobre la rodilla trasera y estira la pierna delantera con el pie en flexión.','Sostén el medio split un instante y desliza las caderas hacia delante otra vez a la zancada.','Repite las veces indicadas y cambia de lado.'], ARRAY['Mantén larga la parte posterior de la pierna delantera: flexiona un poco la rodilla en lugar de redondear la columna para llegar.','Se mueven las caderas, no el pie delantero; el pie se queda donde estaba.','Acolcha la rodilla trasera y usa bloques bajo las manos si el suelo queda lejos.'], '/exercises/low-lunge-to-half-split-main.webp', '/exercises/low-lunge-to-half-split-main.webp'),
  ('Zancada', 'lunge', 'glutes', ARRAY['back','hamstrings'], NULL, 'intermediate', 'compound', 'Una zancada hacia delante con el peso corporal, entrenando cuádriceps, glúteos y equilibrio una pierna a la vez.', ARRAY['Párate erguido con los pies a la anchura de las caderas.','Da un paso adelante largo con una pierna.','Baja la rodilla trasera hacia el suelo hasta que ambas rodillas formen ángulos de 90 grados.','Empuja con el talón delantero para volver a la posición de pie.','Completa las repeticiones de un lado y luego cambia.'], ARRAY['Da una zancada lo bastante larga para que ambas rodillas lleguen a unos 90 grados.','Mantén el torso erguido y la mirada al frente.','Empuja con el talón delantero para volver en un solo movimiento potente.'], '/exercises/lunge-main.webp', '/exercises/lunge-main.webp'),
  ('Elevación de Piernas Acostado', 'lying-leg-raise', 'core', NULL, NULL, 'beginner', 'compound', 'Un ejercicio de suelo para el abdomen bajo y los flexores de cadera que consiste en elevar las piernas rectas desde posición supina.', ARRAY['Túmbate boca arriba con las piernas rectas y las manos bajo la zona lumbar o sujetando una superficie estable detrás de la cabeza.','Con las piernas juntas y el core activado, eleva las piernas hasta la vertical.','Pausa brevemente arriba.','Baja las piernas despacio hacia el suelo sin llegar a apoyarlas.','Repite el número de repeticiones deseado.'], ARRAY['Mantén la zona lumbar pegada al suelo durante todo el ejercicio.','Evita el balanceo — controla el descenso para maximizar la tensión.','Dobla ligeramente las rodillas si la flexibilidad de los isquiotibiales lo requiere.'], '/exercises/lying-leg-raise-main.webp', '/exercises/lying-leg-raise-main.webp'),
  ('Extensión de Tríceps Tumbado', 'lying-tricep-extension', 'triceps', ARRAY['shoulders'], 'dumbbell', 'intermediate', 'isolation', 'Un ejercicio de aislamiento tumbado que baja el peso hacia la frente y extiende los codos para trabajar los tríceps.', ARRAY['Túmbate en un banco con una barra o mancuernas sostenidas sobre la cabeza.','Mantén los brazos superiores verticales y los codos apuntando hacia adelante.','Baja el peso hacia la frente doblando los codos.','Extiende los brazos de vuelta a la posición inicial.','Aprieta los tríceps en la parte superior.','Repite el número de repeticiones deseado.'], ARRAY['Mantén los brazos verticales y los codos apuntando hacia delante.','Mueve solo los codos, no los hombros.','Baja el peso con control en lugar de dejarlo caer.'], '/exercises/lying-tricep-extension-main.webp', '/exercises/lying-tricep-extension-main.webp'),
  ('Extensión de Espalda en Máquina', 'machine-back-extension', 'back', ARRAY['glutes','hamstrings'], 'machine', 'beginner', 'isolation', 'Un ejercicio de aislamiento sentado para la zona lumbar: con la cadera y las piernas fijas, el torso empuja hacia atrás contra un rodillo acolchado y extiende la columna venciendo la placa de pesas.', ARRAY['Siéntate en la máquina de extensión de espalda con los pies apoyados en la plataforma y ajusta el rodillo para que quede sobre la parte alta de la espalda, justo por debajo de los omóplatos.','Agarra las manijas laterales y deja que el torso venga ligeramente hacia delante: esta es la posición inicial.','Empuja hacia atrás contra el rodillo extendiendo la columna hasta que el torso quede inclinado hacia atrás y la zona lumbar esté totalmente contraída.','Haz una pausa breve en la extensión completa y regresa a la posición inicial de forma controlada, resistiendo el peso durante el recorrido.','Repite el número de repeticiones deseado.'], ARRAY['Coloca el rodillo justo por debajo de los omóplatos: más arriba presiona el cuello y más abajo pierdes recorrido.','Extiende desde la zona lumbar en lugar de lanzar la cabeza y los hombros hacia atrás, y mantén lento el movimiento en ambos sentidos.','Detente con el torso extendido en posición neutra en lugar de forzar la columna más allá, y empieza con poco peso: la zona lumbar responde mejor a repeticiones controladas que a cargas altas.'], '/exercises/machine-back-extension-main.webp', '/exercises/machine-back-extension-main.webp'),
  ('Curl de Bíceps en Máquina', 'machine-bicep-curl', 'biceps', NULL, 'machine', 'beginner', 'isolation', 'Un curl de bíceps en máquina para el entrenamiento aislado de brazos.', ARRAY['Siéntate en la máquina y ajusta el rodillo a la longitud de tus brazos.','Agarra las manijas con agarre en supinación.','Lleva las manijas hacia los hombros.','Baja con control.','Repite.'], ARRAY['Mantén los codos apoyados en la almohadilla en todo momento.','Evita encoger los hombros al subir las asas.','Baja hasta casi extender los brazos sin perder la tensión.'], '/exercises/machine-bicep-curl-main.webp', '/exercises/machine-bicep-curl-main.webp'),
  ('Elevación de Pantorrillas en Máquina', 'machine-calf-raise', 'calves', NULL, 'machine', 'beginner', 'isolation', 'Un ejercicio de aislamiento en máquina de pie que trabaja los gemelos y el sóleo con un recorrido completo del tobillo.', ARRAY['Párate en la máquina de elevación de pantorrillas con los metatarsos sobre la plataforma.','Coloca los rodillos de hombro firmemente.','Baja los talones por debajo de la plataforma para un estiramiento completo.','Empuja con los metatarsos para elevarte en los dedos de los pies.','Aprieta las pantorrillas en la parte superior.','Baja con control y repite.'], ARRAY['Evita rebotar en la parte baja para no perder tensión.','Mantén las rodillas extendidas pero sin llegar a bloquearlas.','Sube en vertical, sin inclinar los tobillos hacia fuera.'], '/exercises/machine-calf-raise-main.webp', '/exercises/machine-calf-raise-main.webp'),
  ('Aperturas en Máquina', 'machine-chest-fly', 'chest', ARRAY['shoulders','core'], 'machine', 'beginner', 'isolation', 'Un ejercicio de aislamiento de pecho realizado en una máquina que junta las palancas en un arco frente al cuerpo.', ARRAY['Siéntate en la máquina de aperturas y ajusta el asiento para que las palancas queden a la altura del pecho.','Sujeta las palancas con una ligera flexión de codos.','Junta las palancas frente al pecho en un arco suave.','Contrae el pectoral en el punto de máxima contracción.','Vuelve con control a la posición inicial sin dejar caer el peso.','Repite el número de repeticiones deseado.'], ARRAY['Mantén una flexión de codo ligera y constante durante todo el movimiento.','Enfócate en contraer el pecho en lugar de empujar con los brazos.','Controla el regreso en vez de dejar caer la pila de pesas.'], '/exercises/machine-chest-fly-main.webp', '/exercises/machine-chest-fly-main.webp'),
  ('Curl en Máquina de Predicador', 'machine-preacher-curl', 'biceps', NULL, 'machine', 'beginner', 'isolation', 'Un curl de bíceps en máquina de predicador que fija los codos sobre el almohadillado y ofrece una curva de fuerza guiada.', ARRAY['Siéntate y ajusta el asiento para que las axilas queden en la parte superior del almohadillado.','Coloca los brazos sobre el soporte y sujeta las asas.','Comienza con los brazos ligeramente flexionados, sin bloquear los codos.','Flexiona los codos hacia arriba y aprieta en la posición máxima.','Baja lentamente hasta la posición inicial y repite.'], ARRAY['No separes los codos del almohadillado.','Para justo antes de la extensión completa para proteger los tendones del codo.'], '/exercises/machine-preacher-curl-main.webp', '/exercises/machine-preacher-curl-main.webp'),
  ('Abdominales en Máquina Sentado', 'machine-seated-crunch', 'core', NULL, 'machine', 'beginner', 'isolation', 'Un ejercicio de aislamiento abdominal en una máquina sentada que flexiona la columna contra resistencia.', ARRAY['Siéntate en la máquina de abdominales y sujeta las manijas.','Coloca la almohadilla de pecho contra tu torso.','Contrae el abdomen para flexionar el torso hacia adelante y abajo.','Contrae al final del recorrido.','Vuelve a la posición inicial con control.','Repite el número de repeticiones deseado.'], ARRAY['Inicia el movimiento con el abdomen, no con los brazos.','Exhala mientras flexionas el torso.','Evita el impulso balanceando el cuerpo.'], '/exercises/machine-seated-crunch-main.webp', '/exercises/machine-seated-crunch-main.webp'),
  ('Press de Hombros en Máquina', 'machine-shoulder-press', 'shoulders', ARRAY['traps','triceps'], 'machine', 'beginner', 'compound', 'Un movimiento de press por encima de la cabeza en máquina para los hombros.', ARRAY['Siéntate en la máquina con la espalda contra el rodillo.','Agarra las manijas a la altura de los hombros.','Presiona las manijas sobre la cabeza hasta que los brazos queden completamente extendidos.','Baja con control a la posición inicial.','Repite.'], ARRAY['No arquees la zona lumbar al empujar hacia arriba.','Evita bloquear los codos de golpe en la parte alta.','Mantén las muñecas firmes y alineadas con los antebrazos.'], '/exercises/machine-shoulder-press-main.webp', '/exercises/machine-shoulder-press-main.webp'),
  ('Extensión de Tríceps en Máquina', 'machine-triceps-extension', 'triceps', NULL, 'machine', 'beginner', 'isolation', 'Un ejercicio de aislamiento sentado en máquina: los brazos quedan apoyados sobre un rodillo mientras los codos se extienden contra dos manijas, de modo que el tríceps trabaja por un recorrido guiado sin ayuda de los hombros ni del torso.', ARRAY['Siéntate en la máquina de extensión de tríceps con la espalda apoyada en el respaldo y los brazos apoyados de plano sobre el rodillo, delante del pecho.','Toma una manija con cada mano, con los codos flexionados y las manos a la altura de los hombros.','Manteniendo los brazos pegados al rodillo, extiende los codos para empujar las manijas hacia abajo y hacia delante hasta estirar los brazos por completo.','Aprieta el tríceps en la extensión completa y flexiona los codos para volver al inicio de forma controlada.','Repite el número de repeticiones deseado.'], ARRAY['Ajusta la altura del asiento para que los brazos queden planos sobre el rodillo y los codos alineados con el eje de giro de la máquina: esa alineación es lo que mantiene el trabajo en el tríceps.','Mantén los brazos pegados al rodillo; si se despegan, el movimiento se convierte en un press y el tríceps deja de trabajar.','Estira los brazos del todo sin bloquear de golpe los codos, y frena la vuelta en lugar de dejar caer las placas.'], '/exercises/machine-triceps-extension-main.webp', '/exercises/machine-triceps-extension-main.webp'),
  ('Golpe con Balón Medicinal', 'medicine-ball-slam', 'core', ARRAY['glutes','back'], 'kettlebell', 'beginner', 'compound', 'Un ejercicio explosivo de cuerpo completo donde se levanta un slam ball sobre la cabeza y se lanza contra el suelo con la máxima fuerza.', ARRAY['Párate con los pies a la anchura de los hombros sosteniendo un slam ball frente a las caderas.','Levanta el balón sobre la cabeza extendiendo las caderas y alargándote hacia arriba.','Golpea el balón contra el suelo entre los pies con fuerza, contrayendo el core.','Atrapa el balón en el rebote o recógelo del suelo.','Repite el número de repeticiones recomendado.'], ARRAY['Usa un slam ball de rebote suave, no un balón medicinal tradicional: los balones normales pueden rebotar hacia la cara.','Termina con todo el cuerpo: es un swing completo, no solo un lanzamiento de brazos.'], '/exercises/medicine-ball-slam-main.webp', '/exercises/medicine-ball-slam-main.webp'),
  ('Mountain Climbers', 'mountain-climbers', 'core', ARRAY['quads'], NULL, 'beginner', 'cardio', 'Un ejercicio dinámico de peso corporal que combina trabajo de core con cardio.', ARRAY['Comienza en posición de plancha alta.','Lleva una rodilla hacia el pecho.','Cambia rápidamente de pierna llevando la otra rodilla hacia adelante.','Continúa alternando a un ritmo brioso.','Repite.'], ARRAY['Mantén los hombros encima de las muñecas todo el tiempo.','No dejes que la cadera se eleve hacia el techo.','Acelera solo mientras puedas mantener la técnica.'], '/exercises/mountain-climbers-main.webp', '/exercises/mountain-climbers-main.webp'),
  ('Postura de la Montaña', 'mountain-pose', 'back', ARRAY['calves','quads'], NULL, 'beginner', 'mobility', 'La postura básica de pie: pies enraizados, piernas activas, columna larga y hombros relajados. Es la referencia de alineación con la que se miden las demás posturas de pie.', ARRAY['Ponte de pie con los pies a la anchura de las caderas y reparte el peso por igual entre ambos.','Activa ligeramente los muslos y deja caer el coxis para que la pelvis quede neutra.','Alinea las costillas sobre la pelvis y la cabeza sobre las costillas, con los brazos relajados a los lados.','Mantén la postura durante el tiempo indicado, respirando con regularidad.','Observa dónde queda el peso y devuélvelo al centro de cada pie.'], ARRAY['Levanta y abre los dedos de los pies una vez y vuelve a apoyarlos; eso reinicia el arco del pie.','Mantén las rodillas blandas en lugar de bloquearlas.','Deja que los hombros roten atrás y abajo sin apretar las escápulas entre sí.'], '/exercises/mountain-pose-main.webp', '/exercises/mountain-pose-main.webp'),
  ('Muscle Snatch', 'muscle-snatch', 'shoulders', ARRAY['back','glutes','hamstrings'], 'barbell', 'intermediate', 'compound', 'Una variante de la arrancada que tira de la barra por encima de la cabeza sin caer debajo, desarrollando potencia de tirón y fuerza de bloqueo.', ARRAY['Párate con los pies a la anchura de las caderas y agarra la barra en ancho con agarre de gancho.','Tira de la barra explosivamente desde el suelo manteniéndola cerca del cuerpo.','Encoge los hombros con fuerza y lleva la barra sobre la cabeza sin flexionar las piernas.','Bloquea la barra sobre la cabeza con los brazos rectos.','Baja la barra con control a la posición inicial.','Repite el número de repeticiones deseado.'], ARRAY['Encoge los hombros con fuerza y sigue tirando de la barra hacia arriba.','Mantente erguido; no te metas debajo de la barra para recibirla.','Mantén la barra cerca del cuerpo durante todo el tirón.'], '/exercises/muscle-snatch-main.webp', '/exercises/muscle-snatch-main.webp'),
  ('Muscle-Ups', 'muscle-ups', 'back', ARRAY['shoulders','biceps','chest'], 'bodyweight', 'advanced', 'compound', 'Un movimiento avanzado en barra que combina una dominada explosiva con una transición a fondo para terminar por encima de la barra.', ARRAY['Cuélgate de una barra de dominadas con agarre falso.','Tírate hacia arriba de forma explosiva hacia la barra.','Cuando el pecho llegue a la barra, rota los codos por encima y transiciona a un dip.','Empuja el cuerpo hacia arriba hasta que los brazos queden completamente extendidos sobre la barra.','Baja con control por el mismo recorrido.','Repite el número de repeticiones deseado.'], ARRAY['Usa agarre falso para que las muñecas ya estén sobre la barra en la transición.','Tira explosivamente hacia el esternón, no solo hasta la barbilla.','Practica la transición en anillas bajas o con bandas antes de hacer repeticiones completas.'], '/exercises/muscle-ups-main.webp', '/exercises/muscle-ups-main.webp'),
('Estiramiento Lateral de Cuello', 'neck-side-stretch', 'traps', NULL, NULL, 'beginner', 'mobility', 'Un estiramiento suave que alarga el trapecio superior y el lateral del cuello inclinando la oreja hacia el hombro.', ARRAY['Siéntate o párate erguido con los hombros relajados.','Inclina la cabeza para que una oreja baje hacia ese hombro.','Apoya esa mano sobre la cabeza para un peso suave.','Mantén de 20 a 30 segundos, respirando de forma constante.','Cambia de lado y repite.'], ARRAY['Deja que el peso de la mano haga el trabajo, no tires fuerte.','Mantén el hombro opuesto hacia abajo.'], '/exercises/neck-side-stretch-main.webp', '/exercises/neck-side-stretch-main.webp'),
  ('Dominadas Negativas', 'negative-pull-ups', 'back', ARRAY['biceps','forearms','shoulders'], 'bodyweight', 'beginner', 'compound', 'Una progresión de dominada centrada en la fase excéntrica, en la que se desciende lentamente desde la barra con control.', ARRAY['Usa un cajón o salta para colocarte en la parte superior de una dominada.','Agarra la barra con las manos a la anchura de los hombros.','Mantén el mentón por encima de la barra un momento.','Bájate lentamente durante 3-5 segundos con control.','Extiende los brazos completamente en la parte inferior.','Vuelve a la posición inicial y repite el número de repeticiones deseado.'], ARRAY['Resiste la bajada durante todo el recorrido, sin dejarte caer al final.','Mantén los hombros activos, lejos de las orejas.','Aprieta el core para no balancearte durante el descenso.'], '/exercises/negative-pull-ups-main.webp', '/exercises/negative-pull-ups-main.webp'),
  ('Dominadas en Agarre Neutro', 'neutral-grip-pull-ups', 'back', ARRAY['biceps','forearms'], 'bodyweight', 'intermediate', 'compound', 'Una dominada con agarre neutro y palmas enfrentadas que trabaja el dorsal ancho con fuerte participación de los brazos.', ARRAY['Agarra las barras paralelas con las palmas enfrentadas.','Cuelga con los brazos completamente extendidos.','Tírate hacia arriba hasta que el mentón supere la barra.','Aprieta los dorsales en la parte superior del movimiento.','Bájate con control a la posición inicial.','Repite el número de repeticiones deseado.'], ARRAY['Piensa en llevar los codos hacia las costillas al subir.','Evita balancearte; sube en una línea vertical limpia.','Lleva el pecho hacia las barras en la parte alta.'], '/exercises/neutral-grip-pull-ups-main.webp', '/exercises/neutral-grip-pull-ups-main.webp'),
  ('Curl Nórdico de Isquiotibiales', 'nordic-hamstring-curl', 'hamstrings', ARRAY['calves','glutes'], 'machine', 'advanced', 'isolation', 'Un ejercicio de flexión de rodilla bajando el torso hacia delante desde una posición arrodillada, trabajando los isquiotibiales de forma excéntrica.', ARRAY['Arrodíllate sobre una colchoneta con los tobillos anclados bajo un soporte fijo.','Mantén el torso erguido y las caderas extendidas.','Baja el cuerpo hacia adelante lentamente resistiendo con los isquiotibiales.','Amortigua la caída con las manos justo antes de tocar el suelo.','Empuja con las manos para volver y tírate hacia la posición inicial.','Repite el número de repeticiones deseado.'], ARRAY['Baja tan despacio como sea posible: la fase excéntrica es el objetivo.','Mantén las caderas extendidas; no te dobles por la cintura.','Frénate con las manos y empuja ligeramente mientras ganas fuerza.'], '/exercises/nordic-hamstring-curl-main.webp', '/exercises/nordic-hamstring-curl-main.webp'),
  ('Press Militar con Barra', 'ohp', 'shoulders', ARRAY['traps','triceps'], 'barbell', 'intermediate', 'compound', 'Un movimiento de empuje compuesto por encima de la cabeza que trabaja los hombros y el tríceps.', ARRAY['De pie con los pies a la anchura de los hombros y la barra a la altura de las clavículas.','Contrae el core y empuja la barra por encima de la cabeza.','Bloquea los codos arriba con la barra sobre el punto medio del pie.','Baja la barra hasta la altura de las clavículas.','Repite.'], ARRAY['No te eches demasiado hacia atrás.','Aprieta los glúteos para mayor estabilidad.'], '/exercises/ohp-main.webp', '/exercises/ohp-main.webp'),
  ('Push Press con Mancuerna a Un Brazo', 'one-arm-dumbbell-push-press', 'shoulders', ARRAY['glutes','core','quads','triceps'], 'dumbbell', 'intermediate', 'compound', 'Un push press unilateral con una sola mancuerna. El impulso de piernas te permite lanzar cargas más pesadas por encima de la cabeza que un press estricto a un brazo, y la carga asimétrica exige una fuerte contención anti-flexión lateral.', ARRAY['De pie con la mancuerna en un hombro, palma hacia adentro (neutro).','Pies a la anchura de los hombros, core contraído, brazo libre al costado para equilibrio.','Flexiona ligeramente las rodillas manteniendo el torso vertical.','Extiende las piernas de forma explosiva y empuja la mancuerna por encima de la cabeza en un solo movimiento.','Bloquea el codo arriba y baja la mancuerna al hombro con control.','Completa todas las repeticiones de un lado y luego cambia.'], ARRAY['El impulso viene de las piernas; el brazo termina el movimiento, no lo inicia.','El torso debe mantenerse erguido y cuadrado; no te inclines hacia el lado contrario a la carga.','Menos peso y mejor impulso de piernas superan a más peso con el torso inclinado.'], '/exercises/one-arm-dumbbell-push-press-main.webp', '/exercises/one-arm-dumbbell-push-press-main.webp'),
  ('Swing con Mancuerna a un Brazo', 'one-arm-dumbbell-swing', 'glutes', ARRAY['back','forearms','shoulders'], 'dumbbell', 'intermediate', 'compound', 'Este ejercicio dinámico desarrolla potencia explosiva en glúteos e isquiotibiales mediante una potente bisagra de cadera, involucrando el core y los hombros para un entrenamiento de cuerpo completo.', ARRAY['Párate con los pies al ancho de los hombros, una mancuerna en el suelo ligeramente delante de ti.','Haz una bisagra de cadera, manteniendo la espalda recta, y agarra la mancuerna con una mano.','Lleva la mancuerna hacia atrás entre tus piernas, luego impulsa explosivamente tus caderas hacia adelante.','Balancea la mancuerna hasta la altura del pecho, manteniendo tu brazo relajado y estirado.','Permite que la mancuerna baje, haciendo una bisagra de cadera mientras desciende.','Repite las repeticiones deseadas por lado, manteniendo el control.'], ARRAY['Concéntrate en impulsar con tus caderas, no en tirar con tu brazo.','Mantén tu core contraído durante todo el movimiento para mayor estabilidad.','Mantén una columna vertebral neutra; evita redondear tu espalda.','Controla la fase excéntrica mientras la mancuerna baja.'], '/exercises/one-arm-dumbbell-swing-main.webp', '/exercises/one-arm-dumbbell-swing-main.webp'),
  ('Curl de Bíceps con Pesa Rusa a Un Brazo', 'one-arm-kettlebell-bicep-curl', 'biceps', ARRAY['forearms'], 'kettlebell', 'intermediate', 'isolation', 'Un curl de bíceps unilateral con pesa rusa que entrena cada brazo por separado e implica con fuerza el antebrazo.', ARRAY['De pie, sostén una pesa rusa en una mano.','Mantén el codo pegado al costado.','Sube la pesa rusa hacia el hombro flexionando el bíceps.','Aprieta en la parte superior del movimiento.','Baja la pesa rusa con control.','Completa las repeticiones de un lado y luego cambia.'], ARRAY['Mantén la muñeca recta aunque la pesa tire de ella.','Evita balancear el torso para ayudarte a subir el peso.','Empieza siempre por tu lado más débil.'], '/exercises/one-arm-kettlebell-bicep-curl-main.webp', '/exercises/one-arm-kettlebell-bicep-curl-main.webp'),
  ('Press Strict con Pesa Rusa Invertida a Un Brazo', 'one-arm-kettlebell-bottoms-up-press', 'shoulders', ARRAY['forearms','core','triceps'], 'kettlebell', 'advanced', 'compound', 'Un press estricto por encima de la cabeza con la pesa rusa boca abajo: la bola arriba y el asa en la palma. La carga invertida exige un agarre fuerte, estabilidad perfecta de hombro y una trayectoria impecable.', ARRAY['Limpia una pesa rusa ligera a la posición de rack y luego inclínala para que la bola apunte hacia arriba y el asa quede en la palma.','Agarra el asa con fuerza; la muñeca absolutamente recta y vertical.','Contrae el core y empuja la bola recto hacia arriba sin dejarla caer.','Bloquea el codo arriba con la bola todavía perfectamente vertical.','Baja lentamente a la posición de rack manteniendo la pesa vertical durante todo el descenso.','Completa todas las repeticiones de un lado y luego cambia.'], ARRAY['Si la bola se inclina, la serie termina; no luches para bajarla.','Empieza con muy poco peso; es un ejercicio de habilidad y estabilidad, no un press pesado.','Aprieta fuerte durante todo el recorrido; cualquier relajación y la pesa cae.'], '/exercises/one-arm-kettlebell-bottoms-up-press-main.webp', '/exercises/one-arm-kettlebell-bottoms-up-press-main.webp'),
  ('Press en Puente de Glúteos en Suelo con Pesa Rusa a Un Brazo', 'one-arm-kettlebell-floor-glute-bridge-press', 'glutes', ARRAY['shoulders','hamstrings','triceps'], 'kettlebell', 'intermediate', 'compound', 'Un ejercicio combinado en el suelo que une un puente de glúteos con un press de pesa rusa a un brazo.', ARRAY['Túmbate boca arriba con las rodillas dobladas y los pies planos en el suelo.','Sostén una pesa rusa en una mano a la altura del hombro.','Eleva las caderas en un puente de glúteos.','Empuja la pesa rusa recto hacia el techo.','Baja la pesa rusa y las caderas con control.','Completa las repeticiones de un lado y luego cambia.'], ARRAY['Mantén las caderas elevadas y firmes mientras haces el press.','Sujeta la pesa con la muñeca recta y firme.','Evita que la cadera rote hacia el lado cargado.'], '/exercises/one-arm-kettlebell-floor-glute-bridge-press-main.webp', '/exercises/one-arm-kettlebell-floor-glute-bridge-press-main.webp'),
  ('Press en Suelo con Pesa Rusa a Un Brazo', 'one-arm-kettlebell-floor-press', 'chest', ARRAY['shoulders','triceps'], 'kettlebell', 'intermediate', 'compound', 'Un press de pecho unilateral con pesa rusa ejecutado tumbado en el suelo, que acorta el recorrido y trabaja pectoral y tríceps.', ARRAY['Túmbate boca arriba en el suelo con las rodillas dobladas.','Sostén una pesa rusa en un hombro con una mano.','Empuja la pesa rusa recto hacia arriba hasta que el brazo quede completamente extendido.','Baja la pesa rusa hasta que la parte superior del brazo toque el suelo.','Mantén el core contraído durante todo el ejercicio.','Completa las repeticiones de un lado y luego cambia.'], ARRAY['Apoya el brazo en el suelo con suavidad, sin rebotar.','Sujeta la pesa con la muñeca firme, sin dejar que se doble.','Evita abrir el codo en exceso hacia el lado.'], '/exercises/one-arm-kettlebell-floor-press-main.webp', '/exercises/one-arm-kettlebell-floor-press-main.webp'),
  ('Sentadilla Frontal con Pesa Rusa a Un Brazo', 'one-arm-kettlebell-front-squat', 'glutes', ARRAY['back','hamstrings','core'], 'kettlebell', 'intermediate', 'compound', 'Una sentadilla frontal con una pesa rusa apoyada en un solo hombro, que obliga al core a resistir la inclinación lateral.', ARRAY['Sostén una pesa rusa en posición de rack en un hombro.','De pie con los pies a la anchura de los hombros.','Baja en sentadilla flexionando las rodillas y las caderas.','Mantén el pecho alto y el torso erguido durante todo el ejercicio.','Impulsa a través de los talones para volver a ponerte de pie.','Completa las repeticiones de un lado y luego cambia.'], ARRAY['Resiste la tendencia a inclinarte hacia el lado de la pesa.','Empuja las rodillas hacia afuera en la parte baja.','Mantén el codo pegado al cuerpo bajo la pesa.'], '/exercises/one-arm-kettlebell-front-squat-main.webp', '/exercises/one-arm-kettlebell-front-squat-main.webp'),
  ('Push Press con Pesa Rusa a Un Brazo', 'one-arm-kettlebell-push-press', 'shoulders', ARRAY['glutes','quads','traps','triceps'], 'kettlebell', 'intermediate', 'compound', 'Un press unilateral con pesa rusa que usa un impulso de piernas para llevar el peso por encima de la cabeza.', ARRAY['Sostén una pesa rusa en posición de rack en un hombro.','De pie con los pies a la anchura de los hombros.','Flexiona ligeramente las rodillas.','Extiende las piernas de forma explosiva y empuja la pesa rusa por encima de la cabeza.','Bloquea el codo en la parte superior.','Baja la pesa rusa al hombro con control.','Completa las repeticiones de un lado y luego cambia.'], ARRAY['Haz la flexión de piernas corta y rápida, sin inclinar el torso.','Sincroniza el empuje de piernas con la extensión del brazo.','Aprieta el core al recibir la pesa de vuelta en el hombro.'], '/exercises/one-arm-kettlebell-push-press-main.webp', '/exercises/one-arm-kettlebell-push-press-main.webp'),
  ('Remo con Pesa Rusa a Un Brazo', 'one-arm-kettlebell-row', 'back', ARRAY['biceps','shoulders','traps'], 'kettlebell', 'intermediate', 'compound', 'Un remo unilateral con pesa rusa y apoyo en banco, que fortalece el dorsal ancho y los romboides de cada lado.', ARRAY['Apoya una mano y una rodilla sobre un banco para sujetarte.','Sostén una pesa rusa en la mano contraria con el brazo extendido.','Jala la pesa rusa hacia la cadera llevando el codo hacia atrás.','Aprieta la espalda en la parte superior del movimiento.','Baja la pesa rusa con control.','Completa las repeticiones de un lado y luego cambia.'], ARRAY['Mantén la espalda plana y paralela al suelo.','Evita rotar el torso al subir la pesa.','Tira con la espalda, no solo con el bíceps.'], '/exercises/one-arm-kettlebell-row-main.webp', '/exercises/one-arm-kettlebell-row-main.webp'),
  ('Press de Hombro con Pesa Rusa a Un Brazo', 'one-arm-kettlebell-shoulder-press', 'shoulders', ARRAY['core','traps','triceps'], 'kettlebell', 'intermediate', 'compound', 'Un press de hombro estricto a un brazo con pesa rusa, que exige estabilidad del core para evitar la inclinación lateral.', ARRAY['Sostén una pesa rusa en posición de rack en un hombro.','De pie con los pies a la anchura de las caderas.','Empuja la pesa rusa recto hacia arriba hasta bloquear el codo.','Mantén el core apretado durante todo el ejercicio.','Baja la pesa rusa a la posición de rack con control.','Completa las repeticiones de un lado y luego cambia.'], ARRAY['No te inclines hacia el lado contrario al empujar.','Mantén el antebrazo vertical bajo la pesa durante el recorrido.','Exhala al empujar y evita encoger el hombro hacia la oreja.'], '/exercises/one-arm-kettlebell-shoulder-press-main.webp', '/exercises/one-arm-kettlebell-shoulder-press-main.webp'),
  ('Swing con Pesa Rusa a Un Brazo', 'one-arm-kettlebell-swing', 'glutes', ARRAY['shoulders','back','core'], 'kettlebell', 'intermediate', 'compound', 'Un swing de pesa rusa a un brazo, un movimiento balístico de bisagra de cadera que desarrolla potencia en glúteos e isquiotibiales.', ARRAY['De pie con los pies a la anchura de los hombros y la pesa rusa en el suelo frente a ti.','Bisagra en las caderas y agarra la pesa rusa con una mano.','Lleva la pesa rusa hacia atrás entre las piernas.','Impulsa las caderas hacia adelante para lanzar la pesa rusa hasta la altura del pecho.','Deja que la gravedad lleve la pesa rusa de vuelta entre las piernas.','Completa las repeticiones de un lado y luego cambia.'], ARRAY['Genera la potencia con la cadera, no con el brazo.','Mantén la espalda recta cuando la pesa pase entre las piernas.','No dejes que la pesa tire del hombro hacia delante.'], '/exercises/one-arm-kettlebell-swing-main.webp', '/exercises/one-arm-kettlebell-swing-main.webp'),
  ('Extensión de Tríceps a Un Brazo con Pesa Rusa', 'one-arm-kettlebell-tricep-kickback', 'triceps', ARRAY['shoulders'], 'kettlebell', 'beginner', 'isolation', 'Una extensión de tríceps unilateral con pesa rusa: inclínate, fija el brazo al costado paralelo al suelo y extiende el codo hacia atrás.', ARRAY['Inclínate hacia delante flexionando las caderas con la espalda recta y las rodillas ligeramente flexionadas.','Sujeta una pesa rusa por el asa con una mano, con la palma hacia el cuerpo.','Fija la parte alta del brazo al costado de modo que quede paralela al suelo; el antebrazo cuelga recto hacia abajo.','Extiende el codo hacia atrás para estirar el brazo del todo por detrás de ti, manteniendo inmóvil la parte alta del brazo.','Aprieta el tríceps en la extensión completa y vuelve de forma controlada a la posición inicial.','Completa todas las repeticiones de un lado y luego cambia de mano.'], ARRAY['La parte alta del brazo no se mueve, solo el antebrazo; balancear el hombro es trampa.','Bloquea la pesa un instante en la extensión completa; tiende a hundirte la muñeca.','Usa una pesa más ligera que en una extensión con mancuerna; la carga descentrada cuesta más de estabilizar.'], '/exercises/one-arm-kettlebell-tricep-kickback-main.webp', '/exercises/one-arm-kettlebell-tricep-kickback-main.webp'),
  ('Press Landmine con Un Brazo', 'one-arm-landmine-press', 'shoulders', ARRAY['core','triceps'], 'barbell', 'intermediate', 'compound', 'Una variante de press sobre la cabeza unilateral con montaje landmine que sigue un arco natural, reduciendo el riesgo de impingement de hombro.', ARRAY['Ancla un extremo de la barra en el accesorio landmine y carga el extremo libre.','Arrodíllate en una rodilla o párate y sujeta el extremo libre a la altura del hombro con una mano.','Empuja la barra hacia arriba y adelante siguiendo su arco hasta extender completamente el brazo.','Baja la barra de regreso a la altura del hombro con control.','Completa todas las repeticiones antes de cambiar de lado.'], ARRAY['Activa el core para evitar que el torso rote hacia el brazo de trabajo.','El movimiento en arco es más amigable para las articulaciones que un press estricto.','Arrodillarse en la rodilla contraria aumenta la demanda antirotacional del core.'], '/exercises/one-arm-landmine-press-main.webp', '/exercises/one-arm-landmine-press-main.webp')
) as v(name, slug, muscle_slug, secondary_slugs, equipment_slug, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url)
on conflict (slug) do nothing;

insert into public.exercises (name, slug, primary_muscle_group_id, secondary_muscle_group_ids, equipment_id, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url, image_source, image_license)
select v.name, v.slug,
  (select id from public.muscle_groups where slug = v.muscle_slug),
  coalesce((select array_agg(id) from public.muscle_groups where slug = any(v.secondary_slugs)), '{}'),
  (select id from public.equipment where slug = v.equipment_slug),
  v.difficulty::public.exercise_difficulty,
  v.movement_type::public.movement_type,
  v.description, v.instructions, v.tips, v.image_url, v.thumbnail_url,
  'RepDB (repdb.co)', 'Free tier - commercial in-app use with attribution'
from (values
('Jalón al Pecho con Un Brazo', 'one-arm-lat-pulldown', 'back', ARRAY['biceps','shoulders'], 'cable', 'intermediate', 'compound', 'Un jalón en cable unilateral con manija individual que trabaja el dorsal ancho permitiendo mayor rango de movimiento y corrección de desequilibrios.', ARRAY['Sujeta una manija individual al jalón de cable y siéntate con los muslos asegurados bajo el soporte.','Agarra la manija con una mano, brazo completamente extendido.','Tira de la manija hacia tu hombro llevando el codo hacia la cadera.','Pausa brevemente en la contracción máxima, luego vuelve con control.','Completa todas las repeticiones en un lado antes de cambiar.'], ARRAY['Inclínate ligeramente alejándote del cable para maximizar el estiramiento del dorsal arriba.','Tira con el codo, no con la mano, para mantener el dorsal activado.','Controla la fase excéntrica para maximizar la tensión en el dorsal durante todo el rango.'], '/exercises/one-arm-lat-pulldown-main.webp', '/exercises/one-arm-lat-pulldown-main.webp'),
  ('Peso Muerto Rumano a Una Pierna con Mancuerna a Un Brazo', 'one-arm-single-leg-dumbbell-romanian-deadlift', 'glutes', ARRAY['back','forearms','core'], 'dumbbell', 'advanced', 'compound', 'Un peso muerto rumano a una pierna sosteniendo una mancuerna en una sola mano, generalmente la opuesta a la pierna de apoyo (contralateral). Carga los isquiotibiales y glúteos de la pierna de apoyo mientras exige una fuerte contención anti-rotación del core.', ARRAY['De pie sobre una pierna, sostén una mancuerna en la mano contraria.','Brazo libre al costado para equilibrarte, pierna libre suspendida justo por encima del suelo.','Bisagra en la cadera de apoyo empujándola hacia atrás mientras la pierna libre se extiende detrás para contrarrestar el peso.','Mantén las caderas cuadradas al suelo; no las abras hacia el lado.','Baja la mancuerna hacia el pie de la pierna de apoyo sintiendo un estiramiento profundo en los isquiotibiales.','Impulsa la cadera hacia adelante para volver a ponerte de pie con control.','Completa todas las repeticiones de un lado y luego cambia.'], ARRAY['Empieza con menos peso del que crees; el equilibrio y la demanda anti-rotación son el factor limitante, no la fuerza de los isquiotibiales.','Si rotas, haz una pausa y reinicia; un recorrido limpio más corto es mejor que uno completo con rotación.','Fijar la vista en un punto fijo en el suelo a un par de metros al frente ayuda con el equilibrio.'], '/exercises/one-arm-single-leg-dumbbell-romanian-deadlift-main.webp', '/exercises/one-arm-single-leg-dumbbell-romanian-deadlift-main.webp'),
  ('Peso Muerto Rumano a Una Pierna con Pesa Rusa a Un Brazo', 'one-arm-single-leg-kettlebell-romanian-deadlift', 'glutes', ARRAY['back','forearms','core'], 'kettlebell', 'advanced', 'compound', 'La versión con pesa rusa del peso muerto rumano a una pierna y un brazo. La masa excéntrica de la pesa rusa y su centro de gravedad más bajo lo convierten en un reto sutilmente diferente al de la mancuerna; excelente para la fuerza de la cadena posterior y el equilibrio bajo carga asimétrica.', ARRAY['De pie sobre una pierna, sostén una pesa rusa en la mano contraria por el asa.','Brazo libre al costado para equilibrarte, pierna libre suspendida detrás.','Bisagra en la cadera de apoyo empujándola hacia atrás mientras la pierna libre se extiende para contrarrestar el peso.','Mantén las caderas cuadradas al suelo; la pesa rusa desciende recto por la espinilla.','Siente un estiramiento profundo en los isquiotibiales de la pierna de apoyo en la parte inferior.','Impulsa la cadera hacia adelante para volver a ponerte de pie.','Completa todas las repeticiones de un lado y luego cambia.'], ARRAY['La pesa rusa cuelga más bajo que una mancuerna; acorta ligeramente el recorrido para mantener la espalda plana.','Si la pesa oscila, estás yendo demasiado rápido. Desacelera la fase excéntrica.','Primero domina el peso muerto rumano a una pierna con dos mancuernas antes de progresar a este ejercicio.'], '/exercises/one-arm-single-leg-kettlebell-romanian-deadlift-main.webp', '/exercises/one-arm-single-leg-kettlebell-romanian-deadlift-main.webp'),
  ('Sentadilla con Barra en Alto', 'overhead-squat', 'glutes', ARRAY['back','shoulders','traps'], 'barbell', 'intermediate', 'compound', 'Una sentadilla con la barra bloqueada por encima de la cabeza con agarre ancho de arrancada, que exige movilidad, estabilidad y un core fuerte.', ARRAY['Sostén una barra por encima de la cabeza con un agarre ancho de arrancada y los codos bloqueados.','De pie con los pies ligeramente más abiertos que la anchura de los hombros.','Baja en sentadilla empujando las caderas hacia atrás y doblando las rodillas.','Mantén la barra directamente sobre el punto medio de los pies.','Impulsa a través de los talones para volver a ponerte de pie.','Repite el número de repeticiones deseado.'], ARRAY['Gira las axilas hacia delante para fijar la barra en su sitio.','Mantén la barra sobre el mediopié, con el torso más erguido que en una sentadilla trasera.','Trabaja la movilidad de hombros y tobillos antes de añadir peso.'], '/exercises/overhead-squat-main.webp', '/exercises/overhead-squat-main.webp'),
  ('Extensión de Tríceps por Encima de la Cabeza', 'overhead-tricep-extension', 'triceps', NULL, 'dumbbell', 'beginner', 'isolation', 'Un ejercicio de aislamiento para el tríceps que enfatiza la cabeza larga.', ARRAY['De pie o sentado, sostén una mancuerna por encima de la cabeza con ambas manos.','Baja la mancuerna detrás de la cabeza doblando los codos.','Extiende los brazos de vuelta a la posición inicial.','Mantén los codos cerca de la cabeza durante todo el ejercicio.','Repite.'], ARRAY['Mueve solo los antebrazos y mantén quieto todo lo demás.','Evita arquear la zona lumbar cuando la mancuerna baje.','Agarra la mancuerna por debajo del disco superior con ambas palmas.'], '/exercises/overhead-tricep-extension-main.webp', '/exercises/overhead-tricep-extension-main.webp'),
  ('Estiramiento de Tríceps sobre la Cabeza', 'overhead-triceps-stretch', 'triceps', ARRAY['back'], NULL, 'beginner', 'mobility', 'Un estiramiento de pie que alarga el tríceps y el dorsal llevando la mano por la espalda alta.', ARRAY['Sube un brazo sobre la cabeza y flexiona el codo.','Deja caer la mano por detrás de la cabeza.','Con la otra mano empuja el codo flexionado hacia atrás.','Mantén de 20 a 30 segundos, respirando de forma constante.','Cambia de lado y repite.'], ARRAY['Mantén la cabeza erguida, no la empujes hacia adelante.','Relájate y sigue respirando todo el tiempo.'], '/exercises/overhead-triceps-stretch-main.webp', '/exercises/overhead-triceps-stretch-main.webp'),
  ('Peso Muerto con Pausa', 'pause-deadlift', 'back', ARRAY['quads','traps'], 'barbell', 'advanced', 'compound', 'Una variante del peso muerto con una pausa deliberada justo por debajo de las rodillas para desarrollar fuerza desde el suelo.', ARRAY['Colócate en posición de peso muerto convencional.','Levanta la barra del suelo y haz una pausa cuando pase por las rodillas.','Mantén la posición 2-3 segundos y luego completa el levantamiento.','Baja con control.','Repite.'], ARRAY['La pausa elimina el impulso y desarrolla la fuerza de inicio.','Mantén la espalda plana durante la pausa.'], '/exercises/pause-deadlift-main.webp', '/exercises/pause-deadlift-main.webp'),
  ('Dominada con Pausa', 'pause-pull-up', 'back', ARRAY['biceps','shoulders','traps'], 'bodyweight', 'advanced', 'compound', 'Una variante de dominada que añade una breve pausa isométrica en la parte superior del movimiento, con la barbilla sobre la barra, antes de bajar de nuevo.', ARRAY['Cuélgate de una barra de dominadas con agarre prono, brazos completamente extendidos.','Tira de tu cuerpo hacia arriba hasta que la barbilla supere la barra.','Haz una pausa y mantén esa posición superior un momento.','Baja con control de vuelta a la posición de colgado completo.','Repite el número deseado de repeticiones.'], ARRAY['La pausa elimina el impulso, así que el tirón es más difícil que en una dominada normal -- espera menos repeticiones.','Mantén los hombros activos durante la pausa en lugar de relajarte colgando de la barra.','Baja despacio en vez de caer directamente a la siguiente repetición.'], '/exercises/pause-pull-up-main.webp', '/exercises/pause-pull-up-main.webp'),
  ('Sentadilla con Pausa', 'pause-squat', 'glutes', ARRAY['back','hamstrings'], 'barbell', 'intermediate', 'compound', 'Una sentadilla con barra que incluye una pausa de varios segundos en la posición baja para eliminar el rebote y reforzar la salida del fondo.', ARRAY['Saca la barra del rack y apóyala sobre la parte superior de la espalda.','De pie con los pies a la anchura de los hombros.','Baja en sentadilla hasta que los muslos queden paralelos al suelo.','Mantén la posición inferior durante 2-3 segundos.','Impulsa a través de los talones para volver a ponerte de pie.','Repite el número de repeticiones deseado.'], ARRAY['Mantén la tensión en la pausa; no te relajes en el fondo.','Coge aire arriba y mantén el abdomen firme toda la repetición.','Mantén el pecho alto para que la barra no te venza hacia delante.'], '/exercises/pause-squat-main.webp', '/exercises/pause-squat-main.webp'),
  ('Press de Banca con Pausa', 'paused-bench-press', 'chest', ARRAY['shoulders','triceps'], 'barbell', 'advanced', 'compound', 'Un press de banca con barra en el que la pausa sobre el pecho elimina el rebote y endurece la fase inicial del empuje.', ARRAY['Túmbate en un banco plano y agarra la barra ligeramente más abierta que la anchura de los hombros.','Saca la barra del rack y bájala hasta el pecho.','Haz una pausa sobre el pecho durante 1-2 segundos.','Empuja la barra hacia arriba hasta que los brazos queden completamente extendidos.','Controla el descenso en cada repetición.','Repite el número de repeticiones deseado.'], ARRAY['No dejes que la barra se hunda en el pecho durante la pausa.','Mantén los omóplatos retraídos y pegados al banco.','Pide que alguien te asista cuando muevas cargas altas.'], '/exercises/paused-bench-press-main.webp', '/exercises/paused-bench-press-main.webp'),
  ('Press Inclinado con Pausa', 'paused-incline-bench-press', 'shoulders', ARRAY['triceps'], 'barbell', 'advanced', 'compound', 'Un press inclinado con barra y pausa sobre la parte alta del pecho, que elimina el rebote y enfatiza pectoral superior y deltoides anterior.', ARRAY['Túmbate en un banco inclinado y agarra la barra ligeramente más abierta que la anchura de los hombros.','Saca la barra del rack y bájala hasta el pecho superior.','Haz una pausa sobre el pecho durante 1-2 segundos.','Empuja la barra hacia arriba hasta que los brazos queden completamente extendidos.','Mantén los omóplatos retraídos durante todo el ejercicio.','Repite el número de repeticiones deseado.'], ARRAY['No acortes la pausa cuando la carga se haga pesada.','Mantén las muñecas firmes sobre los codos durante el recorrido.','Mantén los pies firmes en el suelo durante toda la serie.'], '/exercises/paused-incline-bench-press-main.webp', '/exercises/paused-incline-bench-press-main.webp'),
  ('Press militar con pausa', 'paused-ohp', 'shoulders', ARRAY['traps','triceps'], 'barbell', 'advanced', 'compound', 'Una variante del press militar que hace una pausa con la barra a la altura de los hombros, eliminando el impulso para desarrollar fuerza de empuje estricta y estabilidad por encima de la cabeza.', ARRAY['Colócate con la barra a la altura de los hombros, pies al ancho de los hombros y el core firme.','Empuja la barra recta por encima de la cabeza hasta bloquear los codos.','Baja la barra de forma controlada hasta el frente de los hombros.','Mantén una pausa completa de un segundo en los hombros, conservando la tensión y evitando cualquier rebote.','Vuelve a empujar desde la posición estática sin usar impulso de piernas.'], ARRAY['Mantén la pausa estricta: sin rebotar la barra en los hombros.','Aprieta el core y mantén la trayectoria de la barra vertical sobre el medio del pie.','Usa un peso que puedas controlar desde el arranque estático.'], '/exercises/paused-ohp-main.webp', '/exercises/paused-ohp-main.webp'),
  ('Pec Deck', 'pec-deck', 'chest', ARRAY['shoulders','core'], 'machine', 'beginner', 'isolation', 'Una máquina de aislamiento de pecho con almohadillas de codo fijas que trabaja los pectorales mediante aducción horizontal.', ARRAY['Siéntate en la máquina pec deck y coloca los antebrazos contra las almohadillas.','Ajusta el asiento para que las almohadillas queden a la altura media del pecho.','Junta las almohadillas frente al pecho apretando.','Mantén la contracción brevemente en el centro.','Regresa con control a la posición inicial.','Repite el número de repeticiones deseado.'], ARRAY['No dejes que los brazos viajen demasiado atrás al abrir.','Mantén la espalda y los hombros pegados al respaldo.','Exhala al juntar las almohadillas e inhala al abrir.'], '/exercises/pec-deck-main.webp', '/exercises/pec-deck-main.webp'),
  ('Remo Pendlay', 'pendlay-row', 'back', ARRAY['biceps','shoulders'], 'barbell', 'intermediate', 'compound', 'Un remo estricto con barra realizado desde una parada muerta en el suelo entre repeticiones con el torso paralelo al suelo. Popularizado por el entrenador Glenn Pendlay.', ARRAY['Carga una barra y colócala en el suelo.','Bisagra en las caderas hasta que el torso quede paralelo al suelo con las rodillas ligeramente dobladas.','Agarra la barra ligeramente más abierta que la anchura de los hombros con un agarre en pronación.','Jala la barra de forma explosiva hacia el pecho inferior.','Baja la barra al suelo con control y haz una pausa antes de la siguiente repetición.','Repite.'], ARRAY['Cada repetición debe comenzar desde el suelo sin rebote.','Mantén el torso fijo a aproximadamente 90 grados; no uses el impulso del cuerpo.','Lleva los codos hacia arriba y atrás, no hacia los lados.'], '/exercises/pendlay-row-main.webp', '/exercises/pendlay-row-main.webp'),
  ('Estiramiento de la Paloma', 'pigeon-stretch', 'glutes', ARRAY['core'], NULL, 'beginner', 'mobility', 'Un estiramiento sentado en el suelo para los glúteos y la cadera externa, con la espinilla delantera cruzada al frente.', ARRAY['Desde cuadrupedia, lleva una rodilla adelante y apoya la espinilla cruzada al frente.','Extiende la otra pierna recta hacia atrás, con el empeine en el suelo.','Baja la cadera hacia el suelo y mantenla cuadrada.','Mantén de 20 a 30 segundos, respirando de forma constante.','Cambia de lado y repite.'], ARRAY['Coloca un cojín bajo la cadera si no llega al suelo.','Camina las manos hacia adelante para profundizar el estiramiento.'], '/exercises/pigeon-stretch-main.webp', '/exercises/pigeon-stretch-main.webp'),
  ('Flexiones en Pica', 'pike-push-ups', 'shoulders', ARRAY['traps','triceps'], NULL, 'intermediate', 'compound', 'Una flexión realizada con las caderas elevadas en posición de pica, empujando en un ángulo pronunciado para cargar los hombros.', ARRAY['Comienza en posición de perro boca abajo con las caderas altas y las manos a la anchura de los hombros.','Acerca los pies a las manos.','Dobla los codos y baja la cabeza hacia el suelo.','Mantén las caderas altas durante todo el ejercicio.','Empuja hacia arriba hasta que los brazos queden completamente extendidos.','Repite el número de repeticiones deseado.'], ARRAY['Cuanto más altas las caderas, más trabajan los hombros.','Baja la cabeza hacia un punto ligeramente por delante de las manos.','Acerca los pies a las manos para progresar hacia las flexiones en pino.'], '/exercises/pike-push-ups-main.webp', '/exercises/pike-push-ups-main.webp'),
  ('Patada Lateral de Rodillas de Pilates', 'pilates-kneeling-side-kick', 'glutes', ARRAY['core'], NULL, 'intermediate', 'compound', 'Un ejercicio clásico de suelo: de rodillas con la mano apoyada en el suelo, la pierna de arriba oscila adelante y atrás a la altura de la cadera mientras el tronco permanece inmóvil.', ARRAY['Arrodíllate y apoya en el suelo la mano del mismo lado, con la otra mano detrás de la cabeza.','Extiende la pierna de arriba hacia el lado a la altura de la cadera, con el pie en flexión.','Mantén el tronco completamente quieto y lleva la pierna hacia delante mientras la pelvis siga cuadrada.','Lleva la pierna por detrás de la línea del cuerpo sin arquear la zona lumbar.','Repite las veces indicadas y cambia de lado.'], ARRAY['El tronco es el ejercicio: si se balancea con la pierna, acorta el recorrido.','Mantén el hombro de apoyo alejado de la oreja.','Trabaja a un ritmo controlado en lugar de lanzar la pierna.'], '/exercises/pilates-kneeling-side-kick-main.webp', '/exercises/pilates-kneeling-side-kick-main.webp'),
  ('Leg Pull Back de Pilates', 'pilates-leg-pull-back', 'back', ARRAY['hamstrings','shoulders','triceps'], NULL, 'intermediate', 'compound', 'Una plancha invertida con elevaciones alternas de pierna: las caderas se mantienen altas mientras se eleva una pierna cada vez, de modo que glúteos y parte posterior del tronco trabajan ante el apoyo cambiante.', ARRAY['Siéntate con las piernas estiradas y las manos en el suelo detrás de las caderas, con los dedos hacia delante.','Empuja con manos y talones y eleva las caderas a una plancha invertida.','Con las caderas niveladas y altas, eleva una pierna estirada mientras la pelvis siga quieta.','Baja la pierna de forma controlada y repite con la otra.','Termina la serie y baja las caderas al suelo.'], ARRAY['Detén la elevación donde las caderas empiecen a caer; la altura no es el objetivo.','Mantén el pecho abierto y los hombros lejos de las orejas.','Flexiona un poco las rodillas si la versión con piernas estiradas tira de los isquiotibiales.'], '/exercises/pilates-leg-pull-back-main.webp', '/exercises/pilates-leg-pull-back-main.webp'),
('Leg Pull Front de Pilates', 'pilates-leg-pull-front', 'glutes', ARRAY['shoulders','back','core'], NULL, 'intermediate', 'compound', 'Una plancha alta con elevaciones alternas de pierna: los hombros permanecen sobre las muñecas mientras se eleva una pierna cada vez, lo que añade una demanda antirrotación a la plancha.', ARRAY['Colócate en plancha alta con las manos bajo los hombros y el cuerpo en línea.','Aprieta el tronco y los glúteos para que las caderas no puedan rotar.','Eleva una pierna estirada unos centímetros por encima de la cadera sin que la pelvis se incline.','Bájala de forma controlada y repite con la otra pierna.','Sigue alternando las veces indicadas.'], ARRAY['Eleva la pierna desde el glúteo y no arqueando la zona lumbar.','Reparte el peso entre ambas manos; la tendencia es inclinarse lejos del lado que se eleva.','Reduce la altura hasta que las caderas se mantengan perfectamente niveladas.'], '/exercises/pilates-leg-pull-front-main.webp', '/exercises/pilates-leg-pull-front-main.webp'),
  ('Roll Down de Pilates', 'pilates-roll-down', 'back', ARRAY['hamstrings','core'], NULL, 'beginner', 'mobility', 'Una articulación de la columna de pie: la cabeza guía un descenso vértebra a vértebra hacia el suelo y de vuelta, movilizando toda la espalda mientras las piernas se mantienen estables.', ARRAY['Ponte de pie con los pies a la anchura de las caderas y los brazos colgando a los lados.','Lleva la barbilla al pecho y empieza a rodar hacia abajo vértebra a vértebra.','Deja los brazos y la cabeza colgando pesados cuando la columna esté completamente descendida.','Sube por el mismo camino, apilando las vértebras una a una, la cabeza al final.','Repite las veces indicadas.'], ARRAY['Mantén las rodillas blandas para que el movimiento venga de la columna y no de los isquiotibiales.','Ve lo bastante despacio como para sentir cada segmento; la velocidad arruina el ejercicio.','Mantén el peso en el centro de los pies mientras bajas.'], '/exercises/pilates-roll-down-main.webp', '/exercises/pilates-roll-down-main.webp'),
  ('Roll Over de Pilates', 'pilates-roll-over', 'core', ARRAY['back'], NULL, 'advanced', 'compound', 'Una inversión controlada desde la colchoneta: con los brazos presionando el suelo, las piernas estiradas viajan por encima de la cabeza hasta que los pies apuntan al suelo, y después la columna vuelve a bajar segmento a segmento.', ARRAY['Túmbate boca arriba con las piernas estiradas y los brazos presionando la colchoneta a los lados.','Eleva ambas piernas a la vertical sin dejar que la zona lumbar se arquee.','Presiona los brazos hacia abajo y lleva las piernas por encima de la cabeza hasta dejarlas paralelas al suelo por detrás.','Abre un poco las piernas, flexiona los pies y baja la columna vértebra a vértebra.','Devuelve las piernas a la vertical y repite las veces indicadas.'], ARRAY['Impulsa el movimiento con el abdomen, no lanzando las piernas.','Mantén el peso fuera del cuello: el descenso se detiene en las escápulas.','Evita este ejercicio si tienes molestias cervicales y constrúyelo antes con curls más pequeños.'], '/exercises/pilates-roll-over-main.webp', '/exercises/pilates-roll-over-main.webp'),
  ('La Sierra de Pilates', 'pilates-saw', 'back', ARRAY['adductors','hamstrings'], NULL, 'intermediate', 'mobility', 'Un giro con flexión sentado: sentado erguido con las piernas abiertas, el torso rota y después se pliega sobre la pierna contraria para que la mano que alcanza pase junto al dedo meñique como una sierra.', ARRAY['Siéntate erguido con las piernas estiradas y algo más abiertas que las caderas, los brazos hacia los lados.','Rota el torso hacia un lado manteniendo ambos isquiones en el suelo.','Pliégate hacia delante sobre esa pierna y alcanza con la mano contraria más allá del dedo meñique.','Vuelve a subir a través de la columna y regresa al centro.','Repite hacia el otro lado y sigue alternando.'], ARRAY['Ancla ambos isquiones; si uno se levanta, el giro se convierte en una inclinación.','Primero rota y después pliégate: ese orden es lo que hace funcionar el ejercicio.','Siéntate sobre una manta doblada si la pelvis no puede mantenerse erguida.'], '/exercises/pilates-saw-main.webp', '/exercises/pilates-saw-main.webp'),
  ('Flexión Lateral de Pilates', 'pilates-side-bend', 'glutes', ARRAY['shoulders','core'], NULL, 'intermediate', 'compound', 'Un ejercicio lateral del tronco desde un apoyo de costado: las caderas se elevan y el brazo de arriba se estira por encima de la cabeza, curvando el cuerpo de lado sobre el brazo de apoyo.', ARRAY['Siéntate sobre una cadera con las piernas dobladas hacia un lado y la mano de apoyo en el suelo bajo el hombro.','Empuja con la mano y la pierna inferior para elevar las caderas del suelo.','Estira el brazo de arriba por encima de la cabeza para formar un arco largo desde la mano hasta los pies.','Baja las caderas de forma controlada hacia la colchoneta.','Completa las repeticiones y cambia de lado.'], ARRAY['Empuja el suelo para que el hombro de apoyo quede estable y alineado.','Alarga el brazo de arriba en lugar de dejarte caer hacia el lado.','Mantén el movimiento fluido: subir y bajar duran lo mismo.'], '/exercises/pilates-side-bend-main.webp', '/exercises/pilates-side-bend-main.webp'),
  ('Spine Stretch Forward de Pilates', 'pilates-spine-stretch-forward', 'back', ARRAY['hamstrings','core'], NULL, 'intermediate', 'mobility', 'Una articulación sentada: sentado erguido con las piernas abiertas, la columna se enrolla hacia delante segmento a segmento sobre las piernas y después vuelve a apilarse vértebra a vértebra.', ARRAY['Siéntate erguido con las piernas estiradas y algo más abiertas que las caderas, los pies en flexión.','Estira los brazos hacia delante a la altura de los hombros.','Baja la barbilla y enrolla la columna hacia delante vértebra a vértebra, alcanzando más allá de los pies.','Vuelve a apilar la columna desde la base hasta quedar sentado erguido.','Repite las veces indicadas.'], ARRAY['Mantén la pelvis erguida: la curva viene de la columna, no de bascular la cadera.','Empuja los talones hacia fuera todo el tiempo para que las piernas sigan activas.','Siéntate sobre una manta doblada si ya sentarte erguido te redondea la zona lumbar.'], '/exercises/pilates-spine-stretch-forward-main.webp', '/exercises/pilates-spine-stretch-forward-main.webp'),
  ('Spine Twist de Pilates', 'pilates-spine-twist', 'core', ARRAY['back'], NULL, 'intermediate', 'mobility', 'Una rotación sentada con las piernas juntas y los brazos abiertos: el tronco gira a cada lado de forma controlada mientras la pelvis y las piernas permanecen completamente quietas.', ARRAY['Siéntate erguido con las piernas estiradas y juntas, los pies en flexión y los brazos abiertos a la altura de los hombros.','Crece a través de la columna y presiona ambos isquiones contra el suelo.','Rota el tronco hacia un lado mientras las caderas sigan cuadradas y vuelve al centro.','Rota hacia el otro lado del mismo modo.','Sigue alternando las veces indicadas.'], ARRAY['Las piernas son el ancla: si un pie se adelanta, la pelvis se ha movido.','Alárgate hacia arriba antes de cada rotación en lugar de hundirte en ella.','Gira la cabeza con el tronco en lugar de que ella lidere.'], '/exercises/pilates-spine-twist-main.webp', '/exercises/pilates-spine-twist-main.webp'),
  ('Sentadilla a una Pierna (Pistol)', 'pistol-squat', 'glutes', ARRAY['hamstrings','core'], NULL, 'advanced', 'compound', 'Una sentadilla a una pierna con la pierna libre extendida adelante, que exige fuerza y equilibrio.', ARRAY['Mantente sobre una pierna, la otra extendida al frente, brazos al lado para equilibrio.','Flexiona la cadera y la rodilla de apoyo, manteniendo el pecho arriba.','Baja lentamente hasta que la parte posterior del muslo toque la pantorrilla.','Empuja con el talón de apoyo para volver a subir.','Repeticiones por lado, luego cambia de pierna.'], ARRAY['Sostén un contrapeso ligero al pecho si te cuesta el equilibrio.','Construye la fuerza primero con pistol asistido sobre cajón.','Mantén el talón de trabajo plano en el suelo.'], '/exercises/pistol-squat-main.webp', '/exercises/pistol-squat-main.webp'),
  ('Plancha Calisténica', 'planche', 'shoulders', ARRAY['core','triceps'], NULL, 'advanced', 'compound', 'Una posición avanzada de calistenia que requiere una fuerza excepcional del tren superior y el core para mantener el cuerpo paralelo al suelo.', ARRAY['Comienza en posición de flexión con las manos giradas hacia afuera.','Inclínate hacia adelante hasta que tu centro de masa quede sobre las manos.','Levanta los pies del suelo manteniendo el cuerpo horizontal.','Mantén la posición.','Regresa al suelo con control.'], ARRAY['Progresa a través de la posición encogida, en estrella y la plancha completa.','Desarrolla la fuerza de muñecas y hombros antes de intentarlo.'], '/exercises/planche-main.webp', '/exercises/planche-main.webp'),
  ('Elevación de Pantorrilla a la Burra en Máquina', 'plate-loaded-donkey-calf-raise', 'calves', NULL, 'machine', 'beginner', 'isolation', 'Una elevación de pantorrilla a la burra en una máquina de discos, con una almohadilla sobre las caderas y el torso inclinado hacia delante para estirar los gemelos en la parte baja de cada repetición.', ARRAY['Carga los soportes de discos y sube a la plataforma con los metatarsos en el borde y los talones al aire.','Inclínate hacia delante desde las caderas, coloca la almohadilla sobre ellas y apoya los antebrazos en el soporte que tienes delante.','Mantén las rodillas estiradas y la espalda plana, con el torso cerca de la paralela al suelo.','Empuja con los metatarsos y eleva los talones tan alto como puedas, con una pausa breve arriba.','Baja los talones por debajo de la plataforma hasta notar un estiramiento fuerte en los gemelos y repite el número de repeticiones deseado.'], ARRAY['La inclinación hacia delante es el ejercicio. Ponerte erguido lo convierte en una elevación de talones de pie corriente y regala justo el estiramiento extra que venías a buscar.','Mantén las rodillas estiradas todo el tiempo. Flexionarlas traslada el trabajo del gemelo al sóleo, y eso es la elevación sentado, no esta.','Deja que los talones bajen del todo por debajo del borde de la plataforma. La parte baja del recorrido es lo que justifica esta máquina, y recortarla desperdicia todo el montaje.'], '/exercises/plate-loaded-donkey-calf-raise-main.webp', '/exercises/plate-loaded-donkey-calf-raise-main.webp'),
  ('Empuje de Glúteo en Máquina de Discos', 'plate-loaded-glute-drive', 'glutes', ARRAY['hamstrings','quads'], 'machine', 'beginner', 'compound', 'Un empuje de cadera en una máquina de glúteo de discos, donde el respaldo y la plataforma integrados fijan la posición para que las caderas extiendan contra la carga sin tener que montar un banco.', ARRAY['Carga los soportes de discos por igual y siéntate en la máquina con la parte alta de la espalda contra el respaldo y los pies planos en la plataforma.','Baja la almohadilla o barra sobre tus caderas y ajústala para que apoye en el pliegue de la cadera y no sobre el abdomen.','Coloca los pies de modo que las espinillas queden verticales cuando las caderas estén arriba, y sujeta las empuñaduras.','Empuja las caderas hacia arriba apretando los glúteos hasta que los muslos queden alineados con el torso, y mantén un instante arriba.','Baja de forma controlada hasta justo antes del final del recorrido y repite el número de repeticiones deseado.'], ARRAY['Coloca la almohadilla en el pliegue de la cadera. Dejarla sobre el abdomen es lo único realmente incómodo de esta máquina, y se resuelve moviendo la almohadilla, no añadiendo acolchado.','Termina el movimiento con la cadera, no con la zona lumbar. Si arriba se te abren las costillas es que se acabó la extensión de cadera y has empezado a arquear, que es donde la máquina deja de entrenar el glúteo.','Este es el empuje de cadera al que recurrir cuando el banco y la barra están ocupados: el respaldo y la plataforma forman parte del bastidor, así que no hay montaje que hacer mal.'], '/exercises/plate-loaded-glute-drive-main.webp', '/exercises/plate-loaded-glute-drive-main.webp'),
  ('Elevación Lateral en Máquina de Discos', 'plate-loaded-lateral-raise', 'shoulders', ARRAY['traps'], 'machine', 'beginner', 'isolation', 'Una elevación lateral sentado en una máquina de discos, donde unas almohadillas apoyan contra los brazos para que los deltoides laterales levanten la carga sin sujetarla con las manos.', ARRAY['Ajusta la altura del asiento para que el eje de giro de las almohadillas quede alineado con la punta de tus hombros al sentarte.','Carga los soportes de discos por igual en ambos lados y siéntate con la espalda apoyada en el respaldo.','Coloca la cara externa de los brazos contra las almohadillas, con los codos flexionados y los brazos colgando.','Empuja hacia fuera y hacia arriba contra las almohadillas hasta que los brazos queden aproximadamente a la altura de los hombros.','Baja de forma controlada hasta que los brazos vuelvan a los costados y repite el número de repeticiones deseado.'], ARRAY['Ajusta primero el asiento. Si el eje queda por debajo del hombro, las almohadillas llevan el brazo cruzado por delante del cuerpo en lugar de hacia el lado, y el deltoides lateral deja de ser el músculo que trabaja.','Empuja con el brazo, no con la mano. Las empuñaduras solo sirven para que los brazos no resbalen de las almohadillas: apretarlas mete el bíceps y el antebrazo en una elevación que debería ser puro deltoides.','Detente a la altura del hombro. Subir más entrega la última parte de la repetición al trapecio, y la máquina te dejará hacerlo sin protestar.'], '/exercises/plate-loaded-lateral-raise-main.webp', '/exercises/plate-loaded-lateral-raise-main.webp'),
  ('Encogimiento de Hombros en Máquina de Discos', 'plate-loaded-shrug', 'traps', ARRAY['forearms'], 'machine', 'beginner', 'isolation', 'Un encogimiento de hombros de pie en una máquina de discos, levantando unas empuñaduras que cuelgan a los costados para que el trapecio trabaje sin una barra por delante o por detrás de las piernas.', ARRAY['Carga los soportes de discos por igual y súbete a la plataforma de la máquina, de espaldas al bastidor.','Toma una empuñadura con cada mano, con los brazos colgando rectos a los costados y los hombros relajados.','Ponte erguido con el pecho alto, la barbilla nivelada y las rodillas ligeramente flexionadas.','Encoge los hombros en línea recta hacia las orejas todo lo que puedas y mantén un instante arriba.','Baja de forma controlada hasta que los hombros queden completamente abajo y repite el número de repeticiones deseado.'], ARRAY['Encoge en línea recta hacia arriba. Rotar los hombros añade recorrido pero no trabajo extra del trapecio, y lleva la articulación del hombro a describir un círculo bajo carga para nada.','Mantén los brazos rectos y pasivos. Flexionar los codos convierte el movimiento en un remo vertical corto y quita la carga del trapecio.','Las empuñaduras colgando a los costados son la razón de ser de esta máquina: no hay barra que esquivar en los muslos, así que puedes estar erguido y usar todo el recorrido sin acortar la parte alta.'], '/exercises/plate-loaded-shrug-main.webp', '/exercises/plate-loaded-shrug-main.webp'),
  ('Agarre de Discos', 'plate-pinch', 'forearms', ARRAY['traps'], 'barbell', 'intermediate', 'isolation', 'Un ejercicio clásico para el agarre: pellizca dos discos con la cara lisa hacia afuera y mantenlos durante un tiempo determinado, cargando los flexores del pulgar y los dedos en trabajo isométrico sostenido.', ARRAY['Coloca dos discos en el suelo uno al lado del otro con las caras lisas hacia afuera.','Baja en sentadilla, agarra ambos discos juntos entre los dedos y el pulgar de una mano — sin agarraderas, solo pellizca.','Levántate y sostén los discos al costado durante el tiempo deseado, manteniendo el brazo recto.','Devuélvelos al suelo con control.','Repite con la otra mano.'], ARRAY['Empieza con dos discos de 5 kg / 10 lb y ve aumentando.','La magnesia en las manos marca una gran diferencia; con las manos sudadas el agarre falla rápido.'], '/exercises/plate-pinch-main.webp', '/exercises/plate-pinch-main.webp'),
  ('Pullover con Disco', 'plate-pullover', 'back', ARRAY['core','triceps'], 'barbell', 'beginner', 'compound', 'Un pullover sosteniendo un disco, que trabaja dorsales, pecho y serrato.', ARRAY['Acuéstate plano en un banco sujetando un disco con ambas manos.','Empuja el disco sobre el pecho con los brazos casi rectos.','Baja el disco en arco por detrás de la cabeza hasta sentir el estiramiento.','Tira del disco de regreso sobre el pecho por el mismo arco.','Repite el número de repeticiones indicado.'], ARRAY['Mantén los codos suaves pero con el mismo ángulo.','Detente al final de tu rango limpio — sin estiramiento excesivo del hombro.','Apoya bien los pies para mantener la estabilidad.'], '/exercises/plate-pullover-main.webp', '/exercises/plate-pullover-main.webp'),
  ('Postura del Arado', 'plow-pose', 'back', ARRAY['glutes','traps'], NULL, 'intermediate', 'mobility', 'Una inversión en la que las piernas pasan por encima de la cabeza hasta que los dedos de los pies llegan al suelo por detrás, alargando toda la parte posterior del cuerpo.', ARRAY['Túmbate boca arriba con los brazos junto al cuerpo y las palmas hacia abajo.','Eleva ambas piernas por encima de la cabeza y sostén la zona lumbar con las manos.','Baja los dedos de los pies hacia el suelo por detrás de la cabeza, con las piernas tan estiradas como resulte cómodo.','Mantén la posición durante el tiempo indicado, respirando con calma y sin mover la cabeza.','Desciende vértebra a vértebra con las manos sosteniendo la espalda.'], ARRAY['Nunca gires la cabeza dentro de la postura; el cuello está cargado y debe quedar neutro.','Apoya los dedos de los pies en una silla o unos cojines si el suelo queda lejos.','Evita esta postura por completo si tienes molestias cervicales.'], '/exercises/plow-pose-main.webp', '/exercises/plow-pose-main.webp'),
  ('Zancada Pliométrica', 'plyo-lunge', 'glutes', ARRAY['hamstrings'], NULL, 'intermediate', 'compound', 'Un salto explosivo en posición de zancada que cambia las piernas en el aire, alternando cada repetición.', ARRAY['Comienza en una zancada con un pie adelantado.','Baja a una zancada profunda con la rodilla trasera casi tocando el suelo.','Despega ambos pies y cambia las piernas en el aire.','Aterriza suave en zancada con la pierna opuesta adelante.','Continúa alternando sin pausa.'], ARRAY['Aterriza suave con las rodillas flexionadas.','Cambia la posición de las piernas por completo — no solo saltes en el sitio.','Mantén el torso erguido — no te inclines adelante.'], '/exercises/plyo-lunge-main.webp', '/exercises/plyo-lunge-main.webp'),
  ('Flexión Pliométrica', 'plyo-push-up', 'chest', ARRAY['shoulders'], NULL, 'intermediate', 'compound', 'Una flexión explosiva en la que las manos despegan del suelo al subir, entrena potencia del tren superior.', ARRAY['Colócate en posición de flexión estándar, manos a la anchura de los hombros.','Baja con control hasta que el pecho casi toque el suelo.','Empuja explosivamente para que las manos despeguen del suelo.','Aterriza suave con los codos ligeramente flexionados.','Repite sin pausa el número de repeticiones indicado.'], ARRAY['Mantén el cuerpo en línea recta — sin doblar ni hundir.','Aterriza suave con los codos flexionados.','Apoya las rodillas si no puedes despegar limpiamente.'], '/exercises/plyo-push-up-main.webp', '/exercises/plyo-push-up-main.webp'),
('Curl en Banco Scott', 'preacher-curl', 'biceps', NULL, 'barbell', 'beginner', 'isolation', 'Una variación del curl que usa un banco Scott para aislar el bíceps.', ARRAY['Siéntate en el banco Scott con los brazos apoyados en el pad.','Sostén una barra Z con agarre supinado.','Sube la barra hacia los hombros.','Baja con control hasta que los brazos queden casi extendidos.','Repite.'], ARRAY['Evita los rebotes en la parte baja del recorrido.','Mantén las muñecas neutras sobre la barra EZ.','Sube la barra sin impulso de hombros ni espalda.'], '/exercises/preacher-curl-main.webp', '/exercises/preacher-curl-main.webp'),
  ('Curl Martillo en Banco Scott', 'preacher-hammer-curl', 'biceps', NULL, 'dumbbell', 'intermediate', 'isolation', 'Un curl de bíceps en banco Scott con agarre neutro tipo martillo que enfatiza el braquial y los antebrazos.', ARRAY['Siéntate en un banco Scott con una mancuerna en cada mano.','Apoya los brazos superiores en la almohadilla con las palmas enfrentadas.','Flexiona las mancuernas hacia arriba manteniendo las muñecas neutras.','Contrae el bíceps en la parte alta del movimiento.','Baja las mancuernas con control.','Repite el número de repeticiones deseado.'], ARRAY['Mantén los brazos superiores apoyados en la almohadilla.','Evita bloquear completamente los codos en la parte baja.','Controla la bajada en lugar de dejar caer el peso.'], '/exercises/preacher-hammer-curl-main.webp', '/exercises/preacher-hammer-curl-main.webp'),
  ('Push-Ups de Pseudo Plancha', 'pseudo-planche-push-ups', 'shoulders', ARRAY['core','triceps'], NULL, 'advanced', 'compound', 'Una flexión con las manos giradas hacia atrás y los hombros inclinados muy por delante de las muñecas, imitando la carga de la plancha.', ARRAY['Comienza en posición de push-up con las manos giradas de modo que los dedos apunten hacia atrás.','Inclina los hombros hacia adelante por delante de las muñecas.','Baja el pecho hacia el suelo flexionando los codos.','Mantén el cuerpo en línea recta.','Empuja hacia arriba manteniendo la inclinación hacia adelante.','Repite el número deseado de repeticiones.'], ARRAY['Cuanto más te inclines hacia delante, más difícil será cada repetición.','Mantén los codos pegados al cuerpo al bajar.','Mantén las escápulas protraídas y el cuerpo rígido.'], '/exercises/pseudo-planche-push-ups-main.webp', '/exercises/pseudo-planche-push-ups-main.webp'),
  ('Postura del Cachorro', 'puppy-pose', 'back', ARRAY['traps'], NULL, 'beginner', 'mobility', 'Una postura de rodillas a medio camino entre la postura del niño y el perro boca abajo: las caderas quedan sobre las rodillas mientras el pecho se acerca al suelo, abriendo hombros y espalda alta.', ARRAY['Colócate a cuatro apoyos con las caderas sobre las rodillas y las manos bajo los hombros.','Camina las manos hacia delante y baja el pecho hacia el suelo manteniendo las caderas altas.','Apoya la frente o la barbilla en la esterilla y deja que las axilas se ablanden hacia abajo.','Mantén la posición durante el tiempo indicado, respirando hacia la espalda alta.','Camina las manos de vuelta y siéntate sobre los talones para salir.'], ARRAY['Mantén las caderas sobre las rodillas; sentarte atrás convierte esto en la postura del niño.','Presiona las palmas hacia abajo y despega los codos del suelo para que los brazos sigan activos.','Apoya la frente en un bloque si el pecho no baja con comodidad.'], '/exercises/puppy-pose-main.webp', '/exercises/puppy-pose-main.webp'),
  ('Jerk de Empuje', 'push-jerk', 'shoulders', ARRAY['glutes','quads','traps'], 'barbell', 'intermediate', 'compound', 'Un levantamiento por encima de la cabeza que usa una flexión y un impulso de piernas para lanzar la barra arriba, recibida en un cuarto de sentadilla.', ARRAY['Sostén la barra en posición de rack frontal sobre los hombros.','Párate con los pies a la anchura de las caderas.','Flexiona ligeramente las rodillas.','Impulsa explosivamente con las piernas y empuja la barra sobre la cabeza.','Baja a una sentadilla de un cuarto debajo de la barra y bloquea los brazos.','Levántate completamente y baja la barra para repetir.'], ARRAY['Mantén el torso erguido durante la flexión.','Impulsa con las piernas antes de empujar con los brazos.','Bloquea los brazos mientras bajas debajo de la barra.'], '/exercises/push-jerk-main.webp', '/exercises/push-jerk-main.webp'),
  ('Press de Empuje', 'push-press', 'shoulders', ARRAY['quads','triceps'], 'barbell', 'intermediate', 'compound', 'Un press de barra sobre la cabeza que usa el impulso de las piernas para empujar cargas más pesadas.', ARRAY['Párate con la barra apoyada en los deltoides frontales.','Flexiona ligeramente las rodillas.','Impulsa con las piernas y empuja la barra sobre la cabeza.','Bloquea completamente.','Baja al inicio.','Repite.'], ARRAY['Usa el impulso de las piernas solo para iniciar — termina con los hombros.','Mantén el core apretado en todo momento.'], '/exercises/push-press-main.webp', '/exercises/push-press-main.webp'),
  ('Push-Up', 'push-up', 'chest', ARRAY['shoulders'], NULL, 'beginner', 'compound', 'Un ejercicio fundamental con el peso corporal para el pecho, los hombros y los tríceps.', ARRAY['Comienza en posición de plancha alta con las manos a la anchura de los hombros.','Baja el cuerpo hasta que el pecho casi toque el suelo.','Empuja hacia arriba hasta la posición inicial.','Mantén el cuerpo en línea recta en todo momento.','Repite.'], ARRAY['Aprieta el abdomen y los glúteos para evitar que la cadera caiga.','No abras los codos en exceso; mantenlos cerca del torso.','Mantén el cuello neutro mirando al suelo.'], '/exercises/push-up-main.webp', '/exercises/push-up-main.webp'),
  ('Postura de la Pirámide', 'pyramid-pose', 'hamstrings', ARRAY['back','calves'], NULL, 'intermediate', 'mobility', 'Una flexión de pie sobre la pierna delantera estirada en un paso corto, que aísla el isquiotibial de esa pierna mientras ambas caderas quedan cuadradas.', ARRAY['Lleva un pie atrás cerca del largo de una pierna y gíralo ligeramente hacia fuera.','Cuadra ambas caderas hacia el frente de la esterilla y mantén las dos piernas estiradas.','Bascula desde las caderas y flexiona sobre la pierna delantera, llevando las manos al suelo, a bloques o a la espinilla.','Mantén la flexión durante el tiempo indicado, con la columna larga en lugar de redondeada.','Empuja con los pies para subir y repite del otro lado.'], ARRAY['Acorta el paso hasta que ambas caderas puedan mirar al frente; la longitud vale menos que las caderas cuadradas.','Usa bloques bajo las manos para que el pecho siga acercándose a la espinilla.','Deja una micro flexión en la rodilla delantera si el isquiotibial se agarrota.'], '/exercises/pyramid-pose-main.webp', '/exercises/pyramid-pose-main.webp'),
  ('Rack Pull', 'rack-pull', 'back', ARRAY['forearms'], 'barbell', 'intermediate', 'compound', 'Una variación de peso muerto en rango parcial desde pines a la altura de las rodillas, que enfatiza la parte superior de la espalda, el trapecio y la fuerza de bloqueo con cargas superiores al peso muerto completo.', ARRAY['Coloca los pines de seguridad en un rack a la altura de las rodillas y apoya una barra cargada sobre ellos.','Párate con los pies al ancho de caderas y agarra la barra justo fuera de las piernas.','Activa el core, retrae las escápulas y empuja con las piernas para levantar la barra.','Extiende completamente caderas y rodillas en la parte superior.','Baja la barra a los pines con control y reposiciónate antes de la siguiente repetición.'], ARRAY['Usa una bisagra de cadera — mantén la barra cerca del cuerpo en todo momento.','Los rack pulls permiten cargas superiores a tu máximo de peso muerto para sobrecargar el bloqueo.','Enfócate en la tensión de la parte superior de la espalda para evitar el redondeo con cargas pesadas.'], '/exercises/rack-pull-main.webp', '/exercises/rack-pull-main.webp'),
  ('Apertura de Deltoides Posterior', 'rear-delt-fly', 'shoulders', ARRAY['traps'], 'dumbbell', 'beginner', 'isolation', 'Un movimiento de aislamiento que trabaja los deltoides posteriores y la parte superior de la espalda.', ARRAY['Sostén las mancuernas e inclínate hacia adelante desde las caderas.','Con una ligera flexión en los codos, eleva las mancuernas hacia los lados.','Aprieta las escápulas en la parte superior.','Baja con control.','Repite.'], ARRAY['Elige un peso ligero para no usar impulso.','Mantén la espalda recta mientras estás inclinado hacia delante.','Lidera el movimiento con los codos, no con las manos.'], '/exercises/rear-delt-fly-main.webp', '/exercises/rear-delt-fly-main.webp'),
  ('Crunches Inversos', 'reverse-crunches', 'core', NULL, NULL, 'intermediate', 'isolation', 'Un ejercicio de core en el suelo que enrolla la cadera hacia el pecho para trabajar la parte baja del abdomen.', ARRAY['Túmbate boca arriba con los brazos a los lados.','Eleva las piernas con las rodillas flexionadas a 90 grados.','Despega las caderas del suelo contrayendo el abdomen inferior.','Lleva las rodillas hacia el pecho.','Baja las caderas con control.','Repite el número deseado de repeticiones.'], ARRAY['Despega la cadera con el abdomen, no con impulso de las piernas.','Exhala al subir para activar mejor el abdomen.','Presiona los brazos contra el suelo para mayor estabilidad.'], '/exercises/reverse-crunches-main.webp', '/exercises/reverse-crunches-main.webp'),
  ('Curl Inverso', 'reverse-curl', 'biceps', NULL, 'barbell', 'beginner', 'isolation', 'Un curl con barra en agarre prono que trabaja el braquial y los extensores del antebrazo.', ARRAY['Párate y sostén la barra con agarre prono.','Sube la barra hacia los hombros.','Baja con control.','Repite.'], ARRAY['Mantén las muñecas rectas.','Realiza el movimiento en un rango completo de movimiento.'], '/exercises/reverse-curl-main.webp', '/exercises/reverse-curl-main.webp'),
  ('Remo Inclinado con Agarre Invertido', 'reverse-grip-bent-over-row', 'back', ARRAY['biceps','traps'], 'barbell', 'intermediate', 'compound', 'Un remo con barra y agarre supino que trabaja dorsales y romboides, con participación de los bíceps.', ARRAY['Párate con los pies a la anchura de los hombros y agarra la barra con agarre supinado.','Inclínate hacia adelante desde las caderas con una ligera flexión de rodillas.','Deja que la barra cuelgue con los brazos extendidos.','Jala la barra hacia el abdomen inferior llevando los codos hacia atrás.','Aprieta la espalda en la parte superior.','Baja la barra con control.','Repite el número deseado de repeticiones.'], ARRAY['Mantén la espalda neutra y el core firme durante todo el recorrido.','No uses impulso con el torso; el cuerpo queda inclinado y estable.','Mantén las muñecas rectas para proteger los codos con este agarre.'], '/exercises/reverse-grip-bent-over-row-main.webp', '/exercises/reverse-grip-bent-over-row-main.webp'),
  ('Jalón al Pecho Agarre Supino', 'reverse-grip-lat-pulldown', 'biceps', ARRAY['shoulders','back'], 'cable', 'intermediate', 'compound', 'Una variante del jalón al pecho con agarre supino que aumenta la participación del bíceps.', ARRAY['Coloca una barra recta en una máquina de jalón al pecho.','Sujeta la barra con agarre supino, al ancho de los hombros.','Siéntate y asegura tus muslos bajo la almohadilla.','Tira de la barra hacia la parte superior del pecho.','Contrae el dorsal y el bíceps en la parte baja.','Vuelve la barra a la posición inicial con control.','Repite el número de repeticiones deseado.'], ARRAY['Mantén el pecho erguido y evita inclinarte demasiado hacia atrás.','Tira con los codos, no solo con las manos.','Contrae el dorsal en la parte baja del movimiento.'], '/exercises/reverse-grip-lat-pulldown-main.webp', '/exercises/reverse-grip-lat-pulldown-main.webp'),
  ('Zancada Inversa', 'reverse-lunge', 'glutes', ARRAY['hamstrings'], 'dumbbell', 'intermediate', 'compound', 'Una variación de la zancada que da un paso hacia atrás para mayor estabilidad de rodilla.', ARRAY['Párate sosteniendo mancuernas a los costados.','Da un paso hacia atrás con una pierna y baja la rodilla hacia el suelo.','Baja hasta que el muslo delantero quede paralelo al suelo.','Empuja con el talón delantero para volver a la posición de pie.','Repite en ambos lados.'], ARRAY['Da el paso atrás lo bastante largo para que la rodilla delantera no pase del pie.','Mantén el torso erguido y las mancuernas pegadas al cuerpo.','Completa el mismo número de repeticiones con cada pierna.'], '/exercises/reverse-lunge-main.webp', '/exercises/reverse-lunge-main.webp'),
  ('Nordic Curl Inverso', 'reverse-nordic-curl', 'quads', ARRAY['core'], NULL, 'intermediate', 'isolation', 'Un ejercicio de cuádriceps con el propio peso corporal, arrodillado, inclinando el torso hacia atrás con control mientras se mantiene la cadera extendida.', ARRAY['Arrodíllate sobre una almohadilla con los pies planos y el torso erguido.','Mantén la cadera extendida y el core activado.','Inclina el torso lentamente hacia atrás manteniendo el cuerpo en línea recta.','Baja tanto como puedas controlar con el cuádriceps.','Vuelve a subir a la posición inicial.','Repite el número de repeticiones deseado.'], ARRAY['Mantén la cadera extendida en todo momento, sin que se doble.','Baja solo hasta donde puedas controlar el movimiento.','Usa una almohadilla bajo las rodillas para mayor comodidad.'], '/exercises/reverse-nordic-curl-main.webp', '/exercises/reverse-nordic-curl-main.webp'),
  ('Plancha Inversa', 'reverse-plank', 'back', ARRAY['hamstrings','shoulders','triceps'], NULL, 'intermediate', 'compound', 'Una plancha invertida isométrica con el pecho hacia arriba, que fortalece los glúteos y los erectores de la columna.', ARRAY['Siéntate en el suelo con las piernas extendidas al frente.','Coloca las manos detrás de ti con los dedos apuntando hacia los pies.','Eleva las caderas del suelo para formar una línea recta de la cabeza a los talones.','Aprieta los glúteos y contrae el core.','Mantén la posición durante el tiempo deseado.','Baja las caderas con control para salir.'], ARRAY['Mantén la cadera alta; si baja, descansa y repite.','No dejes caer la cabeza hacia atrás; alarga el cuello.','Reparte el peso entre talones y manos, con los hombros lejos de las orejas.'], '/exercises/reverse-plank-main.webp', '/exercises/reverse-plank-main.webp'),
  ('Fondos en Plancha Invertida', 'reverse-plank-dips', 'triceps', ARRAY['back','glutes','shoulders'], NULL, 'intermediate', 'compound', 'Fondos de tríceps desde una plancha invertida con las piernas estiradas: las piernas permanecen largas y las caderas altas mientras los codos se flexionan y estiran.', ARRAY['Siéntate con las piernas estiradas y las manos en el suelo detrás de las caderas, con los dedos hacia delante.','Empuja con manos y talones y eleva las caderas a una plancha invertida con las piernas estiradas.','Flexiona los codos hacia atrás y baja un poco las caderas hacia el suelo.','Empuja de nuevo hasta bloquear los brazos, manteniendo las caderas altas.','Repite las veces indicadas.'], ARRAY['Mantén las caderas elevadas abajo; sentarte entre repeticiones quita la carga.','Lleva los codos rectos hacia atrás en lugar de abrirlos hacia fuera.','Flexiona las rodillas si la versión con piernas estiradas exige demasiado a los isquiotibiales.'], '/exercises/reverse-plank-dips-main.webp', '/exercises/reverse-plank-dips-main.webp'),
('Pulsos de Cadera en Mesa Invertida', 'reverse-tabletop-hip-pulses', 'glutes', ARRAY['back','hamstrings'], NULL, 'intermediate', 'compound', 'Pulsos de glúteo desde la mesa invertida: los brazos permanecen estirados y solo las caderas bajan y suben, de modo que el trabajo se queda en el glúteo y no en el tríceps.', ARRAY['Siéntate con las rodillas flexionadas, los pies apoyados y las manos en el suelo detrás de ti.','Empuja con manos y pies y eleva las caderas hasta que el tronco quede a la altura de las rodillas.','Con los codos estirados, baja las caderas unos centímetros.','Aprieta los glúteos para volver a subirlas al nivel.','Pulsa las veces indicadas y baja.'], ARRAY['Mantén los brazos bloqueados: flexionar los codos convierte esto en un fondo.','Impulsa desde los talones y los glúteos, no desde la zona lumbar.','Mantén el pecho abierto y los hombros lejos de las orejas.'], '/exercises/reverse-tabletop-hip-pulses-main.webp', '/exercises/reverse-tabletop-hip-pulses-main.webp'),
  ('Mesa Invertida Isométrica', 'reverse-tabletop-hold', 'back', ARRAY['hamstrings','shoulders','triceps'], NULL, 'beginner', 'compound', 'Una mesa invertida estática: rodillas flexionadas, manos bajo los hombros por detrás del cuerpo, caderas elevadas a la altura de las rodillas y sostenidas, de modo que los glúteos y toda la parte posterior del tronco trabajan de forma isométrica.', ARRAY['Siéntate con las rodillas flexionadas, los pies apoyados y las manos en el suelo detrás de ti, con los dedos hacia los talones.','Empuja con manos y pies y eleva las caderas hasta que el tronco quede a la altura de las rodillas.','Abre el pecho, aleja los hombros de las orejas y mira al frente.','Mantén la posición durante el tiempo indicado con las caderas altas.','Baja las caderas de forma controlada para terminar.'], ARRAY['Empuja el suelo en lugar de colgarte de los hombros.','Mantén las rodillas sobre los tobillos y apuntando al frente.','Deja que la cabeza siga la línea de la columna en lugar de dejarla caer hacia atrás.'], '/exercises/reverse-tabletop-hold-main.webp', '/exercises/reverse-tabletop-hold-main.webp'),
  ('Postura de la Silla Girada', 'revolved-chair-pose', 'core', ARRAY['back','glutes'], NULL, 'intermediate', 'compound', 'La postura de la silla con una torsión cerrada: las caderas se mantienen bajas y niveladas mientras el pecho rota y un codo se engancha por fuera del muslo contrario.', ARRAY['Colócate en la postura de la silla con las rodillas flexionadas, las caderas atrás y las palmas juntas frente al pecho.','Mantén las rodillas a la misma altura para que las caderas no se abran hacia la torsión.','Gira el pecho hacia un lado y engancha el codo contrario por fuera de ese muslo.','Presiona las palmas entre sí y mantén durante el tiempo indicado, alargando la columna en cada inhalación.','Vuelve al centro y repite del otro lado.'], ARRAY['Alinea las rodillas antes de girar; una rodilla que se adelanta finge la mayor parte de la rotación.','Gira desde la zona media de la espalda en lugar de hacer palanca con el brazo contra la pierna.','Mantén el peso en los talones para que la postura siga siendo una sentadilla y no una inclinación.'], '/exercises/revolved-chair-pose-main.webp', '/exercises/revolved-chair-pose-main.webp'),
  ('Zancada Alta Girada', 'revolved-crescent-lunge', 'core', ARRAY['back'], NULL, 'intermediate', 'compound', 'Una zancada alta con torsión cerrada: el talón trasero sigue elevado, las caderas miran al frente y el pecho rota sobre el muslo delantero.', ARRAY['Colócate en zancada alta con la rodilla delantera sobre el tobillo y el talón trasero elevado.','Junta las palmas frente al pecho y cuadra ambas caderas hacia el frente de la esterilla.','Gira el pecho hacia la pierna delantera y engancha el codo contrario por fuera del muslo.','Mantén la torsión durante el tiempo indicado, empujando el talón trasero hacia la pared de detrás.','Deshaz la torsión y repite del otro lado.'], ARRAY['Mantén la pierna trasera estirada y larga; es lo que impide que la torsión se hunda en las caderas.','Baja la rodilla trasera al suelo para una versión más sencilla con la misma rotación.','Alarga primero la columna y gira después: torcer una espalda redondeada no lleva a ningún sitio.'], '/exercises/revolved-crescent-lunge-main.webp', '/exercises/revolved-crescent-lunge-main.webp'),
  ('Cuelgue Estático en Anillas', 'ring-dead-hang', 'forearms', ARRAY['back','core','traps'], 'bodyweight', 'intermediate', 'compound', 'Un cuelgue pasivo en anillas de gimnasia. El agarre de rotación libre recluta más estabilizadores en las manos, los antebrazos y la cintura escapular que una barra fija.', ARRAY['Agarra un par de anillas de gimnasia con agarre neutro, palmas enfrentadas entre sí.','Cuélgate con los brazos completamente extendidos y los pies fuera del suelo.','Deja que las anillas giren naturalmente; no luches contra el agarre.','Mantén los hombros activos (sin encogerlos hacia las orejas) y el core ligeramente apretado.','Mantén la posición durante el tiempo deseado.'], ARRAY['Empieza con series cortas y aumenta el tiempo de forma progresiva.','Agarra fuerte con toda la mano, no solo con los dedos.','Baja apoyando los pies con control, no te sueltes de golpe.'], '/exercises/ring-dead-hang-main.webp', '/exercises/ring-dead-hang-main.webp'),
  ('Fondos en Anillas', 'ring-dips', 'chest', ARRAY['shoulders'], 'bodyweight', 'advanced', 'compound', 'Un fondo con el peso corporal desafiante realizado en anillas de gimnasia, que exige mayor estabilización que los fondos en barra.', ARRAY['Apóyate en las anillas con los brazos bloqueados.','Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.','Empuja hacia arriba hasta la posición inicial.','Repite.'], ARRAY['Mantén las anillas cerca del cuerpo.','Gira las anillas hacia afuera en la parte superior para mayor activación del pecho.'], '/exercises/ring-dips-main.webp', '/exercises/ring-dips-main.webp'),
  ('Face Pull en Anillas', 'ring-face-pull', 'shoulders', ARRAY['traps'], 'bodyweight', 'intermediate', 'compound', 'Un face pull en anillas de gimnasia para resistencia ajustable y mejora de la salud del hombro.', ARRAY['Agarra las anillas e inclínate hacia atrás de modo que el cuerpo quede en ángulo.','Jala las anillas hacia la cara, abriendo los codos hacia los lados.','Mantén brevemente y luego regresa.','Repite.'], ARRAY['Ajusta el ángulo del cuerpo para controlar la dificultad.','Rota los brazos externamente en la parte superior.'], '/exercises/ring-face-pull-main.webp', '/exercises/ring-face-pull-main.webp'),
  ('Muscle-Up en Anillas', 'ring-muscle-up', 'back', ARRAY['shoulders','biceps'], 'bodyweight', 'advanced', 'compound', 'Un movimiento avanzado de calistenia que combina dominada y fondo en anillas de gimnasia.', ARRAY['Cuelga de las anillas con agarre falso, palmas enfrentadas.','Tira explosivamente, llevando el pecho hacia las anillas.','Pasa los codos por encima de las anillas mientras sube el pecho.','Empuja arriba hasta extender los brazos.','Baja con control pasando por la transición hasta volver al colgado.'], ARRAY['El agarre falso es clave para la transición.','Empuja los codos hacia abajo con fuerza durante la transición.','Construye la fuerza primero con negativas y asistido con banda.'], '/exercises/ring-muscle-up-main.webp', '/exercises/ring-muscle-up-main.webp'),
  ('Flexión en Anillas', 'ring-push-up', 'chest', ARRAY['shoulders','core'], 'bodyweight', 'intermediate', 'compound', 'Una flexión sobre anillas de gimnasia, que exige más a los estabilizadores del pecho, hombros y core.', ARRAY['Coloca las anillas justo por encima del suelo.','Sujeta las anillas y adopta posición de plank con los brazos rectos.','Baja el pecho hacia las anillas, codos pegados al cuerpo.','Empuja arriba hasta extender los brazos.','Repite el número de repeticiones indicado.'], ARRAY['Gira las anillas hacia afuera arriba para activar más el pecho.','Activa el core — las anillas amplifican cualquier oscilación.','Apoya las rodillas para escalar la dificultad.'], '/exercises/ring-push-up-main.webp', '/exercises/ring-push-up-main.webp'),
  ('Remo en Anillas', 'ring-row', 'back', ARRAY['biceps','shoulders','traps'], 'bodyweight', 'beginner', 'compound', 'Un remo con peso corporal en anillas de gimnasia, realizado en ángulo para trabajar espalda y bíceps.', ARRAY['Coloca las anillas a la altura de la cadera o el pecho.','Sujeta las anillas con las palmas enfrentadas, inclínate atrás con los brazos rectos.','Activa el core y tira del pecho hacia las anillas.','Junta los omóplatos arriba.','Baja con control hasta extender los brazos.'], ARRAY['Cuanto más bajo el ángulo del cuerpo, más difícil el remo.','Mantén el cuerpo recto — no dejes caer las caderas.','Tira con los codos atrás, no abiertos, para más implicación dorsal.'], '/exercises/ring-row-main.webp', '/exercises/ring-row-main.webp'),
  ('Remo Invertido en Anillas', 'rings-inverted-row', 'back', ARRAY['biceps','forearms','shoulders','core'], 'bodyweight', 'intermediate', 'compound', 'Un remo horizontal con peso corporal en anillas cerca del suelo, más difícil que el remo de pie en anillas.', ARRAY['Coloca las anillas justo por encima de la cadera.','Acuéstate bajo las anillas y agárralas con las palmas enfrentadas.','Camina con los pies adelante hasta que el cuerpo forme una línea recta.','Tira del pecho hacia las anillas, juntando los omóplatos.','Baja con control hasta extender los brazos.'], ARRAY['Mantén el cuerpo en línea recta — de los talones a la cabeza.','Activa glúteos y core para no hundirte.','Eleva los pies en un cajón para una versión más difícil.'], '/exercises/rings-inverted-row-main.webp', '/exercises/rings-inverted-row-main.webp'),
  ('Peso Muerto Rumano', 'romanian-deadlift', 'glutes', ARRAY['back'], 'barbell', 'intermediate', 'compound', 'Un movimiento de bisagra de cadera que enfatiza los isquiotibiales y los glúteos.', ARRAY['Párate sosteniendo la barra a la altura de las caderas con agarre prono.','Bisagra en las caderas empujándolas hacia atrás mientras mantienes las piernas casi rectas.','Baja la barra a lo largo de las piernas hasta sentir el estiramiento de los isquiotibiales.','Empuja las caderas hacia adelante para volver a la posición de pie.','Repite.'], ARRAY['No redondees la espalda baja; mantén la columna neutra.','Baja solo hasta donde llegues sin perder la postura.','Aprieta los dorsales para mantener la barra cerca del cuerpo.'], '/exercises/romanian-deadlift-main.webp', '/exercises/romanian-deadlift-main.webp'),
  ('Trepa de Cuerda', 'rope-climb', 'back', ARRAY['biceps','forearms','core'], 'bodyweight', 'advanced', 'compound', 'Un ejercicio de jalón para todo el cuerpo que trepa una cuerda vertical mano a mano, cargando el dorsal ancho, el bíceps, el agarre y el core de forma isométrica.', ARRAY['Agarra la cuerda lo más arriba posible con ambas manos.','Envuelve la cuerda alrededor de un pie (gancho en S o en J) o apriétala entre ambos pies.','Súbete mientras los pies aprietan para soportar el peso corporal y sueltan la cuerda.','Alcanza más arriba con una mano, luego con la otra, y vuelve a sujetar con los pies.','Repite hasta llegar a la cima de la cuerda.','Baja mano bajo mano con los pies controlando la velocidad — nunca te deslices.'], ARRAY['Aprende el bloqueo de pies antes de intentar trepar más alto; duplica tu capacidad de trabajo.','Nunca te dejes caer desde la cima; el descenso controlado es parte del ejercicio.'], '/exercises/rope-climb-main.webp', '/exercises/rope-climb-main.webp'),
  ('Máquina de Remo', 'rowing-machine', 'back', ARRAY['biceps','glutes','hamstrings','traps'], 'machine', 'beginner', 'cardio', 'Un ejercicio cardiovascular de cuerpo completo en la máquina de remo: cada palada empuja con las piernas, lleva el torso hacia atrás y tira de la manija hasta las costillas, trabajando piernas, espalda y brazos en un ciclo continuo.', ARRAY['Siéntate en la máquina de remo, sujeta los pies con las correas de las plataformas y agarra la manija en pronación.','Deslízate hacia delante hasta la posición de ataque: tibias verticales, torso ligeramente por delante de la cadera y brazos estirados hacia el volante.','Empuja primero con las piernas y desplaza el asiento hacia atrás hasta dejar las rodillas casi estiradas.','Lleva el torso hacia atrás pasando de la vertical y tira entonces de la manija hasta las costillas bajas, con los codos pasando junto a los costados.','Invierte el orden en la recuperación — primero los brazos hacia delante, después el torso y por último flexionar las rodillas — y vuelve a deslizarte hasta la posición de ataque para la siguiente palada.','Continúa durante el tiempo, la distancia o el número de paladas que quieras.'], ARRAY['Respeta el orden: piernas, torso y brazos en el tirón, y brazos, torso y piernas en la recuperación. Flexionar los brazos antes de tiempo desaprovecha la parte más fuerte de la palada.','Rema con la espalda plana y el core activado: redondear la zona lumbar en la posición de ataque es lo que convierte el remo en dolor de espalda en lugar de trabajo cardiovascular.','Lleva la manija en línea recta y horizontal hasta las costillas bajas, y haz la recuperación unas dos veces más lenta que el tirón en lugar de volver de golpe.'], '/exercises/rowing-machine-main.webp', '/exercises/rowing-machine-main.webp'),
  ('Giro Ruso', 'russian-twist', 'core', NULL, NULL, 'beginner', 'isolation', 'Un ejercicio de core rotacional que trabaja los oblicuos.', ARRAY['Siéntate en el suelo con las rodillas flexionadas e inclínate ligeramente hacia atrás.','Junta las manos o sostén un peso a la altura del pecho.','Rota el torso hacia un lado, luego hacia el otro.','Mantén el core apretado en todo momento.','Repite.'], ARRAY['Gira desde el torso, no solo con los brazos.','Mantén la espalda recta aunque estés ligeramente reclinado.','Hazlo lento y controlado; la velocidad resta trabajo a los oblicuos.'], '/exercises/russian-twist-main.webp', '/exercises/russian-twist-main.webp'),
  ('Postura del Cadáver', 'savasana', 'back', NULL, NULL, 'beginner', 'mobility', 'El descanso final de una práctica: tumbado boca arriba con el cuerpo completamente pasivo, dejando que los efectos de la sesión se asienten.', ARRAY['Túmbate boca arriba con las piernas cómodamente separadas y los pies cayendo hacia fuera.','Deja los brazos algo separados del cuerpo con las palmas hacia arriba.','Permite que todo el cuerpo se ablande contra el suelo, incluidos la mandíbula, los ojos y las manos.','Permanece durante el tiempo indicado, respirando con naturalidad y sin controlar la respiración.','Flexiona las rodillas y rueda hacia un lado antes de incorporarte despacio.'], ARRAY['Coloca un bolster bajo las rodillas si la zona lumbar no termina de asentarse.','Cúbrete con una manta; el cuerpo se enfría rápido en cuanto deja de moverse.','Esta postura no debe costar ningún esfuerzo: resiste el impulso de reajustarte constantemente.'], '/exercises/savasana-main.webp', '/exercises/savasana-main.webp'),
  ('Dominadas Escapulares', 'scapular-pull-ups', 'back', ARRAY['forearms'], 'bodyweight', 'intermediate', 'compound', 'Un ejercicio en barra de dominadas con brazos extendidos, que entrena la depresión y retracción de las escápulas.', ARRAY['Cuélgate de una barra de dominadas con los brazos completamente extendidos.','Mantén los brazos rectos durante todo el movimiento.','Deprime y retrae las escápulas para elevar el pecho.','Haz una breve pausa en la parte superior del movimiento.','Regresa a la posición de cuelgue completo.','Repite el número deseado de repeticiones.'], ARRAY['Piensa en alejar los hombros de las orejas al subir el pecho.','No intentes convertirlo en una dominada; el recorrido es corto.','Controla la vuelta a la posición colgada sin desplomarte.'], '/exercises/scapular-pull-ups-main.webp', '/exercises/scapular-pull-ups-main.webp'),
  ('Tijeras', 'scissor-kicks', 'core', NULL, NULL, 'intermediate', 'compound', 'Un ejercicio de core realizado boca arriba, cruzando alternadamente las piernas rectas para trabajar el abdomen bajo y los flexores de cadera.', ARRAY['Recuéstate boca arriba con las manos bajo los glúteos.','Eleva ambas piernas unos centímetros del suelo.','Cruza alternadamente una pierna sobre la otra en un movimiento de tijera.','Mantén la zona lumbar presionada contra el suelo.','Mantén un ritmo constante durante todo el ejercicio.','Repite el número de repeticiones deseado.'], ARRAY['Presiona la zona lumbar contra el suelo en todo momento.','Mantén las piernas rectas y cerca del suelo.','Muévete con control, no con velocidad.'], '/exercises/scissor-kicks-main.webp', '/exercises/scissor-kicks-main.webp')
) as v(name, slug, muscle_slug, secondary_slugs, equipment_slug, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url)
on conflict (slug) do nothing;

insert into public.exercises (name, slug, primary_muscle_group_id, secondary_muscle_group_ids, equipment_id, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url, image_source, image_license)
select v.name, v.slug,
  (select id from public.muscle_groups where slug = v.muscle_slug),
  coalesce((select array_agg(id) from public.muscle_groups where slug = any(v.secondary_slugs)), '{}'),
  (select id from public.equipment where slug = v.equipment_slug),
  v.difficulty::public.exercise_difficulty,
  v.movement_type::public.movement_type,
  v.description, v.instructions, v.tips, v.image_url, v.thumbnail_url,
  'RepDB (repdb.co)', 'Free tier - commercial in-app use with attribution'
from (values
('Press de Barra sobre la Cabeza Sentado', 'seated-barbell-overhead-press', 'shoulders', ARRAY['traps','triceps'], 'barbell', 'intermediate', 'compound', 'Un press de barra sobre la cabeza estricto en posición sentada, que elimina el impulso de caderas y aísla los deltoides y los tríceps.', ARRAY['Ajusta un banco vertical dentro del rack con los pines a la altura aproximada de los hombros cuando estés sentado.','Siéntate con la espalda plana contra el pad y desrackea la barra en la parte frontal de los hombros.','Empuja la barra sobre la cabeza hasta extender completamente los brazos, pasando la cabeza por delante en la parte superior.','Baja la barra de vuelta a las clavículas con control.','Repite el número de repeticiones recomendado.'], ARRAY['Mantén las costillas abajo y los glúteos apretados; no te inclines hacia atrás como en un press de banca.','Empuja la barra recto hacia arriba, no hacia adelante.'], '/exercises/seated-barbell-overhead-press-main.webp', '/exercises/seated-barbell-overhead-press-main.webp'),
  ('Elevación de Talones Sentado', 'seated-calf-raise', 'calves', NULL, 'machine', 'beginner', 'isolation', 'Una elevación de talones en máquina realizada sentado para trabajar específicamente el músculo sóleo.', ARRAY['Siéntate en la máquina de elevación de talones con los pads apoyados en los muslos.','Baja los talones lo más posible.','Elévate sobre las puntas de los pies.','Baja con control.','Repite.'], ARRAY['La posición sentada pre-estira el sóleo.','Utiliza un rango completo de movimiento.'], '/exercises/seated-calf-raise-main.webp', '/exercises/seated-calf-raise-main.webp'),
  ('Press de Hombro con Mancuernas Sentado', 'seated-db-press', 'shoulders', ARRAY['traps','triceps'], 'dumbbell', 'intermediate', 'compound', 'Un movimiento de press sentado para los hombros usando mancuernas.', ARRAY['Siéntate en un banco con respaldo sosteniendo mancuernas a la altura de los hombros.','Empuja las mancuernas sobre la cabeza hasta extender completamente los brazos.','Baja las mancuernas de vuelta a la altura de los hombros.','Repite.'], ARRAY['No arquees la espalda baja; mantén el contacto con el respaldo.','Sube las mancuernas en línea recta, sin chocarlas arriba.','Exhala al empujar y mantén el core firme.'], '/exercises/seated-db-press-main.webp', '/exercises/seated-db-press-main.webp'),
  ('Curl con Mancuernas Sentado', 'seated-dumbbell-curl', 'biceps', NULL, 'dumbbell', 'beginner', 'isolation', 'Un curl de bíceps sentado con mancuernas, donde la posición sentada y erguida elimina el impulso para una técnica más estricta.', ARRAY['Siéntate en un banco con una mancuerna en cada mano.','Deja los brazos colgando a los lados con las palmas hacia adelante.','Sube ambas mancuernas hacia los hombros flexionando los bíceps.','Aprieta en la parte superior del movimiento.','Baja las mancuernas con control.','Repite el número deseado de repeticiones.'], ARRAY['Mantén los codos pegados a los costados en todo momento.','Evita inclinarte hacia atrás para ayudar a levantar el peso.','Estira los brazos por completo al final de cada repetición.'], '/exercises/seated-dumbbell-curl-main.webp', '/exercises/seated-dumbbell-curl-main.webp'),
  ('Elevación Lateral con Mancuerna Sentado', 'seated-dumbbell-lateral-raise', 'shoulders', ARRAY['traps'], 'dumbbell', 'beginner', 'isolation', 'Un ejercicio de aislamiento sentado que levanta las mancuernas hacia los lados, trabajando los deltoides laterales sin impulso de piernas.', ARRAY['Siéntate en un banco con una mancuerna en cada mano a los lados.','Mantén la espalda erguida y el core contraído.','Eleva ambas mancuernas hacia los lados hasta la altura de los hombros.','Mantén una ligera flexión en los codos.','Baja las mancuernas con control.','Repite el número de repeticiones deseado.'], ARRAY['Usa un peso ligero para mantener la elevación estricta.','Lidera con los codos en lugar de con las manos.','Eleva hasta la altura de los hombros y baja con control.'], '/exercises/seated-dumbbell-lateral-raise-main.webp', '/exercises/seated-dumbbell-lateral-raise-main.webp'),
  ('Extensión de Tríceps con Mancuerna Sentado', 'seated-dumbbell-tricep-extension', 'triceps', ARRAY['shoulders'], 'dumbbell', 'beginner', 'isolation', 'Una extensión por encima de la cabeza sentado que baja la mancuerna detrás de la cabeza, estirando y trabajando los tríceps.', ARRAY['Siéntate en un banco con una mancuerna sostenida sobre la cabeza con ambas manos.','Mantén los brazos superiores verticales junto a las orejas.','Baja la mancuerna detrás de la cabeza flexionando los codos.','Extiende los brazos para empujar la mancuerna de vuelta arriba.','Aprieta los tríceps en la parte superior.','Repite el número de repeticiones deseado.'], ARRAY['Mantén los brazos verticales junto a las orejas.','Mueve solo los antebrazos, manteniendo los codos quietos.','Contrae el core para evitar arquear la zona lumbar.'], '/exercises/seated-dumbbell-tricep-extension-main.webp', '/exercises/seated-dumbbell-tricep-extension-main.webp'),
  ('Flexión Sentado hacia Adelante', 'seated-forward-fold', 'hamstrings', ARRAY['back'], NULL, 'beginner', 'mobility', 'Un estiramiento sentado para los isquiotibiales y la zona lumbar, inclinando el torso sobre las piernas estiradas.', ARRAY['Siéntate en el suelo con ambas piernas estiradas al frente.','Mantén la espalda larga e inclínate desde las caderas.','Lleva las manos hacia los pies.','Mantén de 20 a 30 segundos, respirando de forma constante.'], ARRAY['Inicia con el pecho, no con la cabeza, para mantener la espalda larga.','Estira hasta una tensión leve, nunca hasta el dolor.'], '/exercises/seated-forward-fold-main.webp', '/exercises/seated-forward-fold-main.webp'),
  ('Curl de Piernas Sentado', 'seated-leg-curl', 'hamstrings', ARRAY['calves'], 'machine', 'beginner', 'isolation', 'Un ejercicio de aislamiento de isquiotibiales en máquina en posición sentada, con tensión constante y menor implicación de los flexores de cadera respecto a la variante tumbada.', ARRAY['Ajusta el respaldo y el cojín de tobillo para que las rodillas queden alineadas con el pivote de la máquina.','Siéntate erguido, coloca la parte posterior de los tobillos sobre el cojín y sujeta las asas.','Flexiona las piernas hacia abajo y atrás bajo el asiento hasta donde la máquina lo permita.','Pausa en la contracción máxima, luego vuelve lentamente a la posición inicial.','Repite el número de repeticiones deseado.'], ARRAY['Mantén la espalda firmemente apoyada en el respaldo durante todo el movimiento.','Flexiona ligeramente los pies hacia las espinillas en la contracción máxima para mayor activación de los isquios.','Controla la fase excéntrica — no dejes que el peso jale las piernas de vuelta rápidamente.'], '/exercises/seated-leg-curl-main.webp', '/exercises/seated-leg-curl-main.webp'),
  ('Press de Hombros en Máquina Smith Sentado', 'seated-smith-machine-shoulder-press', 'shoulders', ARRAY['traps','triceps'], 'smith_machine', 'beginner', 'compound', 'Un press de hombros sentado en máquina Smith, cuyo recorrido guiado facilita el aprendizaje del empuje vertical.', ARRAY['Coloca un banco dentro de la máquina Smith.','Siéntate mirando hacia adelante con la barra a la altura de los hombros.','Agarra la barra ligeramente más ancho que el ancho de hombros.','Desbloquea la barra y empuja hacia arriba hasta extender los brazos.','Baja la barra de vuelta a la altura de los hombros con control.','Repite el número de repeticiones deseado.'], ARRAY['Coloca el banco de modo que la barra baje justo delante de la cara.','No bloquees los codos con brusquedad en la parte alta.','Mantén el torso erguido y el core activo durante toda la serie.'], '/exercises/seated-smith-machine-shoulder-press-main.webp', '/exercises/seated-smith-machine-shoulder-press-main.webp'),
  ('Giro Espinal Sentado', 'seated-spinal-twist', 'back', ARRAY['glutes'], NULL, 'beginner', 'mobility', 'Una rotación sentada que estira los oblicuos, la espalda media y los glúteos girando hacia una rodilla flexionada.', ARRAY['Siéntate con una pierna estirada y cruza el otro pie por encima.','Apoya el codo opuesto contra la parte externa de la rodilla flexionada.','Gira el torso hacia la rodilla flexionada y mira sobre el hombro.','Mantén de 20 a 30 segundos, respirando de forma constante.','Cambia de lado y repite.'], ARRAY['Siéntate erguido y alarga la columna antes de girar.','Gira desde la espalda media, no desde la lumbar.'], '/exercises/seated-spinal-twist-main.webp', '/exercises/seated-spinal-twist-main.webp'),
  ('Estiramiento en Apertura Sentado', 'seated-straddle-stretch', 'adductors', ARRAY['back'], NULL, 'beginner', 'mobility', 'Un estiramiento sentado con piernas abiertas para aductores e isquiotibiales, inclinando el torso entre las piernas.', ARRAY['Siéntate con las piernas estiradas y bien abiertas en V.','Mantén la espalda larga e inclínate desde las caderas.','Camina las manos hacia adelante por el suelo.','Mantén de 20 a 30 segundos, respirando de forma constante.'], ARRAY['Mantén los dedos de los pies hacia arriba, no girados.','Entra en el estiramiento lentamente, nunca rebotes.'], '/exercises/seated-straddle-stretch-main.webp', '/exercises/seated-straddle-stretch-main.webp'),
  ('Encogimiento con Barra', 'shrug', 'traps', ARRAY['back'], 'barbell', 'beginner', 'isolation', 'Un movimiento de aislamiento para el trapecio superior.', ARRAY['De pie, sostén una barra a lo largo de los brazos con agarre en pronación.','Encoge los hombros directamente hacia las orejas.','Mantén brevemente en la parte superior.','Baja los hombros con control.','Repite.'], ARRAY['Sube los hombros en vertical, sin hacer círculos.','No uses los brazos; los codos quedan extendidos todo el tiempo.','Evita impulsarte con las piernas para subir más peso.'], '/exercises/shrug-main.webp', '/exercises/shrug-main.webp'),
  ('Zancada Lateral', 'side-lunge', 'glutes', ARRAY['hamstrings','core'], NULL, 'intermediate', 'compound', 'Una zancada lateral que da un paso amplio hacia un lado, trabajando los cuádriceps, glúteos y la cara interna de los muslos en un patrón lateral.', ARRAY['De pie con los pies al ancho de las caderas y las manos en el pecho.','Da un paso amplio hacia un lado con una pierna, manteniendo la otra recta.','Flexiona la rodilla de la pierna que dio el paso y empuja las caderas hacia atrás en una sentadilla lateral.','Mantén el pecho erguido y el talón de trabajo apoyado.','Empuja con la pierna flexionada para volver a la posición de pie.','Completa las repeticiones de un lado y luego cambia.'], ARRAY['Empuja las caderas hacia atrás mientras flexionas la rodilla del paso.','Mantén la pierna contraria estirada y ambos talones apoyados.','Mantén el pecho erguido en lugar de redondear hacia delante.'], '/exercises/side-lunge-main.webp', '/exercises/side-lunge-main.webp'),
  ('Abducción de Cadera Acostado de Lado', 'side-lying-hip-abduction', 'abductors', NULL, NULL, 'beginner', 'isolation', 'Un ejercicio de aislamiento con peso corporal que trabaja el glúteo medio y los abductores de cadera.', ARRAY['Acuéstate de lado con las piernas apiladas.','Mantén la pierna inferior ligeramente flexionada.','Eleva la pierna superior hacia el techo.','Baja con control.','Repite de ambos lados.'], ARRAY['Mantén las caderas apiladas durante todo el ejercicio.','Evita inclinar la pelvis.'], '/exercises/side-lying-hip-abduction-main.webp', '/exercises/side-lying-hip-abduction-main.webp'),
  ('Abducción de Cadera Acostado de Lado Isométrica', 'side-lying-hip-abduction-hold', 'abductors', NULL, NULL, 'beginner', 'isolation', 'La parte alta de la elevación lateral de pierna mantenida en el tiempo: tumbado de lado con la pierna superior elevada y ligeramente por detrás del cuerpo, cargando el glúteo medio de forma isométrica.', ARRAY['Túmbate de lado con las piernas estiradas y apiladas, apoyando la cabeza sobre el brazo inferior.','Aprieta el tronco para que el torso quede cuadrado y no ruede hacia atrás.','Eleva la pierna superior unos 30 o 45 grados, con los dedos del pie apuntando al frente.','Mantén la pierna ahí durante el tiempo indicado, respirando con normalidad.','Baja la pierna de forma controlada y repite del otro lado.'], ARRAY['Girar los dedos hacia el techo pasa el trabajo al flexor de la cadera; mantenlos mirando al frente.','Lleva la pierna algo por detrás de la línea del cuerpo para enfatizar el glúteo medio.','Apoya la mano superior en el suelo por delante si el equilibrio es lo que te limita.'], '/exercises/side-lying-hip-abduction-hold-main.webp', '/exercises/side-lying-hip-abduction-hold-main.webp'),
  ('Aducción de Cadera Acostado de Lado', 'side-lying-hip-adduction', 'adductors', NULL, NULL, 'intermediate', 'isolation', 'Un ejercicio de aducción tumbado de lado que eleva la pierna inferior contra la gravedad para trabajar la cadera con el propio peso.', ARRAY['Acuéstate de lado con la pierna inferior recta.','Flexiona la pierna superior y coloca su pie plano frente al muslo inferior.','Apoya la cabeza con el brazo inferior.','Eleva la pierna inferior hacia el techo.','Baja la pierna con control.','Completa las repeticiones de un lado y luego cambia.'], ARRAY['Mueve solo la pierna; la cadera y el torso quedan quietos.','Sube la pierna sin impulso y baja despacio.','Alinea hombros, cadera y pies antes de empezar a moverte.'], '/exercises/side-lying-hip-adduction-main.webp', '/exercises/side-lying-hip-adduction-main.webp'),
  ('Aducción de Cadera Acostado de Lado Isométrica', 'side-lying-hip-adduction-hold', 'adductors', NULL, NULL, 'intermediate', 'isolation', 'La parte alta de la elevación de cara interna del muslo mantenida en el tiempo: tumbado de lado con la pierna superior cruzada por delante y la pierna inferior separada del suelo por los aductores.', ARRAY['Túmbate de lado con la pierna inferior estirada y la superior cruzada por encima, con el pie apoyado en el suelo.','Apoya la cabeza sobre el brazo inferior y mantén las caderas apiladas en vertical.','Eleva la pierna inferior todo lo que puedas con la rodilla estirada y los dedos del pie al frente.','Mantén esa posición elevada durante el tiempo indicado sin rodar la cadera hacia atrás.','Baja la pierna de forma controlada y repite del otro lado.'], ARRAY['El recorrido es corto: unos pocos centímetros con la pelvis quieta valen más que un balanceo amplio.','Mantén la pierna elevada en línea con el torso en lugar de dejar que se vaya hacia delante.','Presiona ligeramente el pie superior contra el suelo si necesitas estabilizar la posición.'], '/exercises/side-lying-hip-adduction-hold-main.webp', '/exercises/side-lying-hip-adduction-hold-main.webp'),
  ('Elevación Lateral Tumbado de Lado', 'side-lying-lateral-raise', 'shoulders', ARRAY['traps'], 'dumbbell', 'beginner', 'isolation', 'Un ejercicio de aislamiento del deltoides lateral con mancuerna en posición lateral sobre un banco plano, que proporciona tensión constante sin impulso.', ARRAY['Túmbate de lado sobre un banco plano usando el brazo inferior para apoyar la cabeza o sujetar el borde del banco.','Sujeta una mancuerna con la mano superior con el brazo descansando a lo largo del costado.','Con el codo ligeramente flexionado, eleva la mancuerna hasta que el brazo quede perpendicular al suelo.','Pausa brevemente arriba, luego baja la mancuerna despacio hasta el costado.','Completa todas las repeticiones en un lado antes de cambiar.'], ARRAY['Mantén el torso quieto — solo el brazo de trabajo debe moverse.','La posición tumbada elimina el impulso y aísla eficazmente el deltoides lateral.','Usa un peso más ligero que en la elevación lateral de pie — la palanca es más exigente.'], '/exercises/side-lying-lateral-raise-main.webp', '/exercises/side-lying-lateral-raise-main.webp'),
('Plancha Lateral', 'side-plank', 'core', ARRAY['glutes'], NULL, 'beginner', 'compound', 'Una variación de plancha lateral que trabaja los oblicuos y el core lateral.', ARRAY['Acuéstate de lado con el antebrazo en el suelo y el codo bajo el hombro.','Levanta las caderas del suelo formando una línea recta de la cabeza a los pies.','Mantén la posición con el core apretado.','Respira con regularidad.','Repite de ambos lados.'], ARRAY['No dejes que la cadera se hunda hacia el suelo.','Alinea hombros y cadera en un mismo plano, sin rotar el torso.','Empuja el suelo con el antebrazo para no colgarte del hombro.'], '/exercises/side-plank-main.webp', '/exercises/side-plank-main.webp'),
  ('Plancha Lateral con Elevación de Pierna', 'side-plank-leg-lift', 'glutes', ARRAY['core'], NULL, 'intermediate', 'compound', 'Una plancha lateral con elevación de la pierna superior, que combina trabajo de core lateral con abducción de cadera.', ARRAY['Túmbate de lado con el antebrazo en el suelo y el codo bajo el hombro.','Coloca un pie sobre el otro y eleva las caderas hasta una plancha lateral.','Desde esta plancha lateral estable, sube la pierna de arriba recta hacia el techo.','Baja la pierna de forma controlada sin dejar caer las caderas.','Completa las repeticiones de un lado y luego cambia.'], ARRAY['Mantén las caderas elevadas toda la serie; no dejes que se hundan.','Guía la elevación de la pierna con el talón, no con la punta.','Mantén el cuerpo en una sola línea recta de la cabeza al pie de abajo.'], '/exercises/side-plank-leg-lift-main.webp', '/exercises/side-plank-leg-lift-main.webp'),
  ('Plancha Lateral con Elevación de Pierna Isométrica', 'side-plank-leg-lift-hold', 'glutes', ARRAY['core'], NULL, 'intermediate', 'compound', 'Una plancha lateral sostenida con la pierna superior elevada: la cadera se mantiene alta y cuadrada mientras la pierna se separa, lo que añade una demanda de glúteo medio al trabajo lateral del tronco.', ARRAY['Colócate en plancha lateral sobre el antebrazo, con el codo bajo el hombro y los pies apilados.','Eleva la cadera hasta que el cuerpo forme una línea recta desde los tobillos hasta la cabeza.','Sube la pierna superior aproximadamente a la altura de la cadera, con los dedos del pie al frente.','Mantén la posición durante el tiempo indicado, con la cadera alta y el hombro alineado sobre el codo.','Baja la pierna y la cadera de forma controlada y repite del otro lado.'], ARRAY['Aleja del oído el hombro de apoyo para que el pecho no se venga abajo hacia el suelo.','Termina la serie cuando la cadera empiece a caer, no cuando se canse la pierna.','Apoya la rodilla inferior en el suelo para una versión más sencilla que conserva la elevación de pierna.'], '/exercises/side-plank-leg-lift-hold-main.webp', '/exercises/side-plank-leg-lift-hold-main.webp'),
  ('Remo con Mancuerna a Una Mano con Pecho Apoyado', 'single-arm-chest-supported-dumbbell-row', 'back', ARRAY['biceps','shoulders'], 'dumbbell', 'intermediate', 'compound', 'Un remo unilateral realizado con un brazo a la vez sobre un banco inclinado con apoyo para el pecho, que aísla cada lado de la espalda y reduce el impulso.', ARRAY['Túmbate boca abajo en un banco inclinado sujetando una mancuerna con una mano, con el brazo colgando recto hacia abajo.','Rema la mancuerna hacia tu costado, llevando el codo más allá del torso.','Aprieta el omóplato en la parte superior y luego baja de forma controlada.','Completa todas las repeticiones de un lado antes de cambiar de brazo.'], ARRAY['Trabajar un lado a la vez te permite concentrarte en una contracción completa sin que el otro brazo compense.','Mantén el pecho presionado contra el banco durante todo el movimiento para evitar usar impulso.','Iguala el número de repeticiones en ambos lados para evitar desequilibrios.'], '/exercises/single-arm-chest-supported-dumbbell-row-main.webp', '/exercises/single-arm-chest-supported-dumbbell-row-main.webp'),
  ('Remo con Mancuerna a Un Brazo', 'single-arm-db-row', 'back', ARRAY['biceps','shoulders'], 'dumbbell', 'intermediate', 'compound', 'Un ejercicio de espalda unilateral con mancuerna para un desarrollo equilibrado.', ARRAY['Coloca una rodilla y una mano en un banco como apoyo.','Sostén una mancuerna en la otra mano con el brazo extendido.','Tira de la mancuerna hacia la cadera apretando el omóplato.','Baja la mancuerna con control.','Repite de ambos lados.'], ARRAY['No gires el torso al tirar; mantén la cadera estable.','Evita encoger el hombro hacia la oreja al iniciar el tirón.','Haz las mismas repeticiones con cada brazo.'], '/exercises/single-arm-db-row-main.webp', '/exercises/single-arm-db-row-main.webp'),
  ('Extensión de Tríceps sobre la Cabeza con Mancuerna a Un Brazo', 'single-arm-dumbbell-overhead-tricep-extension', 'triceps', ARRAY['core'], 'dumbbell', 'beginner', 'isolation', 'Una extensión de tríceps sobre la cabeza a un brazo que proporciona un estiramiento largo y unilateral de la cabeza larga y entrena la estabilidad del core contra la flexión lateral.', ARRAY['De pie o sentado, sostén una mancuerna en una mano sobre la cabeza con el brazo completamente extendido.','La palma mira hacia adelante; la otra mano puede apoyarse en la cadera o en un soporte para mayor estabilidad.','Flexiona el codo para bajar la mancuerna detrás de la cabeza en un arco controlado.','Mantén el brazo superior vertical y cerca de la cabeza durante todo el movimiento.','Extiende el codo para regresar la mancuerna sobre la cabeza.','Completa todas las repeticiones de un lado y luego cambia.'], ARRAY['Solo el antebrazo se mueve — el brazo superior permanece fijo en su lugar.','No dejes que el torso se incline hacia un lado; este también es un ejercicio de core.'], '/exercises/single-arm-dumbbell-overhead-tricep-extension-main.webp', '/exercises/single-arm-dumbbell-overhead-tricep-extension-main.webp'),
  ('Curl martillo unilateral', 'single-arm-hammer-curl', 'biceps', ARRAY['forearms'], 'dumbbell', 'intermediate', 'isolation', 'Un curl unilateral con mancuerna y agarre neutro que mantiene el codo de trabajo junto al torso mientras el braquial y el braquiorradial flexionan el codo.', ARRAY['Colócate con los pies al ancho de las caderas y sostén una mancuerna al costado con la palma hacia dentro.','Activa el tronco y mantén el brazo de trabajo junto a las costillas mientras cuelga extendido.','Lleva la mancuerna hacia el hombro sin girar la palma ni balancear el torso.','Aprieta los flexores del codo arriba y baja la mancuerna de forma controlada hasta extender el brazo.','Completa las repeticiones de un lado y después cambia de brazo.'], ARRAY['Deja que el lado más débil marque el peso y las repeticiones para que ambos lados reciban el mismo trabajo.','Mantén la muñeca neutra y el hombro quieto; el movimiento debe venir del codo.','Controla la bajada en lugar de dejar caer la mancuerna desde arriba.'], '/exercises/single-arm-hammer-curl-main.webp', '/exercises/single-arm-hammer-curl-main.webp'),
  ('Press de hombros unilateral en máquina', 'single-arm-machine-shoulder-press', 'shoulders', ARRAY['traps','triceps'], 'machine', 'beginner', 'compound', 'Un press de hombros unilateral sentado en máquina que permite empujar cada brazo por separado mientras la espalda permanece apoyada y la máquina guía la resistencia.', ARRAY['Ajusta el asiento para que el agarre de trabajo comience cerca del hombro y apoya firmemente la espalda en el respaldo.','Sujeta un agarre con la muñeca recta y deja la mano libre sobre el soporte.','Empuja el agarre hacia arriba sin separarte del respaldo ni girar el torso.','Baja el agarre bajo control hasta que el codo quede justo por debajo de la posición inicial.','Completa las repeticiones de un lado y después entrena el otro lado.'], ARRAY['Comienza con el brazo más débil y deja que marque el peso y las repeticiones de ambos lados.','Mantén las costillas abajo y la espalda contra el respaldo en lugar de inclinarte hacia un lado.','Detén el movimiento ante una posición dolorosa del hombro; el recorrido de la máquina debe sentirse controlado.'], '/exercises/single-arm-machine-shoulder-press-main.webp', '/exercises/single-arm-machine-shoulder-press-main.webp'),
  ('Elevación Lateral a Un Brazo en Máquina de Discos', 'single-arm-plate-loaded-lateral-raise', 'shoulders', ARRAY['traps'], 'machine', 'beginner', 'isolation', 'La elevación lateral en máquina de discos trabajando un brazo cada vez, de modo que cada lado levanta su propia carga y ambos pueden entrenarse hasta el mismo nivel.', ARRAY['Ajusta la altura del asiento para que el eje de la almohadilla quede alineado con tu hombro y carga solo el lado que vas a trabajar.','Siéntate con la espalda apoyada en el respaldo y coloca la cara externa del brazo que trabaja contra su almohadilla.','Sujeta la empuñadura del lado libre o apoya esa mano en el regazo, y mantén el torso alineado con el asiento.','Empuja el brazo que trabaja hacia fuera y hacia arriba contra la almohadilla hasta la altura del hombro, y baja de forma controlada.','Completa todas las repeticiones de ese lado, luego carga y trabaja el otro lado.'], ARRAY['Iguala los lados por el brazo débil, no por el fuerte. Trabajar un lado cada vez solo revela un desequilibrio si dejas que el lado débil fije el número de repeticiones.','No dejes que el torso se incline hacia el lado que trabaja. Con carga en un solo brazo la máquina ya no se equilibra sola, y inclinarse convierte la elevación en una flexión lateral.','Empieza por el brazo débil para que marque el objetivo, y da el mismo descanso a los dos lados.'], '/exercises/single-arm-plate-loaded-lateral-raise-main.webp', '/exercises/single-arm-plate-loaded-lateral-raise-main.webp'),
  ('Extensión de Tríceps a Un Brazo en Polea', 'single-arm-tricep-pushdown', 'triceps', ARRAY['forearms'], 'cable', 'intermediate', 'compound', 'Un ejercicio de aislamiento de tríceps realizado con un brazo a la vez en una máquina de polea con una sola manija.', ARRAY['Coloca una manija individual en una polea alta.','Sujeta la manija con una mano y mantén el codo pegado al costado.','Empuja la manija hacia abajo hasta extender completamente el brazo.','Contrae el tríceps en la parte baja.','Vuelve lentamente a la posición inicial.','Completa las repeticiones de un lado y luego cambia.'], ARRAY['Mantén el codo pegado al costado en todo momento.','Evita inclinarte hacia adelante para generar impulso.','Extiende el brazo por completo en la parte baja para una contracción total.'], '/exercises/single-arm-tricep-pushdown-main.webp', '/exercises/single-arm-tricep-pushdown-main.webp'),
  ('Press Svend con una Mancuerna', 'single-db-svend-press', 'chest', ARRAY['shoulders','triceps'], 'dumbbell', 'beginner', 'isolation', 'Un press de pecho de pie sosteniendo una sola mancuerna en vertical entre las palmas, donde lo que trabaja los pectorales es la presión hacia adentro y no la carga.', ARRAY['De pie y erguido, sostén una sola mancuerna en vertical frente al esternón, con el mango entre las palmas planas.','Aprieta con fuerza las palmas contra la mancuerna para que la tensión vaya al pecho y el peso no resbale.','Empuja la mancuerna recto hacia adelante hasta extender por completo los brazos, manteniéndola a la altura del pecho todo el recorrido.','Haz una breve pausa sin soltar la presión y devuelve la mancuerna al pecho con control.','Repite el número de repeticiones recomendado.'], ARRAY['La presión sobre la mancuerna hace el ejercicio. Si agarras el mango en lugar de aplastar el peso entre las palmas planas, el pecho no trabaja.','Usa una mancuerna ligera. Las palmas la sostienen solo por fricción, así que el agarre marca el límite mucho antes que el pecho.','Mantén los codos ligeramente flexionados en el lockout y la mancuerna a la altura del esternón; si baja hacia las caderas, los pectorales dejan de trabajar.'], '/exercises/single-db-svend-press-main.webp', '/exercises/single-db-svend-press-main.webp'),
  ('Elevación de Pantorrilla a Una Pierna', 'single-leg-calf-raise', 'calves', NULL, NULL, 'beginner', 'isolation', 'Una elevación de pantorrilla unilateral que carga una pantorrilla a la vez y expone desequilibrios laterales.', ARRAY['Mantente sobre un pie con la punta sobre una plataforma elevada, talón al aire.','Sujétate a una pared o barandilla con una mano para equilibrio.','Baja el talón por debajo de la plataforma para un estiramiento profundo.','Empuja arriba sobre la punta tan alto como puedas.','Baja con control. Repeticiones por lado, luego cambia.'], ARRAY['Pausa arriba para maximizar la contracción.','Usa una excéntrica lenta para el estiramiento completo.','Sostén una mancuerna del lado que trabaja cuando el peso corporal sea fácil.'], '/exercises/single-leg-calf-raise-main.webp', '/exercises/single-leg-calf-raise-main.webp'),
  ('Extensión de Cuádriceps a Una Pierna', 'single-leg-extension', 'quads', NULL, 'machine', 'intermediate', 'isolation', 'Un ejercicio de aislamiento de cuádriceps en una máquina de extensión de piernas, trabajando una pierna a la vez.', ARRAY['Siéntate en una máquina de extensión de piernas y coloca un pie bajo la almohadilla.','Deja el otro pie apoyado en el suelo o colgando.','Extiende la pierna de trabajo hasta que quede casi recta.','Contrae el cuádriceps en la parte alta.','Baja la pierna con control.','Completa las repeticiones de un lado y luego cambia.'], ARRAY['Contrae con fuerza el cuádriceps en la parte alta del movimiento.','Baja el peso con control en lugar de dejarlo caer.','Mantén la espalda plana contra el respaldo.'], '/exercises/single-leg-extension-main.webp', '/exercises/single-leg-extension-main.webp'),
  ('Puente de Glúteo a Una Pierna', 'single-leg-glute-bridge', 'glutes', ARRAY['back','hamstrings'], NULL, 'intermediate', 'compound', 'Un puente de glúteo unilateral que carga un glúteo a la vez y ayuda a corregir desequilibrios laterales.', ARRAY['Acuéstate boca arriba con una rodilla flexionada y el pie plano, la otra pierna extendida recta.','Activa el core y contrae el glúteo del lado que trabaja.','Empuja las caderas arriba presionando con el talón de trabajo.','Pausa arriba con el cuerpo en línea recta de hombros a rodilla.','Baja con control. Repeticiones por lado, luego cambia.'], ARRAY['Mantén la pierna extendida en línea con el muslo de trabajo.','Contrae el glúteo arriba — no empujes desde la zona lumbar.','Ralentiza la fase de bajada para más estímulo.'], '/exercises/single-leg-glute-bridge-main.webp', '/exercises/single-leg-glute-bridge-main.webp'),
  ('Puente de Glúteo a Una Pierna Isométrico', 'single-leg-glute-bridge-hold', 'glutes', ARRAY['back','hamstrings'], NULL, 'intermediate', 'compound', 'La parte alta del puente de glúteo a una pierna mantenida en el tiempo: la cadera queda extendida y nivelada mientras una pierna permanece elevada, de modo que un solo glúteo sostiene toda la posición.', ARRAY['Túmbate boca arriba con una rodilla flexionada y ese pie apoyado, y eleva la otra pierna hasta que el muslo quede casi vertical.','Empuja con el talón del pie apoyado y eleva la cadera hasta que el cuerpo quede recto desde la rodilla hasta los hombros.','Nivela la pelvis para que el lado elevado no caiga y lleva las costillas hacia abajo.','Mantén la posición alta durante el tiempo indicado, con la rodilla elevada quieta.','Baja la cadera de forma controlada y repite del otro lado.'], ARRAY['Fíjate en la pelvis más que en la altura: una cadera nivelada un poco más abajo vale más que una alta y girada.','Mantén el talón apoyado cerca del glúteo para que el isquiotibial no se acalambre.','Estira del todo la pierna libre si la posición te resulta fácil, pero solo mientras la pelvis siga nivelada.'], '/exercises/single-leg-glute-bridge-hold-main.webp', '/exercises/single-leg-glute-bridge-hold-main.webp'),
  ('Curl de Pierna Tumbado a Una Pierna', 'single-leg-lying-leg-curl', 'hamstrings', ARRAY['calves'], 'machine', 'intermediate', 'isolation', 'Un curl femoral tumbado a una pierna en máquina, que aísla los isquiotibiales de cada lado por separado.', ARRAY['Acuéstate boca abajo en la máquina de curl de piernas tumbado.','Coloca un tobillo bajo el apoyo y deja el otro pie fuera de la máquina.','Flexiona la pierna de trabajo llevando el talón hacia el glúteo.','Aprieta los isquiotibiales en la parte superior.','Baja la pierna con control.','Completa las repeticiones de un lado y luego cambia.'], ARRAY['Mantén la cadera pegada al apoyo durante todo el recorrido.','Usa un peso que te permita subir y bajar sin tirones.','Empieza por la pierna más débil y repite igual con la otra.'], '/exercises/single-leg-lying-leg-curl-main.webp', '/exercises/single-leg-lying-leg-curl-main.webp'),
  ('Prensa de Piernas a Una Pierna', 'single-leg-press', 'glutes', ARRAY['hamstrings'], 'machine', 'intermediate', 'compound', 'Un ejercicio de tren inferior en una máquina de prensa, empujando la plataforma con una pierna a la vez.', ARRAY['Siéntate en la máquina de prensa con un pie sobre la plataforma.','Mantén la otra pierna fuera de la plataforma, apoyada a un lado.','Suelta los seguros y baja la plataforma flexionando la rodilla.','Detente cuando la rodilla forme un ángulo cercano a 90 grados.','Empuja a través del talón para devolver la plataforma.','Completa las repeticiones de un lado y luego cambia.'], ARRAY['Mantén el pie plano y centrado en la plataforma.','Evita que la rodilla se desplace hacia adentro.','No bloquees la rodilla con fuerza en la parte alta.'], '/exercises/single-leg-press-main.webp', '/exercises/single-leg-press-main.webp'),
  ('Peso Muerto Rumano a Una Pierna', 'single-leg-romanian-deadlift', 'glutes', ARRAY['back'], 'dumbbell', 'intermediate', 'compound', 'Un peso muerto rumano a una pierna con mancuernas, que trabaja isquiotibiales y glúteos mientras exige equilibrio y estabilidad de cadera.', ARRAY['Apóyate en una pierna sosteniendo una mancuerna en cada mano frente a los muslos.','Mantén una ligera flexión en la rodilla de apoyo.','Bisagra en la cadera extendiendo la pierna libre detrás.','Baja las mancuernas a lo largo de la pierna de apoyo hasta sentir el estiramiento en los isquiotibiales.','Empuja con el talón para volver a la posición erguida.','Completa las repeticiones de un lado y luego cambia.'], ARRAY['Mantén la cadera cuadrada; no dejes que se abra hacia el lado.','Si pierdes el equilibrio, reduce el rango o usa menos peso.','Mira un punto fijo en el suelo para estabilizarte.'], '/exercises/single-leg-romanian-deadlift-main.webp', '/exercises/single-leg-romanian-deadlift-main.webp'),
('Abdominales', 'sit-ups', 'core', NULL, NULL, 'beginner', 'compound', 'Un ejercicio abdominal clásico con rango de movimiento completo.', ARRAY['Acuéstate boca arriba con las rodillas flexionadas y los pies anclados.','Cruza los brazos sobre el pecho o coloca las manos detrás de la cabeza.','Siéntate completamente hasta que el torso quede erguido.','Baja con control.','Repite.'], ARRAY['No tires del cuello con las manos al subir.','Exhala mientras subes para mantener el abdomen activo.','Si notas tirantez lumbar, reduce el rango de movimiento.'], '/exercises/sit-ups-main.webp', '/exercises/sit-ups-main.webp'),
  ('Skull Crusher', 'skull-crusher', 'triceps', NULL, 'barbell', 'intermediate', 'isolation', 'Una extensión de tríceps tumbado con barra que aísla los tríceps a través de un rango de movimiento completo.', ARRAY['Acuéstate en un banco plano sosteniendo una barra sobre el pecho con agarre estrecho.','Baja la barra hacia la frente flexionando los codos.','Extiende los brazos de vuelta a la posición inicial.','Repite.'], ARRAY['Mantén los brazos superiores verticales durante todo el ejercicio.','Baja lentamente para proteger los codos.'], '/exercises/skull-crusher-main.webp', '/exercises/skull-crusher-main.webp'),
  ('Remo con Trineo', 'sled-row', 'back', ARRAY['biceps','glutes','shoulders','traps'], 'machine', 'intermediate', 'compound', 'Un remo con carga: agarras el trineo y lo tiras hacia ti mientras caminas hacia atrás, trabajando la espalda con un arrastre continuo en lugar de repeticiones sueltas.', ARRAY['Carga el trineo y agarra sus postes con ambas manos, una en cada poste.','Ponte de pie frente al trineo con los brazos estirados y el torso ligeramente inclinado hacia atrás contra la carga.','Tira del trineo hacia ti llevando los codos atrás y da un paso corto hacia atrás al mismo tiempo.','Estira los brazos de nuevo, da otro paso atrás y repite el tirón.','Continúa por distancia o por tiempo, manteniendo un ritmo constante de tirón y paso.'], ARRAY['Pecho arriba y espalda recta: deja que las piernas te lleven hacia atrás en vez de encorvarte sobre el trineo.','Usa una carga que puedas mover de forma continua; la idea es un arrastre constante, no un tirón máximo.','Si tu gimnasio tiene asas o una cuerda para el trineo, funcionan igual.'], '/exercises/sled-row-main.webp', '/exercises/sled-row-main.webp'),
  ('Press de Banca en Máquina Smith', 'smith-machine-bench-press', 'chest', ARRAY['shoulders','triceps'], 'smith_machine', 'beginner', 'compound', 'Un press de banca en máquina Smith cuyo recorrido guiado permite entrenar el pecho con menos demanda de estabilización.', ARRAY['Acuéstate en un banco plano dentro de la máquina Smith.','Agarra la barra ligeramente más ancho que el ancho de hombros y desbloquéala.','Baja la barra con control hasta el centro del pecho.','Haz una breve pausa sin rebotar.','Empuja la barra hacia arriba hasta extender completamente los brazos.','Repite el número de repeticiones deseado.'], ARRAY['Alinea el banco para que la barra baje a la mitad del pecho.','Mantén los pies firmes en el suelo durante toda la serie.','Aprende el giro de muñeca para enganchar la barra antes de cargar peso.'], '/exercises/smith-machine-bench-press-main.webp', '/exercises/smith-machine-bench-press-main.webp'),
  ('Remo Inclinado en Máquina Smith', 'smith-machine-bent-over-row', 'back', ARRAY['biceps','traps'], 'smith_machine', 'beginner', 'compound', 'Un remo inclinado en máquina Smith que trabaja dorsales y romboides con una trayectoria de barra fija.', ARRAY['De pie dentro de la máquina Smith con los pies al ancho de los hombros.','Agarra la barra en pronación ligeramente más ancho que los hombros.','Bisagra en las caderas hasta que el torso esté aproximadamente a 45 grados.','Tira de la barra hacia el pecho inferior llevando los codos hacia atrás.','Aprieta los omóplatos en la parte superior.','Baja la barra con control y repite.'], ARRAY['Mantén la espalda recta y el core firme en la inclinación.','No te incorpores al tirar; el ángulo del torso no cambia.','Evita encoger los hombros hacia las orejas durante el remo.'], '/exercises/smith-machine-bent-over-row-main.webp', '/exercises/smith-machine-bent-over-row-main.webp'),
  ('Sentadilla Búlgara en Máquina Smith', 'smith-machine-bulgarian-split', 'glutes', ARRAY['hamstrings'], 'smith_machine', 'intermediate', 'compound', 'Una sentadilla búlgara realizada en la máquina Smith para mayor estabilidad y control de la carga.', ARRAY['Coloca un banco detrás de la máquina Smith. Apoya la barra sobre los trapecios.','Coloca el pie trasero en el banco y el pie delantero hacia adelante.','Baja la rodilla trasera hacia el suelo.','Empuja con el talón delantero para volver.','Repite de ambos lados.'], ARRAY['La máquina Smith guía la trayectoria de la barra.','Concéntrate en mantener la rodilla delantera alineada sobre los dedos del pie.'], '/exercises/smith-machine-bulgarian-split-main.webp', '/exercises/smith-machine-bulgarian-split-main.webp'),
  ('Elevación de Talón en Máquina Smith', 'smith-machine-calf-raise', 'calves', NULL, 'smith_machine', 'beginner', 'isolation', 'Una elevación de talones en máquina Smith de pie sobre una plataforma, que aísla los gemelos con un estiramiento completo.', ARRAY['Coloca la barra de la máquina Smith sobre la parte superior de la espalda y los hombros.','De pie sobre una pequeña plataforma para que los talones puedan bajar por debajo de los dedos.','Desbloquea la barra y elévate sobre las puntas de los pies.','Aprieta las pantorrillas con fuerza en la parte superior.','Baja los talones por debajo de la plataforma para un estiramiento completo.','Repite el número de repeticiones deseado.'], ARRAY['Haz una pausa arriba y otra abajo para eliminar el rebote.','No dobles las rodillas; el movimiento sale solo del tobillo.','Mantén el cuerpo erguido, sin inclinarte hacia delante.'], '/exercises/smith-machine-calf-raise-main.webp', '/exercises/smith-machine-calf-raise-main.webp'),
  ('Press de Banca Declinado en Máquina Smith', 'smith-machine-decline-bench-press', 'chest', ARRAY['shoulders','triceps'], 'smith_machine', 'beginner', 'compound', 'Un press de banca en banco declinado bajo la máquina Smith, donde el ángulo con la cabeza abajo y la trayectoria guiada llevan el trabajo al pectoral inferior.', ARRAY['Coloca un banco declinado en la máquina de modo que la barra quede alineada con tu pecho inferior al tumbarte, y engancha las piernas bajo los rodillos.','Túmbate con la cabeza en el extremo bajo, toma un agarre prono algo más ancho que los hombros y desengancha la barra.','Baja la barra de forma controlada hasta que toque el pecho inferior, manteniendo los codos a unos cuarenta y cinco grados del torso.','Empuja la barra hacia arriba hasta extender los brazos, sin bloquear los codos con fuerza.','Repite el número de repeticiones deseado y vuelve a enganchar la barra antes de soltar las piernas.'], ARRAY['Alinea el banco antes de cargarlo. La barra solo se mueve en un plano, así que si el banco está unos centímetros desviado la barra te llegará a la garganta o al estómago en lugar del pecho inferior.','Asegura primero las piernas bajo los rodillos. Con la cabeza abajo y sin sujeción, te deslizarás hacia el extremo bajo del banco en la primera repetición dura.','Incorpórate despacio entre series. Las series largas con la cabeza por debajo del corazón marean a mucha gente, y esta es la variante donde ocurre.'], '/exercises/smith-machine-decline-bench-press-main.webp', '/exercises/smith-machine-decline-bench-press-main.webp'),
  ('Sentadilla Frontal en Máquina Smith', 'smith-machine-front-squat', 'glutes', ARRAY['back','hamstrings'], 'smith_machine', 'beginner', 'compound', 'Una sentadilla en máquina Smith con la barra apoyada al frente sobre los hombros, donde la trayectoria fija y el torso erguido mantienen el trabajo en los cuádriceps.', ARRAY['Coloca la barra a la altura del pecho alto y métete debajo para que se apoye al frente de los hombros, contra las clavículas.','Cruza los brazos sobre la barra o toma un agarre frontal abierto, y sube los codos hasta que los brazos queden casi paralelos al suelo.','Desengancha la barra y separa los pies aproximadamente al ancho de los hombros, ligeramente por delante de ella.','Baja en línea recta manteniendo los codos altos y el torso erguido, hasta que los muslos queden al menos paralelos al suelo.','Empuja desde el medio de los pies para volver a subir y repite el número de repeticiones deseado.'], ARRAY['Los codos altos son toda la ejercicio. En cuanto bajan, la barra rueda de los hombros hacia las manos y la posición frontal se desmorona.','Ajusta los topes de seguridad justo por debajo de tu posición más profunda antes de desenganchar nada: en una sentadilla frontal, soltar la barra es la salida más rápida de una repetición fallida.','Colocarte ligeramente por delante de la barra te permite mantener el torso vertical. Con una trayectoria fija, situarte justo debajo de la barra te obliga a inclinarte y empuja la barra fuera del apoyo frontal.'], '/exercises/smith-machine-front-squat-main.webp', '/exercises/smith-machine-front-squat-main.webp'),
  ('Buenos Días en Máquina Smith', 'smith-machine-good-morning', 'back', ARRAY['glutes'], 'smith_machine', 'beginner', 'compound', 'Una bisagra de cadera con la barra de la máquina Smith apoyada sobre la espalda alta, inclinándote hacia delante desde las caderas contra una trayectoria fija para cargar isquiotibiales y erectores espinales.', ARRAY['Coloca la barra a la altura de la espalda alta, métete debajo y apóyala sobre los trapecios; desengánchala con los pies al ancho de las caderas.','Flexiona ligeramente las rodillas y déjalas así: esto es una bisagra, no una sentadilla.','Empuja las caderas rectas hacia atrás y deja que el torso se incline hacia delante, con la espalda plana y la cabeza en línea con la columna.','Detente cuando sientas un estiramiento fuerte en los isquiotibiales, con el torso cerca de la paralela al suelo.','Lleva las caderas hacia delante para volver a erguirte, aprieta los glúteos arriba y repite las repeticiones deseadas.'], ARRAY['Usa mucho menos peso del que usarías en una sentadilla. Abajo, la barra queda muy lejos de tus caderas, y ese brazo de palanca, no el número en la barra, es lo que cuesta el ejercicio.','Caderas atrás, no pecho abajo. Si el torso baja sin que las caderas retrocedan, estás flexionando la columna en lugar de hacer bisagra en la cadera.','Termina el recorrido donde tu espalda empezaría a redondearse. En un buenos días la profundidad la marcan tus isquiotibiales, y la máquina te llevará encantada más allá de ese punto.'], '/exercises/smith-machine-good-morning-main.webp', '/exercises/smith-machine-good-morning-main.webp'),
  ('Hip Thrust en Máquina Smith', 'smith-machine-hip-thrust', 'glutes', ARRAY['hamstrings'], 'smith_machine', 'beginner', 'compound', 'Un empuje de cadera con la barra en las guías de la máquina Smith, de modo que la carga recorre una línea vertical fija sobre las caderas mientras los hombros quedan apoyados en un banco.', ARRAY['Coloca un banco plano dentro de la máquina Smith, paralelo a la barra y situado de forma que la barra quede sobre el pliegue de tu cadera.','Baja la barra lo suficiente para poder pasar por debajo sentado en el suelo, y apoya la parte alta de la espalda en el banco.','Rueda la barra sobre las caderas, ponle una almohadilla si la necesitas y desengánchala, con los pies planos y a la anchura de las caderas.','Empuja con los talones y extiende las caderas hasta que muslos y torso formen una línea recta, apretando los glúteos arriba.','Baja las caderas de forma controlada hasta quedar justo por encima del suelo y repite el número de repeticiones deseado.'], ARRAY['Alinea el banco antes de cargar la barra. La barra solo sube y baja en vertical, así que si el banco está desplazado la barra acaba sobre el abdomen o los muslos, y a mitad de serie no hay forma de corregirlo.','Pon los topes de seguridad donde queda la barra al final del recorrido. Salir de debajo de una barra Smith cargada estando en el suelo es incómodo, y con los topes deja de ser un problema.','Mira a un punto por delante de ti en lugar de al techo. Mantener la barbilla recogida evita que el movimiento acabe en un arqueo lumbar al bloquear arriba.'], '/exercises/smith-machine-hip-thrust-main.webp', '/exercises/smith-machine-hip-thrust-main.webp'),
  ('Press Inclinado en Máquina Smith', 'smith-machine-incline-bench-press', 'shoulders', ARRAY['triceps'], 'smith_machine', 'beginner', 'compound', 'Un press inclinado en máquina Smith que enfatiza la parte superior del pecho y los deltoides anteriores con una trayectoria guiada.', ARRAY['Ajusta un banco inclinado a 30-45 grados dentro de la máquina Smith.','Recuéstate y agarra la barra ligeramente más ancho que el ancho de hombros.','Desbloquea y baja la barra hasta la parte superior del pecho.','Haz una breve pausa en la parte inferior.','Empuja la barra hacia arriba hasta extender los brazos.','Repite el número de repeticiones deseado.'], ARRAY['Ajusta la posición del banco para que la barra llegue a la parte alta del pecho.','Baja la barra sin rebotarla en el pecho.','Mantén los glúteos en el banco y los pies bien apoyados.'], '/exercises/smith-machine-incline-bench-press-main.webp', '/exercises/smith-machine-incline-bench-press-main.webp'),
  ('Peso Muerto Rumano en Máquina Smith', 'smith-machine-rdl', 'hamstrings', ARRAY['back','glutes','traps'], 'smith_machine', 'beginner', 'compound', 'Un peso muerto rumano realizado en la máquina Smith, que fija la trayectoria de la barra para que puedas concentrarte en la bisagra de cadera y el estiramiento de la cadena posterior.', ARRAY['Ajusta la barra de la máquina Smith a la altura de la mitad del muslo y colócate directamente debajo con los pies al ancho de las caderas.','Desbloquea la barra con agarre en pronación justo por fuera de las caderas.','Empuja las caderas hacia atrás mientras deslizas la barra por la parte delantera de las piernas.','Baja hasta sentir un estiramiento profundo en los isquiotibiales, con la espalda plana y las rodillas ligeramente flexionadas.','Empuja las caderas hacia adelante para volver a la posición de pie, manteniendo la barra cerca del cuerpo.','Repite el número de repeticiones recomendado.'], ARRAY['La barra está guiada en una trayectoria recta — úsala para perfeccionar el patrón de bisagra.','No redondees la zona lumbar al bajar; detente al final del rango de los isquiotibiales.'], '/exercises/smith-machine-rdl-main.webp', '/exercises/smith-machine-rdl-main.webp'),
  ('Remo Inclinado con Agarre Inverso en Máquina Smith', 'smith-machine-reverse-grip-bent-over-row', 'biceps', ARRAY['back','traps'], 'smith_machine', 'beginner', 'compound', 'Un remo inclinado con agarre supino en máquina Smith, que dirige el trabajo a los dorsales y bíceps.', ARRAY['De pie dentro de la máquina Smith y agarra la barra con agarre en supinación.','Bisagra hacia adelante en las caderas hasta que el torso esté aproximadamente a 45 grados.','Mantén la espalda plana y el core contraído.','Tira de la barra hacia el abdomen inferior.','Aprieta los dorsales y los omóplatos en la parte superior.','Baja la barra con control y repite.'], ARRAY['Mantén las muñecas rectas; el agarre supino las carga más.','No conviertas el remo en un curl; tira con la espalda.','Evita incorporarte al tirar; el torso mantiene su inclinación.'], '/exercises/smith-machine-reverse-grip-bent-over-row-main.webp', '/exercises/smith-machine-reverse-grip-bent-over-row-main.webp'),
  ('Zancada Inversa en Máquina Smith', 'smith-machine-reverse-lunge', 'glutes', ARRAY['hamstrings'], 'smith_machine', 'intermediate', 'compound', 'Una zancada inversa bajo la barra de la máquina Smith, dando un paso atrás con un pie y devolviéndolo a la posición de pie en cada repetición mientras la barra guiada mantiene la carga estable.', ARRAY['Coloca la barra de modo que descanse sobre los trapecios altos al estar de pie y desengánchala con los pies bajo las caderas.','Da un paso recto hacia atrás con un pie y baja la rodilla trasera hacia el suelo, manteniendo la tibia delantera vertical y la mayor parte del peso en el pie delantero.','Detente cuando la rodilla trasera esté a punto de tocar el suelo y el muslo delantero quede aproximadamente paralelo a él.','Empuja con el talón delantero y devuelve el pie trasero a la posición de pie bajo la barra.','Completa todas las repeticiones de un lado, o alterna piernas, y luego cambia.'], ARRAY['Da un paso atrás lo bastante largo. Un paso corto lleva la rodilla delantera muy por delante de los dedos, y la trayectoria fija de la barra no te dejará corregirlo una vez cargado.','El pie que se desplaza hace todo el recorrido; el pie delantero no se mueve en absoluto. Si cambia de sitio entre repeticiones, tu paso es demasiado largo o demasiado corto.','La máquina te quita el equilibrio, no la carga: mantén el tronco firme y levántate desde abajo en lugar de recostarte contra la barra.'], '/exercises/smith-machine-reverse-lunge-main.webp', '/exercises/smith-machine-reverse-lunge-main.webp'),
  ('Press de Hombros en Máquina Smith', 'smith-machine-shoulder-press', 'shoulders', ARRAY['traps','triceps'], 'smith_machine', 'beginner', 'compound', 'Un press vertical para deltoides en máquina Smith realizado sentado en un banco, con la barra estabilizada por los raíles.', ARRAY['Siéntate en un banco colocado dentro de una máquina Smith.','Agarra la barra ligeramente más ancha que el ancho de los hombros a la altura de los hombros.','Desrackea la barra y empújala por encima de la cabeza hasta que los brazos estén extendidos.','Baja la barra de vuelta a la altura de los hombros de forma controlada.','Mantén el core contraído durante todo el ejercicio.','Repite el número de repeticiones deseado.'], ARRAY['Sitúate de forma que la barra no roce la cabeza al subir.','Evita arquear la zona lumbar al empujar.','Suelta el aire en la subida de cada repetición.'], '/exercises/smith-machine-shoulder-press-main.webp', '/exercises/smith-machine-shoulder-press-main.webp'),
  ('Encogimiento de Hombros en Máquina Smith', 'smith-machine-shrug', 'traps', ARRAY['forearms'], 'smith_machine', 'beginner', 'isolation', 'Un encogimiento de hombros en máquina Smith que aísla el trapecio sin necesidad de estabilizar la barra.', ARRAY['Párate erguido dentro de una máquina Smith con la barra a la altura de los muslos.','Agarra la barra ligeramente más ancha que el ancho de los hombros con agarre prono.','Desrackea la barra y deja que cuelgue frente a tus muslos.','Encoge los hombros hacia arriba en dirección a las orejas.','Mantén la posición alta un momento, luego baja lentamente.','Repite el número de repeticiones deseado.'], ARRAY['Evita rotar los hombros; súbelos y bájalos en vertical.','No tires con los bíceps; los brazos solo sostienen la barra.','Mantén el cuello relajado y la mirada al frente.'], '/exercises/smith-machine-shrug-main.webp', '/exercises/smith-machine-shrug-main.webp'),
  ('Sentadilla en Tijera en Máquina Smith', 'smith-machine-split-squat', 'glutes', ARRAY['hamstrings'], 'smith_machine', 'intermediate', 'compound', 'Una sentadilla en tijera estática bajo la barra de la máquina Smith, con el pie trasero apoyado en el suelo en lugar de un banco, de modo que la trayectoria guiada quita el equilibrio de un movimiento unilateral.', ARRAY['Coloca la barra lo bastante baja para que siga librando tus hombros en el punto más bajo de la repetición, métete debajo y apóyala sobre los trapecios altos.','Desengancha la barra y da una zancada larga hacia delante con un pie, dejando el pie trasero apoyado en el suelo con el talón elevado.','Comprueba que la tibia delantera quedará vertical al bajar; ajusta la longitud de la zancada antes de empezar a cargarla.','Baja en línea recta flexionando ambas rodillas hasta que la rodilla trasera quede justo por encima del suelo y el muslo delantero cerca de la paralela.','Empuja con el talón delantero para volver al inicio sin mover los pies, y repite las repeticiones deseadas antes de cambiar de lado.'], ARRAY['Fija primero la longitud de la zancada sin carga. Una vez que la barra está sobre tu espalda, la trayectoria fija no te dejará avanzar para corregir una posición demasiado corta.','Baja recto, no hacia delante. La barra solo puede desplazarse en vertical, así que empujar la cadera hacia delante únicamente adelanta la rodilla más allá de los dedos.','Haz el mismo número de repeticiones por lado y empieza por la pierna más débil, ya que una sentadilla en tijera guiada oculta una diferencia entre lados que una barra libre dejaría en evidencia.'], '/exercises/smith-machine-split-squat-main.webp', '/exercises/smith-machine-split-squat-main.webp'),
('Sentadilla en Máquina Smith', 'smith-machine-squat', 'glutes', ARRAY['back','hamstrings'], 'smith_machine', 'beginner', 'compound', 'Una sentadilla guiada en máquina Smith con la barra sobre los trapecios, que trabaja cuádriceps y glúteos con trayectoria fija.', ARRAY['Ajusta la barra de la máquina Smith a la altura de los hombros y colócate debajo de ella.','Apoya la barra sobre tus trapecios superiores y desrackéala.','Párate con los pies al ancho de los hombros, ligeramente por delante de la barra.','Desciende hasta que los muslos queden paralelos al suelo.','Empuja a través de los talones para volver a la posición de pie.','Repite el número de repeticiones deseado.'], ARRAY['Coloca los pies ligeramente por delante de la barra.','Baja hasta que los muslos queden paralelos al suelo.','Empuja con los talones para volver a subir.'], '/exercises/smith-machine-squat-main.webp', '/exercises/smith-machine-squat-main.webp'),
  ('Remo al Mentón en Máquina Smith', 'smith-machine-upright-row', 'shoulders', ARRAY['biceps'], 'smith_machine', 'beginner', 'compound', 'Un remo al mentón en máquina Smith, tirando de la barra guiada por delante del torso con los codos al frente, para trabajar los deltoides laterales y el trapecio superior.', ARRAY['Coloca la barra a la altura de las caderas, toma un agarre prono algo más ancho que los hombros y sitúate cerca de ella con los brazos estirados.','Desengancha la barra y ponte erguido con los hombros atrás y el core activado.','Tira de la barra en línea recta por delante del cuerpo, guiando con los codos y manteniendo la barra cerca.','Detente cuando la barra llegue al pecho inferior y los codos queden a la altura de los hombros, y haz una pausa breve.','Baja la barra de forma controlada hasta estirar los brazos de nuevo y repite las repeticiones deseadas.'], ARRAY['Detente a la altura del pecho. Tirar de la barra hasta la clavícula rota el hombro hacia la posición que provoca el pinzamiento por el que este ejercicio es conocido.','Guía con los codos, no con las manos. Si las muñecas suben primero, toman el relevo los bíceps y los deltoides laterales apenas trabajan.','Abre el agarre si el movimiento pincha. Un agarre estrecho fuerza más rotación interna, y la trayectoria fija de la barra no te deja ninguna alternativa.'], '/exercises/smith-machine-upright-row-main.webp', '/exercises/smith-machine-upright-row-main.webp'),
  ('Arrancada', 'snatch', 'glutes', ARRAY['back','hamstrings','shoulders'], 'barbell', 'intermediate', 'compound', 'Un levantamiento olímpico que tira de la barra desde el suelo hasta encima de la cabeza en un solo movimiento, recibida en una sentadilla por encima de la cabeza.', ARRAY['Párate con los pies al ancho de las caderas y agarra la barra con un agarre ancho.','Inclínate hacia abajo manteniendo la espalda plana y el pecho arriba.','Extiende explosivamente caderas, rodillas y tobillos para impulsar la barra hacia arriba.','Colócate debajo de la barra en una sentadilla por encima de la cabeza.','Levántate con la barra bloqueada por encima de la cabeza.','Devuelve la barra al suelo y repite.'], ARRAY['Mantén la barra cerca del cuerpo mientras sube.','Extiende completamente las caderas antes de tirar por debajo de la barra.','Bloquea los brazos y estabiliza antes de ponerte de pie.'], '/exercises/snatch-main.webp', '/exercises/snatch-main.webp'),
  ('Postura de la Esfinge', 'sphinx-pose', 'back', ARRAY['core','chest'], NULL, 'beginner', 'mobility', 'Una extensión suave boca abajo sobre los antebrazos: los codos quedan bajo los hombros y el pecho se eleva, de modo que la zona lumbar se extiende sin esfuerzo de los brazos.', ARRAY['Túmbate boca abajo y apoya los antebrazos en el suelo con los codos justo bajo los hombros.','Presiona los antebrazos y el empeine contra el suelo y eleva el pecho.','Aleja los hombros de las orejas y alarga la nuca.','Mantén la posición durante el tiempo indicado, respirando hacia la parte frontal del pecho.','Baja el pecho al suelo y descansa.'], ARRAY['Desliza los codos algo hacia delante para una extensión más suave, o hacia atrás para una más profunda.','Mantén los glúteos blandos para que la zona lumbar no se apriete.','Quédate donde se siente estiramiento, no pinzamiento.'], '/exercises/sphinx-pose-main.webp', '/exercises/sphinx-pose-main.webp'),
  ('Curl Araña', 'spider-curl', 'biceps', NULL, 'dumbbell', 'intermediate', 'isolation', 'Un curl tumbado boca abajo en banco inclinado con los brazos colgando verticales, aislando el bíceps en un rango estricto.', ARRAY['Túmbate boca abajo en un banco inclinado con los brazos colgando rectos hacia abajo.','Sostén una mancuerna en cada mano con agarre supino.','Mantén los brazos superiores verticales mientras curleas los pesos hacia arriba.','Aprieta fuerte los bíceps en la parte superior.','Baja las mancuernas de forma controlada hasta la extensión completa.','Repite el número de repeticiones deseado.'], ARRAY['Mantén el pecho pegado al respaldo durante toda la serie.','Aprieta arriba sin dejar que los codos se desplacen hacia atrás.','Usa el rango completo: el estiramiento abajo es la mitad del beneficio.'], '/exercises/spider-curl-main.webp', '/exercises/spider-curl-main.webp'),
  ('Jerk con Tijera', 'split-jerk', 'shoulders', ARRAY['glutes','traps','triceps'], 'barbell', 'intermediate', 'compound', 'Un levantamiento por encima de la cabeza que impulsa la barra con una flexión de piernas y la recibe en posición de tijera con los brazos bloqueados.', ARRAY['Sostén la barra en el rack frontal con los codos altos.','Baja recto doblando ligeramente las rodillas.','Impulsa la barra por encima de la cabeza explosivamente con piernas y brazos.','Abre los pies hacia adelante y hacia atrás mientras la barra se bloquea.','Levántate juntando los pies bajo la barra.','Baja la barra y repite.'], ARRAY['Flexiona recto hacia abajo en lugar de inclinar el torso hacia delante.','Separa los pies adelante y atrás mientras la barra se bloquea.','Al recuperarte, lleva primero el pie delantero hacia atrás.'], '/exercises/split-jerk-main.webp', '/exercises/split-jerk-main.webp'),
  ('Sentadilla en Tijera', 'split-squat', 'glutes', ARRAY['hamstrings'], NULL, 'intermediate', 'compound', 'Una zancada estática bajando en línea recta con las piernas en tijera, desarrollando fuerza unilateral sin dar el paso.', ARRAY['Párate en posición de tijera con un pie adelante y otro atrás.','Mantén el torso erguido y el core contraído.','Baja las caderas rectas hacia abajo doblando ambas rodillas.','Detente cuando la rodilla trasera esté justo por encima del suelo.','Empuja a través del talón delantero para volver al inicio.','Completa las repeticiones de un lado y luego cambia.'], ARRAY['Baja en línea recta en lugar de lanzarte hacia delante.','Mantén la mayor parte del peso sobre el pie delantero.','Mantén el talón delantero apoyado durante toda la repetición.'], '/exercises/split-squat-main.webp', '/exercises/split-squat-main.webp'),
  ('Press Spoto', 'spoto-press', 'chest', ARRAY['shoulders','triceps'], 'barbell', 'intermediate', 'compound', 'Un press de banca con barra que incluye una pausa con la barra suspendida sobre el pecho, eliminando el rebote.', ARRAY['Túmbate en un banco plano y agarra la barra ligeramente más ancha que los hombros.','Desrackea la barra y sostenla sobre el pecho con los brazos extendidos.','Baja la barra hasta que quede a un centímetro por encima del pecho.','Mantén esa posición un segundo completo sin tocar el pecho.','Empuja la barra hacia arriba hasta que los brazos estén extendidos.','Repite el número de repeticiones deseado.'], ARRAY['Detén la barra a un par de centímetros del pecho.','Mantén la pausa un segundo completo sin tocar el pecho.','Conserva los omóplatos retraídos durante todo el recorrido.'], '/exercises/spoto-press-main.webp', '/exercises/spoto-press-main.webp'),
  ('Sentadilla Trasera con Barra', 'squat', 'glutes', ARRAY['back','hamstrings'], 'barbell', 'intermediate', 'compound', 'Un movimiento compuesto de tren inferior que trabaja cuádriceps, glúteos e isquiotibiales.', ARRAY['Coloca la barra sobre tus trapecios superiores.','Desrackea y da un paso atrás, con los pies al ancho de los hombros.','Contrae el core y haz la sentadilla hasta que los muslos queden paralelos.','Empuja a través de los talones para volver a la posición de pie.','Repite.'], ARRAY['Mantén el pecho arriba durante todo el movimiento.','Empuja las rodillas hacia afuera en línea con los dedos de los pies.'], '/exercises/squat-main.webp', '/exercises/squat-main.webp'),
  ('Puente de Cadera con Balón de Estabilidad', 'stability-ball-hip-bridge', 'glutes', ARRAY['hamstrings','core'], 'bodyweight', 'beginner', 'isolation', 'Un puente de glúteos con los pies sobre un balón de estabilidad, que añade demanda antirotación y de equilibrio al patrón básico del puente.', ARRAY['Túmbate boca arriba en el suelo y coloca ambos pies sobre un balón de estabilidad.','Los brazos descansan a los lados en el suelo para equilibrarte.','Aprieta los glúteos y presiona los talones contra el balón para elevar las caderas.','Termina con una línea recta desde los hombros hasta las rodillas.','Baja las caderas de forma controlada sin que el balón ruede.','Repite el número de repeticiones recomendado.'], ARRAY['El balón intentará desplazarse: mantén los pies presionados directamente hacia abajo.','Sin hiperextensión en la parte superior; detente cuando el cuerpo esté en línea.'], '/exercises/stability-ball-hip-bridge-main.webp', '/exercises/stability-ball-hip-bridge-main.webp'),
  ('Encogimiento de Rodillas con Balón de Estabilidad', 'stability-ball-knee-tuck', 'core', ARRAY['shoulders'], 'bodyweight', 'intermediate', 'compound', 'Un encogimiento de rodillas en posición de plancha con los pies sobre un balón de estabilidad, rodando el balón hacia las caderas para trabajar el abdomen dinámicamente.', ARRAY['Comienza en plancha alta con las espinillas o el dorso de los pies sobre un balón de estabilidad.','Las manos están bajo los hombros y el cuerpo en línea recta.','Contrae el core y lleva el balón hacia el pecho encogiendo las rodillas.','Rueda de vuelta hacia afuera extendiendo completamente las piernas a la posición de plancha.','Repite el número de repeticiones recomendado.'], ARRAY['Las caderas no se elevan; mantén el tronco nivelado durante todo el encogimiento.','Los hombros permanecen sobre las muñecas: no dejes que se desplacen hacia adelante.'], '/exercises/stability-ball-knee-tuck-main.webp', '/exercises/stability-ball-knee-tuck-main.webp'),
  ('Push-Up con Balón de Estabilidad', 'stability-ball-push-up', 'chest', ARRAY['shoulders','core','triceps'], 'bodyweight', 'intermediate', 'compound', 'Un push-up realizado con los pies sobre un balón de estabilidad, que añade una fuerte demanda antirotación al push-up estándar.', ARRAY['Arrodíllate frente a un balón de estabilidad y coloca las espinillas o los pies encima.','Apoya las manos en el suelo bajo los hombros en posición de plancha alta.','Contrae fuerte el core: el balón querrá rodar hacia los lados.','Baja el pecho al suelo doblando los codos.','Vuelve a empujar hasta la posición inicial sin dejar que el balón se tambalee.','Repite el número de repeticiones recomendado.'], ARRAY['Comienza con las espinillas sobre el balón; solo con los pies es mucho más difícil.','Si el balón se desplaza de lado a lado, falta contracción del core: reduce la velocidad.'], '/exercises/stability-ball-push-up-main.webp', '/exercises/stability-ball-push-up-main.webp'),
  ('Flexión sobre pelota de estabilidad (manos en la pelota)', 'stability-ball-push-up-hands-on-ball', 'chest', ARRAY['shoulders','core','triceps'], 'bodyweight', 'intermediate', 'compound', 'Una flexión inclinada realizada con ambas manos sobre una pelota de estabilidad y los pies en el suelo. La superficie inestable exige más al pecho, los hombros y los tríceps, mientras el core mantiene el cuerpo rígido.', ARRAY['Coloca ambas manos sobre una pelota de estabilidad y camina con los pies hacia atrás hasta una plancha con los brazos extendidos, el cuerpo en línea recta de la cabeza a los talones.','Activa el core y mantén la pelota firme bajo las manos.','Flexiona los codos para bajar el pecho hacia la pelota de forma controlada.','Empuja de nuevo hasta la extensión completa de los brazos sin dejar que la pelota ruede.','Repite las repeticiones deseadas.'], ARRAY['Mantén el cuerpo en una línea recta y rígida: no dejes que las caderas se hundan ni se eleven.','Muévete lento y con control; la inestabilidad de la pelota es lo que hace efectivo el ejercicio, así que resístela en lugar de combatirla con rapidez.','Coloca las manos algo más anchas que los hombros sobre la pelota y mantén los codos a unos 45 grados.'], '/exercises/stability-ball-push-up-hands-on-ball-main.webp', '/exercises/stability-ball-push-up-hands-on-ball-main.webp'),
  ('Sentadilla en Pared con Pelota', 'stability-ball-wall-squat', 'glutes', ARRAY['hamstrings'], 'bodyweight', 'beginner', 'compound', 'Una sentadilla con peso corporal apoyando una pelota suiza entre la zona lumbar y la pared, que guía la columna.', ARRAY['Coloca una pelota suiza entre tu zona lumbar y una pared.','Adelanta los pies unos 30 cm, un poco más anchos que los hombros.','Baja en sentadilla mientras la pelota rueda por la espalda.','Detente cuando los muslos queden paralelos al suelo.','Empuja con los talones para volver a subir.'], ARRAY['Carga el peso en talones y medio del pie.','No dejes que las rodillas pasen las puntas de los pies.','La pelota debe rodar suavemente — no te separes de ella.'], '/exercises/stability-ball-wall-squat-main.webp', '/exercises/stability-ball-wall-squat-main.webp'),
  ('Escaladora de Escaleras', 'stair-climber', 'glutes', ARRAY['calves','hamstrings'], 'machine', 'beginner', 'cardio', 'Un ejercicio de máquina cardiovascular que sube escalón tras escalón por una escalera giratoria, cargando glúteos y cuádriceps de forma continua y sin impacto de aterrizaje.', ARRAY['Súbete al escalón inferior con la máquina en su ajuste más lento y sujeta los raíles con suavidad para equilibrarte.','Sube de escalón en escalón apoyando el pie entero en cada uno, no solo la punta.','Mantente erguido con el pecho abierto y la cadera bajo los hombros, sin encorvarte sobre la consola.','Empuja el escalón hacia abajo con el talón del pie adelantado y deja que el glúteo de esa pierna haga el trabajo.','Ajusta el ritmo para poder sostener la postura y sigue subiendo durante el tiempo o el número de pisos deseados.'], ARRAY['No te apoyes en los raíles ni cuelgues los antebrazos sobre ellos — descargar ahí el peso quita trabajo a las piernas y la pantalla deja de significar nada.','Pie entero sobre el escalón, talón incluido. Subir de puntillas traslada toda la sesión a los gemelos y los agota pronto.','Sube escalón a escalón antes de intentar saltártelos; una subida deliberada y erguida vale más que un trote rápido en la parte baja de la escalera.'], '/exercises/stair-climber-main.webp', '/exercises/stair-climber-main.webp'),
  ('Estiramiento de Pantorrilla de Pie', 'standing-calf-stretch', 'calves', NULL, NULL, 'beginner', 'mobility', 'Un estiramiento en paso escalonado que alarga la pantorrilla presionando el talón trasero con la pierna estirada.', ARRAY['Lleva un pie atrás a un paso escalonado.','Mantén la pierna trasera estirada y el talón presionado al suelo.','Flexiona la rodilla delantera e inclina el peso hacia adelante.','Mantén de 20 a 30 segundos, respirando de forma constante.','Cambia de lado y repite.'], ARRAY['Mantén el talón trasero plano y los dedos al frente.','Flexiona un poco la rodilla trasera para trabajar la pantorrilla baja.'], '/exercises/standing-calf-stretch-main.webp', '/exercises/standing-calf-stretch-main.webp'),
  ('Flexión de Pie hacia Adelante', 'standing-forward-fold', 'hamstrings', ARRAY['back','calves'], NULL, 'beginner', 'mobility', 'Un estiramiento de pie que alarga los isquiotibiales y la zona lumbar al inclinar el torso sobre las piernas estiradas.', ARRAY['Párate erguido con los pies al ancho de cadera y las piernas estiradas.','Flexiónate desde las caderas y baja el torso hacia el suelo.','Deja que las manos y la cabeza cuelguen hacia los pies.','Mantén de 20 a 30 segundos, respirando de forma constante.'], ARRAY['Flexiona un poco las rodillas si sientes tensos los isquiotibiales.','Entra en el estiramiento lentamente, nunca rebotes.'], '/exercises/standing-forward-fold-main.webp', '/exercises/standing-forward-fold-main.webp'),
  ('Flexión de Pie a Media Elevación', 'standing-forward-fold-to-half-lift', 'back', ARRAY['glutes'], NULL, 'beginner', 'mobility', 'La articulación conocida como media elevación: desde una flexión de pie el pecho sube hasta dejar la espalda plana y la columna larga, y luego vuelve a plegarse. Enseña la diferencia entre una flexión redondeada y una bisagra con la columna larga.', ARRAY['Ponte de pie con los pies a la anchura de las caderas y pliégate hacia delante desde las caderas.','Apoya las manos en las espinillas, en el suelo o en bloques.','Desliza las manos por las espinillas y eleva el pecho hasta dejar la espalda plana y la columna larga.','Vuelve a plegarte dejando que la cabeza y el cuello se relajen.','Sigue alternando entre ambas posiciones las veces indicadas.'], ARRAY['Deja una ligera flexión en las rodillas para que el movimiento venga de las caderas.','Sube a espalda plana en lugar de mirar hacia arriba; el cuello sigue a la columna.','Aleja los hombros de las orejas en la posición elevada.'], '/exercises/standing-forward-fold-to-half-lift-main.webp', '/exercises/standing-forward-fold-to-half-lift-main.webp')
) as v(name, slug, muscle_slug, secondary_slugs, equipment_slug, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url)
on conflict (slug) do nothing;

insert into public.exercises (name, slug, primary_muscle_group_id, secondary_muscle_group_ids, equipment_id, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url, image_source, image_license)
select v.name, v.slug,
  (select id from public.muscle_groups where slug = v.muscle_slug),
  coalesce((select array_agg(id) from public.muscle_groups where slug = any(v.secondary_slugs)), '{}'),
  (select id from public.equipment where slug = v.equipment_slug),
  v.difficulty::public.exercise_difficulty,
  v.movement_type::public.movement_type,
  v.description, v.instructions, v.tips, v.image_url, v.thumbnail_url,
  'RepDB (repdb.co)', 'Free tier - commercial in-app use with attribution'
from (values
('Estiramiento de Cuádriceps de Pie', 'standing-quad-stretch', 'quads', ARRAY['core'], NULL, 'beginner', 'mobility', 'Un estiramiento de equilibrio de pie que alarga el cuádriceps llevando el talón hacia el glúteo.', ARRAY['Párate sobre una pierna, apoyándote en una pared si lo necesitas.','Flexiona la otra rodilla y agarra ese tobillo por detrás.','Lleva el talón hacia el glúteo, manteniendo las rodillas juntas.','Mantén de 20 a 30 segundos, respirando de forma constante.','Cambia de lado y repite.'], ARRAY['Mete la pelvis hacia adentro para profundizar el estiramiento.','Mantén las rodillas juntas en todo momento.'], '/exercises/standing-quad-stretch-main.webp', '/exercises/standing-quad-stretch-main.webp'),
  ('Flexión Lateral de Pie', 'standing-side-bend', 'core', ARRAY['back','lower_back'], NULL, 'beginner', 'mobility', 'Un estiramiento de pie que alarga los oblicuos y dorsales al estirar los brazos arriba e inclinarse a un lado.', ARRAY['Párate con los pies al ancho de cadera y sube ambos brazos.','Junta las manos y estírate hacia arriba.','Inclínate suavemente a un lado en una curva larga.','Mantén de 20 a 30 segundos, respirando de forma constante.','Cambia de lado y repite.'], ARRAY['Mantén ambos pies fijos y las caderas estables.','Estírate hacia arriba y al lado en vez de solo dejarte caer.'], '/exercises/standing-side-bend-main.webp', '/exercises/standing-side-bend-main.webp'),
  ('Flexión Lateral de Pie Alterna', 'standing-side-bend-flow', 'core', ARRAY['back','lower_back'], NULL, 'beginner', 'mobility', 'Un flujo lateral de pie: los brazos se estiran por encima de la cabeza y el tronco se inclina de lado a lado con un ritmo controlado, alargando el costado sin sostener ninguna posición final.', ARRAY['Ponte de pie con los pies a la anchura de las caderas y estira ambos brazos por encima de la cabeza.','Inclina el tronco hacia un lado manteniendo los pies apoyados y las caderas niveladas.','Vuelve por el centro con las costillas alineadas sobre la pelvis.','Inclínate hacia el otro lado del mismo modo.','Sigue alternando las veces indicadas.'], ARRAY['Inclínate solo lateralmente: si el pecho rota, se convierte en un giro.','Mantén ambos talones apoyados para que el movimiento se quede en el tronco.','Muévete con la respiración en lugar de rebotar al final del recorrido.'], '/exercises/standing-side-bend-flow-main.webp', '/exercises/standing-side-bend-flow-main.webp'),
  ('Split de Pie', 'standing-split', 'glutes', ARRAY['back','quads'], NULL, 'advanced', 'mobility', 'Una flexión de pie con una pierna elevada por detrás: el torso se pliega sobre la pierna de apoyo mientras la pierna libre se eleva hacia el techo.', ARRAY['Desde una flexión hacia delante, apoya ambas manos en el suelo o en bloques junto al pie de apoyo.','Pasa el peso a una pierna y eleva la otra por detrás.','Mantén la pierna de apoyo estirada y las caderas tan niveladas como permita la elevación.','Mantén la posición durante el tiempo indicado, acercando el pecho a la espinilla de apoyo.','Baja el pie elevado y repite del otro lado.'], ARRAY['Nivela primero las caderas y acepta menos altura; abrir la cadera convierte esto en otra postura.','Usa bloques bajo las manos para que la columna pueda mantenerse larga.','Agarra el tobillo de apoyo con una mano solo cuando el equilibrio ya sea estable.'], '/exercises/standing-split-main.webp', '/exercises/standing-split-main.webp'),
  ('Bicicleta Estática', 'stationary-bike', 'quads', ARRAY['calves','glutes','hamstrings'], 'machine', 'beginner', 'cardio', 'Un ejercicio cardiovascular sentado que mueve un volante de inercia mediante un pedaleo continuo, trabajando las piernas sin impacto sobre las articulaciones.', ARRAY['Ajusta la altura del sillín para que la rodilla quede ligeramente flexionada en el punto más bajo del pedaleo, siéntate y apoya la parte anterior de los pies en los pedales.','Sujeta el manillar con un agarre relajado y siéntate erguido, con la espalda neutra y los hombros bajos.','Empuja un pedal hacia abajo y hacia delante mientras el otro sube, manteniendo el esfuerzo en las piernas en lugar de tirar del manillar.','Sigue pedaleando en un círculo suave y regular a una cadencia constante, respirando al ritmo del pedaleo.','Ajusta la resistencia para sostener el esfuerzo que buscas y continúa durante el tiempo o la distancia deseados.'], ARRAY['Ajusta el sillín antes de empezar: demasiado bajo castiga las rodillas y demasiado alto hace que la cadera bascule de lado a lado en cada pedalada.','Empuja con las piernas y mantén el tren superior quieto — agarrarte y tirar del manillar solo añade tensión en el cuello y los hombros.','Sube la resistencia en lugar de girar los pedales sueltos y rápidos; un volante ligero a cadencia alta se siente duro en los pulmones pero aporta poco a las piernas.'], '/exercises/stationary-bike-main.webp', '/exercises/stationary-bike-main.webp'),
  ('Step Ups', 'step-ups', 'glutes', ARRAY['calves','hamstrings'], NULL, 'intermediate', 'compound', 'Una subida a un cajón o banco con una pierna que entrena cuádriceps y glúteos de forma funcional.', ARRAY['Párate frente a una caja o banco resistente.','Coloca un pie completamente sobre la superficie de la caja.','Empuja a través de ese talón para subir el cuerpo a la caja.','Sube el pie de atrás para quedar completamente sobre la caja.','Baja con el mismo pie que subió primero.','Alterna piernas o completa todas las repeticiones de un lado antes de cambiar.'], ARRAY['Apoya todo el pie sobre la superficie del cajón.','Impulsa con el talón de la pierna que sube, no con la de atrás.','Controla el descenso en lugar de dejarte caer.'], '/exercises/step-ups-main.webp', '/exercises/step-ups-main.webp'),
  ('Peso Muerto con Piernas Rígidas', 'stiff-leg-deadlift', 'glutes', ARRAY['back','traps'], 'barbell', 'intermediate', 'compound', 'Una bisagra de cadera con las piernas casi rectas, bajando la barra a lo largo de los muslos para estirar y cargar los isquiotibiales.', ARRAY['Párate con los pies al ancho de las caderas, sosteniendo una barra frente a los muslos.','Mantén las piernas casi rectas con solo una ligera flexión de rodillas.','Inclínate en las caderas y baja la barra a lo largo de las piernas.','Baja hasta donde la flexibilidad de los isquiotibiales lo permita con la espalda plana.','Empuja a través de los talones para volver a la posición erguida.','Repite el número de repeticiones deseado.'], ARRAY['Lleva las caderas hacia atrás y mantén la barra cerca de las piernas.','Baja solo hasta donde te permita mantener la espalda plana.','Siente la carga en los isquiotibiales al estirar y luego empuja las caderas hacia delante para subir.'], '/exercises/stiff-leg-deadlift-main.webp', '/exercises/stiff-leg-deadlift-main.webp'),
  ('Jalón con Brazos Rectos', 'straight-arm-pulldown', 'back', ARRAY['shoulders','triceps'], 'cable', 'intermediate', 'isolation', 'Un ejercicio de aislamiento para los dorsales usando cable con los brazos rectos.', ARRAY['Párate frente a una máquina de cable con una barra recta enganchada a la polea alta.','Con los brazos casi rectos, empuja la barra hacia abajo en un arco hacia los muslos.','Aprieta los dorsales en la parte inferior.','Devuelve la barra lentamente a la posición inicial.','Repite.'], ARRAY['Mantén los brazos casi rectos durante todo el movimiento.','Lleva la barra hacia los muslos describiendo un arco.','Aprieta los dorsales en la parte baja del recorrido.'], '/exercises/straight-arm-pulldown-main.webp', '/exercises/straight-arm-pulldown-main.webp'),
  ('Elevación frontal en polea con barra recta', 'straight-bar-cable-front-raise', 'shoulders', ARRAY['chest'], 'cable', 'intermediate', 'isolation', 'Una elevación frontal en la polea baja sujetando una barra recta con ambas manos. A diferencia de la elevación frontal en polea a un brazo, los dos brazos mueven la misma barra y el cable mantiene la tensión sobre el deltoides anterior en todo el recorrido.', ARRAY['Engancha una barra recta a la polea baja y colócate de espaldas a la máquina, con el cable pasando por delante de las piernas.','Sujeta la barra en pronación con las manos a la anchura de los hombros y los brazos colgando estirados delante de los muslos.','Mantén los codos casi extendidos y el core firme para que el torso no se incline hacia atrás.','Eleva la barra hacia delante en un arco suave hasta la altura de los hombros.','Bájala de forma controlada hasta los muslos y repite las repeticiones deseadas.'], ARRAY['Usa poco peso: impulsar la barra con las piernas o inclinarte hacia atrás quita el trabajo al deltoides anterior.','Detente a la altura de los hombros; subir más traslada la carga al trapecio.','Mantén las muñecas neutras en lugar de dejar que se doblen bajo la barra.'], '/exercises/straight-bar-cable-front-raise-main.webp', '/exercises/straight-bar-cable-front-raise-main.webp'),
  ('Fondos en Barra Recta', 'straight-bar-dips', 'chest', ARRAY['triceps'], 'bodyweight', 'intermediate', 'compound', 'Una variante de fondos realizada colgando de una barra recta de dominadas en lugar de barras paralelas de fondos, empujando el cuerpo hacia arriba en un rango de movimiento reducido.', ARRAY['Agarra una barra recta por encima de la cabeza con ambas manos, colgando con los brazos extendidos y los pies fuera del suelo.','Manteniendo el cuerpo recto, empuja hacia abajo a través de la barra para elevar los hombros y el pecho.','Haz una breve pausa en la parte superior del movimiento.','Baja con control de vuelta a la posición colgante.','Repite el número deseado de repeticiones.'], ARRAY['Mantén el movimiento controlado -- es un rango de movimiento pequeño comparado con los fondos en barras paralelas.','Contrae el core para evitar que el cuerpo se balancee.','Esta posición de muñeca y hombro es más exigente que los fondos estándar -- aumenta el volumen gradualmente.'], '/exercises/straight-bar-dips-main.webp', '/exercises/straight-bar-dips-main.webp'),
  ('Curl Estricto', 'strict-curl', 'biceps', ARRAY['forearms'], 'dumbbell', 'intermediate', 'isolation', 'Un curl de pie realizado sin ningún impulso corporal — el torso permanece quieto y los codos se mantienen fijos, de modo que el bíceps hace todo el trabajo.', ARRAY['Ponte de pie con una mancuerna en cada mano, los brazos a los costados y las palmas hacia adelante.','Fija los codos a los costados y contrae el core para que el torso no pueda balancearse.','Flexiona ambas mancuernas hacia arriba moviendo solo los codos.','Bájalas de forma controlada hasta que los brazos queden rectos.','Repite las repeticiones deseadas.'], ARRAY['Ponerte de pie con la espalda contra una pared o poste es una buena autoevaluación — si los hombros o las caderas se separan de ella, estás usando impulso.','Evita que los codos se adelanten; los brazos superiores deben permanecer verticales durante todo el movimiento.','Baja más lento de lo que subes — la versión estricta vive en el descenso.'], '/exercises/strict-curl-main.webp', '/exercises/strict-curl-main.webp'),
  ('Paseo del Maletín', 'suitcase-carry', 'forearms', ARRAY['back','glutes','quads','traps'], 'kettlebell', 'beginner', 'compound', 'Un paseo cargado con el peso en una sola mano, de modo que el tronco tiene que resistir la inclinación lateral durante todo el recorrido — la versión unilateral del paseo del granjero.', ARRAY['Colócate junto a una sola kettlebell o mancuerna, con los pies a la anchura de las caderas.','Flexiona por la cadera, agarra el asa con una mano e incorpórate con el peso colgando a un costado.','Lleva ese hombro abajo y atrás, y aprieta el tronco como si fueran a empujarte de lado.','Camina hacia delante con zancadas normales y regulares, manteniendo el torso erguido y cuadrado en lugar de inclinarte para escapar del peso.','Mantén el brazo libre relajado junto al cuerpo, sin separarlo como contrapeso.','Carga la distancia o el tiempo deseados, deja el peso en el suelo de forma controlada y repite por el otro lado.'], ARRAY['Haz la misma distancia por los dos lados. Todo el valor está en la asimetría, y solo funciona si cargas ambas direcciones por igual.','Si te inclinas hacia el peso o levantas la cadera contraria, el peso es excesivo: esto es ante todo un ejercicio de postura.','El agarre suele fallar antes que el tronco. Es un efecto de entrenamiento legítimo, pero si siempre es el límite, usa correas en las series pesadas.'], '/exercises/suitcase-carry-main.webp', '/exercises/suitcase-carry-main.webp'),
  ('Peso Muerto Sumo', 'sumo-deadlift', 'glutes', ARRAY['back','hamstrings'], 'barbell', 'intermediate', 'compound', 'Una variante del peso muerto con postura amplia que desplaza el énfasis hacia glúteos, cuádriceps e interior de los muslos.', ARRAY['Párate con los pies más anchos que el ancho de los hombros, con los pies apuntando hacia afuera.','Agarra la barra entre las piernas.','Contrae el core y empuja a través de los talones para levantarte.','Baja de forma controlada.','Repite.'], ARRAY['Mantén la barra pegada al cuerpo.','Empuja las rodillas hacia afuera en línea con los dedos de los pies.'], '/exercises/sumo-deadlift-main.webp', '/exercises/sumo-deadlift-main.webp'),
  ('Sentadilla Sumo', 'sumo-squat', 'glutes', ARRAY['back','hamstrings'], 'barbell', 'intermediate', 'compound', 'Una sentadilla con barra y postura amplia con las puntas hacia afuera, que enfatiza glúteos y cara interna de los muslos.', ARRAY['Párate con los pies más anchos que el ancho de los hombros y los pies apuntando hacia afuera.','Sostén una barra sobre la parte superior de la espalda.','Contrae el core y mantén el pecho arriba.','Dobla caderas y rodillas para bajar a una sentadilla profunda.','Empuja a través de los talones para volver a la posición de pie.','Repite el número de repeticiones deseado.'], ARRAY['Abre las puntas de los pies y empuja las rodillas hacia afuera.','Mantén el pecho alto y el core firme.','Baja en profundidad flexionando caderas y rodillas a la vez.'], '/exercises/sumo-squat-main.webp', '/exercises/sumo-squat-main.webp'),
  ('Superman', 'superman', 'back', ARRAY['hamstrings'], NULL, 'beginner', 'isolation', 'Un ejercicio de peso corporal para la zona lumbar realizado en prono, levantando brazos y piernas simultáneamente.', ARRAY['Túmbate boca abajo con los brazos extendidos por encima de la cabeza.','Levanta simultáneamente los brazos, el pecho y las piernas del suelo.','Mantén brevemente la posición superior.','Baja de forma controlada.','Repite.'], ARRAY['Aprieta los glúteos al levantar.','Evita los movimientos bruscos.'], '/exercises/superman-main.webp', '/exercises/superman-main.webp'),
  ('Giro Espinal Tumbado', 'supine-spinal-twist', 'back', ARRAY['glutes'], NULL, 'beginner', 'mobility', 'Un giro tumbado que estira la zona lumbar, los glúteos y los oblicuos al cruzar una rodilla flexionada sobre el cuerpo.', ARRAY['Acuéstate boca arriba y lleva una rodilla al pecho.','Guía esa rodilla cruzando el cuerpo hacia el suelo.','Extiende los brazos y gira la cabeza hacia el lado contrario.','Mantén de 20 a 30 segundos, respirando de forma constante.','Cambia de lado y repite.'], ARRAY['Mantén ambos hombros en el suelo.','Relájate y sigue respirando todo el tiempo.'], '/exercises/supine-spinal-twist-main.webp', '/exercises/supine-spinal-twist-main.webp'),
  ('Limpiaparabrisas Tumbado', 'supine-windshield-wipers', 'core', NULL, NULL, 'intermediate', 'compound', 'Un ejercicio de rotación tumbado: con las rodillas flexionadas o las piernas elevadas, ambas piernas oscilan de lado a lado como limpiaparabrisas mientras los hombros permanecen pegados al suelo.', ARRAY['Túmbate boca arriba con los brazos abiertos a los lados y las rodillas flexionadas sobre las caderas.','Aprieta el tronco para que la zona lumbar no se despegue del suelo.','Baja ambas piernas juntas hacia un lado mientras los hombros sigan apoyados.','Devuélvelas por el centro y bájalas hacia el otro lado.','Sigue alternando las veces indicadas.'], ARRAY['Ambos hombros se quedan en el suelo; son ellos los que definen el recorrido, no las piernas.','Mantén las rodillas juntas para que la pelvis se mueva como una unidad.','Estira las piernas para una versión mucho más difícil cuando tengas el control.'], '/exercises/supine-windshield-wipers-main.webp', '/exercises/supine-windshield-wipers-main.webp'),
  ('Vela con Apoyo', 'supported-shoulderstand', 'back', ARRAY['glutes','traps'], NULL, 'intermediate', 'compound', 'Una inversión apoyada en los hombros y los brazos, con las manos sosteniendo la espalda y el cuerpo alineado en vertical sobre los hombros.', ARRAY['Túmbate boca arriba, idealmente con una manta doblada bajo los hombros y la cabeza fuera de ella.','Eleva las piernas por encima de la cabeza y sostén la zona lumbar con ambas manos, los codos a la anchura de los hombros.','Camina las manos por la espalda y alinea las caderas sobre los hombros hasta que el cuerpo quede vertical.','Mantén la posición durante el tiempo indicado, con la cabeza y el cuello completamente quietos.','Baja las piernas por encima de la cabeza y desciende despacio con las manos sosteniendo la espalda.'], ARRAY['El peso va en los hombros y los brazos, nunca en el cuello.','No gires la cabeza mientras estás invertido.','Construye la postura con piernas en la pared y el arado antes de sostenerla mucho tiempo.'], '/exercises/supported-shoulderstand-main.webp', '/exercises/supported-shoulderstand-main.webp'),
('Press Svend', 'svend-press', 'chest', ARRAY['shoulders','triceps'], 'barbell', 'beginner', 'isolation', 'Un press con apretón de disco que carga los pectorales a través de la aducción isométrica mientras se extiende el peso alejándolo del pecho.', ARRAY['Párate erguido sosteniendo un disco de pesas (o dos apretados juntos) entre las palmas a la altura del pecho.','Aprieta fuerte los discos para generar tensión en los pectorales.','Empuja los discos recto hacia adelante hasta que los brazos estén completamente extendidos.','Haz una breve pausa manteniendo el apretón, luego devuelve los discos al pecho.','Repite el número de repeticiones recomendado.'], ARRAY['Cuanto más fuerte aprietes los discos, mayor activación del pecho obtendrás.','Mantén los discos a la altura del esternón durante todo el ejercicio: no dejes que caigan hacia las caderas.'], '/exercises/svend-press-main.webp', '/exercises/svend-press-main.webp'),
  ('Remo en T', 't-bar-row', 'back', ARRAY['biceps','traps'], 'barbell', 'intermediate', 'compound', 'Un remo compuesto con barra en T y torso inclinado, que desarrolla dorsales y romboides con cargas elevadas.', ARRAY['Colócate a horcajadas sobre la barra en T con los pies al ancho de los hombros.','Inclínate en las caderas hasta que el torso quede a unos 45 grados.','Agarra los mangos y mantén la espalda plana.','Tira de la barra hacia el pecho llevando los codos hacia atrás.','Aprieta los omóplatos en la parte superior.','Baja la barra de forma controlada y repite.'], ARRAY['Inclina el torso unos 45 grados manteniendo la espalda plana.','Tira llevando los codos hacia atrás, no solo con los brazos.','Junta los omóplatos en la parte alta del tirón.'], '/exercises/t-bar-row-main.webp', '/exercises/t-bar-row-main.webp'),
  ('Puente Torácico', 'thoracic-bridge', 'back', ARRAY['shoulders','triceps'], NULL, 'intermediate', 'compound', 'Un sostén de movilidad que eleva las caderas desde una posición de mesa y abre el pecho, extendiendo la columna torácica mientras los glúteos y los hombros sostienen el puente.', ARRAY['Siéntate en el suelo con las rodillas flexionadas y las manos detrás, los dedos apuntando hacia atrás.','Empuja con las manos y los pies para elevar las caderas del suelo.','Sigue empujando hasta que el pecho se abra y los brazos queden extendidos.','Deja caer la cabeza hacia atrás y mantén la posición.','Respira de forma constante mientras mantienes el puente.','Baja de nuevo de forma controlada.'], ARRAY['Eleva bien las caderas y aprieta los glúteos para proteger la zona lumbar.','Mantén los pies planos y el peso repartido entre manos y pies.'], '/exercises/thoracic-bridge-main.webp', '/exercises/thoracic-bridge-main.webp'),
  ('Enhebrar la Aguja', 'thread-the-needle', 'shoulders', ARRAY['back','core'], NULL, 'beginner', 'mobility', 'Una rotación de rodillas: un brazo se desliza por debajo del cuerpo y el hombro y el lateral de la cabeza descansan en el suelo, rotando la columna torácica de forma pasiva.', ARRAY['Comienza a cuatro apoyos con las manos bajo los hombros y las rodillas bajo las caderas.','Desliza un brazo por debajo del cuerpo con la palma hacia arriba hasta que el hombro y el lateral de la cabeza apoyen en la esterilla.','Mantén las caderas sobre las rodillas y camina la mano de arriba hacia delante o llévala a la espalda.','Mantén la torsión durante el tiempo indicado, respirando hacia la espalda alta.','Presiona la mano de arriba contra el suelo para subir y repite del otro lado.'], ARRAY['Mantén las caderas altas sobre las rodillas; si bajan, la rotación se convierte en una inclinación lateral.','Apoya la cabeza en un bloque si el hombro no llega cómodamente al suelo.','Deja que el hombro se asiente con la respiración en lugar de forzar la torsión.'], '/exercises/thread-the-needle-main.webp', '/exercises/thread-the-needle-main.webp'),
  ('Enhebrar la Aguja Dinámico', 'thread-the-needle-flow', 'core', ARRAY['back','shoulders'], NULL, 'beginner', 'mobility', 'La versión en movimiento de enhebrar la aguja: desde cuatro apoyos el brazo pasa por debajo del cuerpo y después se abre hacia el techo, rotando la columna torácica por todo su recorrido.', ARRAY['Comienza a cuatro apoyos con las manos bajo los hombros y las rodillas bajo las caderas.','Desliza un brazo por debajo del cuerpo hasta que el hombro se acerque a la esterilla.','Invierte el movimiento y abre ese brazo hacia el techo, siguiendo la mano con la mirada.','Vuelve por el centro y repite las veces indicadas.','Cambia de lado y repite.'], ARRAY['Mantén las caderas sobre las rodillas para que la rotación se quede en la espalda alta.','Trabaja a un ritmo uniforme en lugar de abrir el brazo de golpe.','Deja que la cabeza siga a la mano en lugar de liderar el movimiento.'], '/exercises/thread-the-needle-flow-main.webp', '/exercises/thread-the-needle-flow-main.webp'),
  ('Perro de Tres Patas', 'three-legged-dog', 'shoulders', ARRAY['hamstrings','traps'], NULL, 'intermediate', 'compound', 'El perro boca abajo con una pierna elevada: los hombros asumen más carga mientras la pierna elevada se alinea con la columna y las caderas se mantienen cuadradas.', ARRAY['Colócate en perro boca abajo con las manos a la anchura de los hombros y las caderas altas.','Presiona ambas manos por igual contra el suelo y desplaza el peso ligeramente hacia delante.','Eleva una pierna por detrás hasta alinearla con la columna, con ambas caderas niveladas.','Mantén la posición durante el tiempo indicado, con el talón de apoyo bajando hacia el suelo.','Baja la pierna y repite del otro lado.'], ARRAY['Evita que la cadera elevada se abra; una pelvis cuadrada importa más que la altura.','Presiona la base del índice contra el suelo para que las muñecas queden cómodas.','Flexiona ligeramente la rodilla de apoyo si el isquiotibial limita la forma.'], '/exercises/three-legged-dog-main.webp', '/exercises/three-legged-dog-main.webp'),
  ('Thruster', 'thruster', 'shoulders', ARRAY['glutes','traps','triceps'], 'barbell', 'intermediate', 'compound', 'Un movimiento de cuerpo completo con barra que combina una sentadilla frontal con un press por encima de la cabeza en un solo impulso fluido.', ARRAY['Sostén una barra en posición de rack frontal con los codos altos.','Párate con los pies al ancho de los hombros.','Baja en sentadilla hasta paralelo manteniendo el torso erguido.','Impúlsate saliendo de la sentadilla y empuja la barra por encima de la cabeza en un solo movimiento.','Bloquea los brazos en la parte superior con la barra sobre la cabeza.','Baja la barra al rack frontal y repite.'], ARRAY['Aprovecha el impulso de la sentadilla para lanzar el press.','Mantén los codos altos para que la barra descanse en los hombros, no en las muñecas.','Termina cada repetición con la barra bloqueada sobre las orejas.'], '/exercises/thruster-main.webp', '/exercises/thruster-main.webp'),
  ('Toes to Bar', 'toes-to-bar', 'core', ARRAY['forearms','back'], 'bodyweight', 'intermediate', 'compound', 'Un ejercicio avanzado de core colgado de una barra que requiere fuerza de flexión de cadera y activación del dorsal para llevar los pies hasta la barra.', ARRAY['Cuélgate de una barra con agarre prono y los brazos completamente extendidos, cuerpo quieto.','Activa los dorsales y el core para evitar balanceos.','Eleva las piernas con rodillas rectas llevando los pies hacia la barra.','Toca la barra con los pies, luego baja las piernas con control.','Repite el número de repeticiones deseado.'], ARRAY['Inicia el movimiento desde el core, no con impulso de patada.','Exhala con fuerza al elevar las piernas para aumentar la presión intraabdominal.','Si no puedes alcanzar la barra, practica las elevaciones de piernas colgado como progresión.'], '/exercises/toes-to-bar-main.webp', '/exercises/toes-to-bar-main.webp'),
  ('Carrera en Cinta', 'treadmill-running', 'calves', ARRAY['glutes','hamstrings','core'], 'machine', 'beginner', 'cardio', 'Una carrera realizada sobre una cinta motorizada, que permite sostener un ritmo y una distancia bajo techo controlando la superficie y la pendiente.', ARRAY['Súbete a la cinta con un pie sobre cada raíl lateral, arranca la banda a velocidad de caminata y pisa cuando ya esté en movimiento.','Sube progresivamente hasta tu ritmo de carrera, apoyando el pie bajo la cadera en lugar de estirar la zancada hacia delante.','Corre erguido con los hombros relajados, los codos flexionados unos noventa grados y los brazos balanceándose adelante y atrás, no cruzando el cuerpo.','Mira al frente y mantente en el centro de la banda en lugar de dejarte llevar hacia el rodillo trasero.','Sostén el ritmo durante el tiempo o la distancia deseados, luego baja la velocidad y camina unos minutos antes de bajarte.'], ARRAY['Engancha la llave de seguridad a la cinturilla — es lo único que detiene la banda si pierdes el pie.','No te agarres a los pasamanos mientras corres. Apoyarte en ellos acorta la zancada, tuerce la postura y oculta cuánto estás trabajando de verdad.','Una pendiente del uno o dos por ciento acerca la carrera en cinta a la carrera al aire libre, donde además hay que vencer la resistencia del aire.'], '/exercises/treadmill-running-main.webp', '/exercises/treadmill-running-main.webp'),
  ('Postura del Árbol', 'tree-pose', 'glutes', ARRAY['back','calves'], NULL, 'intermediate', 'compound', 'Un equilibrio de pie sobre una pierna con la planta del pie libre apoyada en la pantorrilla o el muslo interno y las caderas niveladas.', ARRAY['Ponte de pie y pasa el peso a un pie.','Apoya la planta del otro pie en la cara interna de la pantorrilla o del muslo, evitando la rodilla.','Presiona el pie y la pierna entre sí y nivela las caderas.','Lleva las manos al pecho o por encima de la cabeza y mantén durante el tiempo indicado.','Baja el pie y repite del otro lado.'], ARRAY['No apoyes nunca el pie contra el lateral de la rodilla; solo por encima o por debajo.','Fija la mirada en un punto quieto para estabilizar el equilibrio.','Mantén la pelvis mirando al frente en lugar de dejar que la rodilla elevada la abra.'], '/exercises/tree-pose-main.webp', '/exercises/tree-pose-main.webp'),
  ('Postura del Triángulo', 'triangle-pose', 'hamstrings', ARRAY['adductors','glutes'], NULL, 'intermediate', 'mobility', 'Una postura de base amplia con ambas piernas estiradas y el torso inclinándose lateralmente sobre la pierna delantera, que alarga el isquiotibial y todo el costado.', ARRAY['Sepárate en una base amplia con el pie delantero girado hacia fuera y el trasero algo hacia dentro.','Mantén ambas piernas estiradas y estira la mano delantera hacia delante mientras las caderas van atrás.','Inclínate lateralmente y lleva la mano de abajo a la espinilla, un bloque o el suelo, con el brazo de arriba hacia el techo.','Mantén la posición durante el tiempo indicado, girando el pecho hacia el techo.','Empuja con los pies para subir y repite del otro lado.'], ARRAY['Alárgate primero sobre la pierna delantera antes de inclinarte; bajar demasiado pronto derrumba la postura.','Usa un bloque bajo la mano de abajo en lugar de arrastrar el pecho hacia el suelo.','Mantén ambas piernas estiradas y las rótulas activas.'], '/exercises/triangle-pose-main.webp', '/exercises/triangle-pose-main.webp'),
  ('Patada de Tríceps con Mancuerna', 'tricep-kickback', 'triceps', NULL, 'dumbbell', 'beginner', 'isolation', 'Un ejercicio de aislamiento para los tríceps realizado en posición inclinada hacia adelante.', ARRAY['Inclínate hacia adelante en las caderas sosteniendo una mancuerna con el codo doblado a 90 grados.','Extiende el brazo recto hacia atrás apretando el tríceps.','Mantén brevemente en la extensión completa.','Baja con control.','Repite en ambos lados.'], ARRAY['Mantén el codo pegado y fijo junto al torso.','Extiende el brazo por completo apretando el tríceps al final.','Trabaja un lado a la vez con control en la bajada.'], '/exercises/tricep-kickback-main.webp', '/exercises/tricep-kickback-main.webp'),
  ('Jalón de Tríceps en Cable', 'tricep-pushdown', 'triceps', NULL, 'cable', 'beginner', 'isolation', 'Un ejercicio de aislamiento para los tríceps usando una máquina de cable.', ARRAY['Párate frente a una máquina de cable con un accesorio de barra recta.','Agarra la barra y pega los codos a los costados.','Empuja la barra hacia abajo hasta que los brazos estén completamente extendidos.','Regresa lentamente a la posición inicial.','Repite.'], ARRAY['Mantén el torso erguido.','Solo deben moverse los antebrazos.'], '/exercises/tricep-pushdown-main.webp', '/exercises/tricep-pushdown-main.webp'),
  ('Curl de Bíceps TRX', 'trx-bicep-curl', 'biceps', NULL, 'bodyweight', 'beginner', 'isolation', 'Este ejercicio utiliza un entrenador de suspensión para aislar y fortalecer los músculos bíceps braquial y braquial, desarrollando fuerza e hipertrofia en la parte superior del brazo.', ARRAY['Ajusta las correas del entrenador de suspensión a una longitud media.','Párate frente al punto de anclaje, sujeta las asas con un agarre supino e inclínate hacia atrás hasta que tus brazos estén completamente extendidos.','Mantén tu cuerpo recto y el core activado, jala tu pecho hacia tus manos doblando los codos.','Contrae tus bíceps en la parte superior del movimiento.','Extiende lentamente tus brazos de regreso a la posición inicial, controlando el descenso.','Mantén la tensión durante toda la serie.'], ARRAY['Ajusta el ángulo de tu cuerpo para aumentar o disminuir la dificultad; inclinarte más hacia atrás lo hace más difícil.','Mantén los codos altos y fijos para aislar los bíceps de manera efectiva.','Evita balancear tu cuerpo o usar el impulso; concéntrate en una contracción controlada.','Asegura un rango completo de movimiento, desde la extensión total hasta una fuerte contracción máxima.'], '/exercises/trx-bicep-curl-main.webp', '/exercises/trx-bicep-curl-main.webp'),
  ('Press de Pecho con TRX', 'trx-chest-press', 'chest', ARRAY['shoulders','core','triceps'], 'bodyweight', 'beginner', 'compound', 'Un ejercicio compuesto de empuje que utiliza un entrenador de suspensión para desarrollar fuerza y estabilidad en el pecho.', ARRAY['Ajusta las asas del entrenador de suspensión a la altura de la mitad de la pantorrilla.','Ponte de espaldas al punto de anclaje, sosteniendo un asa en cada mano, con los brazos extendidos.','Inclínate hacia adelante en una posición de plancha, manteniendo tu cuerpo recto de la cabeza a los talones.','Baja tu pecho hacia tus manos doblando los codos, manteniendo la tensión en las correas.','Empuja hacia arriba a la posición inicial, extendiendo completamente los brazos y contrayendo el pecho.'], ARRAY['Mantén tu core activado durante todo el movimiento para mantener una plancha rígida.','Controla la fase excéntrica (descenso) para una mejor activación muscular.','Ajusta la posición de tus pies para modificar la dificultad: más cerca del anclaje para más fácil, más lejos para más difícil.','Asegúrate de que tus codos se muevan ligeramente hacia afuera y hacia atrás, sin abrirlos demasiado.'], '/exercises/trx-chest-press-main.webp', '/exercises/trx-chest-press-main.webp'),
  ('Face Pull con TRX', 'trx-face-pull', 'shoulders', ARRAY['traps'], 'bodyweight', 'beginner', 'compound', 'El Face Pull con TRX es un ejercicio de tracción compuesto que trabaja los deltoides posteriores y los romboides, utilizando un entrenador de suspensión para mejorar la fuerza de la parte superior de la espalda y la postura.', ARRAY['Sujeta las asas del TRX con un agarre prono, las palmas hacia abajo.','Inclínate hacia atrás hasta que tus brazos estén completamente extendidos y tu cuerpo forme una línea recta.','Tira de las asas hacia tu cara, llevando los codos altos y abiertos.','Aprieta los omóplatos al máximo de la contracción.','Extiende lentamente los brazos de vuelta a la posición inicial con control.'], ARRAY['Mantén el torso rígido durante todo el movimiento; evita arquear la espalda baja.','Concéntrate en iniciar la tracción con los músculos de la parte superior de la espalda, no solo con los brazos.','Ajusta el ángulo de tu cuerpo para modificar la dificultad: una posición más horizontal es más difícil.'], '/exercises/trx-face-pull-main.webp', '/exercises/trx-face-pull-main.webp'),
  ('Curl de Isquiotibiales con TRX', 'trx-hamstring-curl', 'hamstrings', ARRAY['calves','glutes'], 'bodyweight', 'intermediate', 'isolation', 'Este ejercicio de aislamiento utiliza un entrenador de suspensión para trabajar los isquiotibiales, glúteos y pantorrillas al flexionar los talones hacia los glúteos.', ARRAY['Acuéstate boca arriba con los talones en los soportes del entrenador de suspensión, rodillas flexionadas a 90 grados.','Levanta tus caderas del suelo, creando una línea recta desde las rodillas hasta los hombros.','Extiende tus piernas hacia adelante, manteniendo las caderas elevadas y la tensión en el core.','Tira de tus talones hacia tus glúteos, contrayendo los isquiotibiales con fuerza.','Controla el movimiento, evitando que las caderas caigan durante toda la serie.'], ARRAY['Mantén tu core contraído para evitar que tus caderas se hundan.','Concéntrate en una fuerte contracción de los isquiotibiales en el punto máximo del curl.','Controla la fase excéntrica extendiendo lentamente tus piernas.'], '/exercises/trx-hamstring-curl-main.webp', '/exercises/trx-hamstring-curl-main.webp'),
  ('Zancada TRX', 'trx-lunge', 'glutes', ARRAY['hamstrings'], 'bodyweight', 'beginner', 'compound', 'Un ejercicio unilateral de tren inferior apto para principiantes que utiliza un entrenador de suspensión para trabajar los cuádriceps y glúteos, mientras involucra los isquiotibiales y el glúteo medio para la estabilidad.', ARRAY['Ponte de espaldas al punto de anclaje, sosteniendo las asas del entrenador de suspensión frente a ti.','Coloca un pie en ambos estribos, extendiendo la pierna hacia atrás.','Contrae tu abdomen y baja tu cuerpo doblando la rodilla delantera, manteniendo el torso erguido.','Desciende hasta que tu muslo delantero esté paralelo al suelo o ligeramente por debajo, manteniendo la tensión en el entrenador de suspensión.','Impúlsate a través del talón delantero para volver a la posición inicial, extendiendo la pierna delantera.','Completa todas las repeticiones en un lado, luego cambia de pierna y repite por lado.'], ARRAY['Mantén tu rodilla delantera alineada con tus dedos del pie, evitando que colapse hacia adentro.','Conserva una columna vertebral neutra durante todo el movimiento, previniendo un arqueo o redondeo excesivo.','Controla la fase excéntrica (de descenso) para maximizar el compromiso muscular.','Ajusta tu distancia del punto de anclaje para modificar la dificultad.'], '/exercises/trx-lunge-main.webp', '/exercises/trx-lunge-main.webp'),
('Sentadilla Pistola con TRX', 'trx-pistol-squat', 'glutes', ARRAY['hamstrings'], 'bodyweight', 'intermediate', 'compound', 'Un desafiante ejercicio unilateral de pierna que utiliza un entrenador de suspensión para asistir el equilibrio y la profundidad, trabajando principalmente los cuádriceps y glúteos.', ARRAY['Ancla el entrenador de suspensión y sujeta las asas con ambas manos, con los brazos extendidos.','Ponte de pie, levanta una pierna recta hacia adelante, manteniéndola separada del suelo.','Inicia la sentadilla empujando las caderas hacia atrás y doblando la rodilla de la pierna de apoyo, bajando el cuerpo lo más profundo posible.','Mantén el pecho erguido, la espalda recta y usa el TRX para el equilibrio y soporte según sea necesario.','Impúlsate a través del talón para volver a la posición inicial, extendiendo completamente la pierna de apoyo.','Completa todas las repeticiones por lado antes de cambiar de pierna.'], ARRAY['Mantén la tensión en las correas del TRX durante todo el movimiento para mayor estabilidad.','Concéntrate en un descenso controlado y un ascenso potente.','Mantén la pierna que no trabaja extendida y elevada para activar los flexores de la cadera.','Ajusta tu agarre en el TRX para modificar el nivel de asistencia.'], '/exercises/trx-pistol-squat-main.webp', '/exercises/trx-pistol-squat-main.webp'),
  ('Plancha en TRX', 'trx-plank', 'core', ARRAY['shoulders'], 'bodyweight', 'intermediate', 'compound', 'Una plancha con los pies suspendidos en el TRX, que aumenta la demanda sobre el core y la estabilidad.', ARRAY['Coloca ambos pies en los estribos del TRX.','Adopta una posición de plancha en antebrazos o plancha alta en el suelo.','Mantén el cuerpo en línea recta de la cabeza a los talones.','Contrae el core y aprieta los glúteos.','Mantén la posición el tiempo deseado.','Baja las rodillas para salir de forma segura.'], ARRAY['Mantén el cuerpo en línea recta de la cabeza a los talones.','Aprieta abdomen y glúteos durante toda la retención.','Evita que la cadera se hunda o se eleve.'], '/exercises/trx-plank-main.webp', '/exercises/trx-plank-main.webp'),
  ('Remo TRX', 'trx-row', 'back', ARRAY['biceps','shoulders','traps'], 'bodyweight', 'beginner', 'compound', 'Este ejercicio de tracción con peso corporal utiliza un entrenador de suspensión para trabajar toda tu espalda, desarrollando fuerza en los dorsales, romboides y bíceps.', ARRAY['Sujeta las asas de un entrenador de suspensión con un agarre prono, las palmas de las manos enfrentadas.','Inclínate hacia atrás, extendiendo completamente los brazos y manteniendo el cuerpo recto de la cabeza a los talones.','Activa tu core y tira del pecho hacia las manos, juntando los omóplatos.','Haz una breve pausa en la parte superior, luego baja lentamente a la posición inicial con control.','Mantén el cuerpo rígido durante todo el movimiento, evitando que las caderas se caigan.'], ARRAY['Ajusta la posición de tus pies: cuanto más cerca estén tus pies del punto de anclaje, más difícil será el ejercicio.','Mantén los codos cerca del cuerpo para enfatizar los dorsales, o ábrelos ligeramente para trabajar más la parte superior de la espalda.','Concéntrate en iniciar la tracción con los músculos de la espalda, no solo con los brazos.','Controla la fase excéntrica (de descenso) para maximizar el compromiso muscular.'], '/exercises/trx-row-main.webp', '/exercises/trx-row-main.webp'),
  ('Plancha Lateral en TRX', 'trx-side-plank', 'core', ARRAY['glutes','shoulders'], 'bodyweight', 'intermediate', 'compound', 'Una plancha lateral con los pies en el TRX, que trabaja los oblicuos y la estabilidad de la cadera.', ARRAY['Coloca ambos pies en los soportes del TRX y recuéstate de lado.','Apóyate en el antebrazo inferior con el codo bajo el hombro.','Eleva las caderas de modo que el cuerpo forme una línea recta.','Apila el pie superior sobre el pie inferior.','Mantén la posición respirando de forma constante.','Baja y cambia de lado al terminar la serie.'], ARRAY['Coloca el codo justo debajo del hombro de apoyo.','Eleva la cadera hasta formar una línea recta.','Respira de forma constante y cambia de lado al terminar.'], '/exercises/trx-side-plank-main.webp', '/exercises/trx-side-plank-main.webp'),
  ('Sentadilla TRX', 'trx-squat', 'glutes', ARRAY['hamstrings'], 'bodyweight', 'beginner', 'compound', 'Este ejercicio compuesto de peso corporal utiliza un entrenador de suspensión para asistir en la realización de una sentadilla, trabajando eficazmente cuádriceps, glúteos e isquiotibiales.', ARRAY['Párate mirando hacia el punto de anclaje, sosteniendo las asas con las palmas enfrentadas y los brazos extendidos.','Inclínate ligeramente hacia atrás, manteniendo tu cuerpo recto y el core activado, con los pies al ancho de los hombros.','Inicia la sentadilla empujando las caderas hacia atrás y doblando las rodillas, bajando tu cuerpo como si te sentaras en una silla.','Desciende hasta que tus muslos estén paralelos al suelo o tan profundo como te sea cómodo, manteniendo la tensión en las correas.','Impúlsate a través de los talones para volver a la posición inicial, extendiendo completamente las caderas y las rodillas.'], ARRAY['Mantén el pecho erguido y la mirada al frente durante todo el movimiento para mantener una columna vertebral neutra.','Usa el entrenador de suspensión para ayudarte a controlar el descenso y el ascenso, especialmente si eres nuevo en las sentadillas.','Concéntrate en empujar las rodillas ligeramente hacia afuera para activar los glúteos de manera más efectiva.'], '/exercises/trx-squat-main.webp', '/exercises/trx-squat-main.webp'),
  ('Extensión de Tríceps TRX', 'trx-tricep-extension', 'triceps', NULL, 'bodyweight', 'intermediate', 'isolation', 'Este ejercicio trabaja el tríceps braquial utilizando un entrenador de suspensión, enfocándose en la extensión del codo para el desarrollo y la fuerza de la parte superior del brazo.', ARRAY['Párate frente al punto de anclaje, sosteniendo las asas del TRX con un agarre por encima, las palmas hacia abajo.','Inclínate hacia adelante, extendiendo tus brazos rectos frente a ti a la altura de los hombros, creando tensión en las correas.','Manteniendo los codos altos y fijos, dóblalos para bajar tu cuerpo, llevando tus manos hacia tus sienes.','Extiende los codos con fuerza para empujar tu cuerpo de vuelta a la posición inicial, contrayendo tus tríceps.','Mantén una posición de plancha rígida durante todo el movimiento, activando tu core y glúteos.'], ARRAY['Ajusta el ángulo de tu cuerpo para aumentar o disminuir la dificultad; cuanto más horizontal, más difícil será el ejercicio.','Mantén los codos apuntando hacia adelante y altos para maximizar el aislamiento del tríceps y minimizar la participación del hombro.','Controla la fase excéntrica (descenso) para una mejor activación y crecimiento muscular.'], '/exercises/trx-tricep-extension-main.webp', '/exercises/trx-tricep-extension-main.webp'),
  ('TRX Y-Fly', 'trx-y-fly', 'shoulders', ARRAY['back'], 'bodyweight', 'intermediate', 'isolation', 'Este ejercicio con el entrenador de suspensión fortalece los deltoides posteriores y el trapecio, mejorando la salud del hombro y la postura al fortalecer la parte superior de la espalda.', ARRAY['Párate frente al punto de anclaje, sujetando las asas con un agarre por encima, las palmas de las manos enfrentadas.','Inclínate hacia atrás, extendiendo los brazos rectos hacia adelante, manteniendo tu cuerpo en posición de plancha.','Inicia el movimiento juntando y bajando tus omóplatos, formando una "Y" con tu cuerpo.','Mantén los brazos rectos y los codos ligeramente flexionados, apretando los omóplatos en la parte superior.','Controla lentamente el descenso de vuelta a la posición inicial, resistiendo la tracción de las correas.'], ARRAY['Ajusta el ángulo de tu cuerpo para modificar la dificultad: inclinarte más hacia atrás aumenta el desafío.','Concéntrate en la retracción y depresión de tus omóplatos durante todo el movimiento.','Mantén un core rígido y una línea corporal recta para evitar que las caderas se caigan.'], '/exercises/trx-y-fly-main.webp', '/exercises/trx-y-fly-main.webp'),
  ('Remo al Mentón con Barra', 'upright-row', 'shoulders', ARRAY['biceps'], 'barbell', 'intermediate', 'compound', 'Un movimiento de tirón compuesto para los deltoides laterales y el trapecio superior.', ARRAY['Párate sosteniendo una barra con un agarre en pronación a la anchura de los hombros.','Tira de la barra hacia arriba a lo largo del cuerpo en dirección al mentón.','Lidera con los codos, manteniéndolos por encima de las manos.','Baja la barra de forma controlada.','Repite.'], ARRAY['Sube la barra pegada al cuerpo hacia la barbilla.','Guía el movimiento con los codos por encima de las manos.','Baja la barra de forma controlada en cada repetición.'], '/exercises/upright-row-main.webp', '/exercises/upright-row-main.webp'),
  ('Perro Boca Arriba', 'upward-dog', 'back', ARRAY['glutes','chest'], NULL, 'intermediate', 'mobility', 'Una extensión boca abajo sobre los brazos estirados con los muslos despegados del suelo, donde los brazos y los extensores de la espalda mantienen el pecho abierto y la columna larga.', ARRAY['Túmbate boca abajo con las manos junto a las costillas bajas y el empeine apoyado en el suelo.','Presiona las manos y estira los brazos, elevando primero el pecho y después los muslos de la esterilla.','Lleva los hombros atrás y abajo y mantén el cuello largo.','Mantén la posición durante el tiempo indicado con solo las manos y el empeine en el suelo.','Flexiona los brazos y baja de forma controlada.'], ARRAY['Mantén los hombros sobre las muñecas en lugar de por detrás de ellas.','Presiona el empeine contra el suelo; eso es lo que eleva los muslos.','Si los muslos no pueden despegarse, quédate en la cobra en lugar de forzar la posición.'], '/exercises/upward-dog-main.webp', '/exercises/upward-dog-main.webp'),
  ('Jalón al Pecho con Barra en V', 'v-bar-lat-pulldown', 'back', ARRAY['biceps','traps'], 'cable', 'beginner', 'compound', 'Un jalón con agarre neutro realizado con una barra en V estrecha, maximizando el estiramiento del dorsal y permitiendo una contracción más profunda.', ARRAY['Coloca una barra en V (mango doble-D) en el cable de jalón al pecho.','Siéntate con los muslos asegurados bajo el pad y agarra el mango con las palmas enfrentadas.','Comienza con los brazos completamente extendidos por encima de la cabeza.','Tira del mango hacia el esternón empujando los codos hacia abajo y ligeramente hacia atrás.','Aprieta los dorsales en la posición inferior y sube lentamente de forma controlada.','Repite el número de repeticiones recomendado.'], ARRAY['El agarre neutro es más suave con los hombros que los agarres en pronación o supinación.','Imagina que acercas las costillas hacia las caderas: piensa en los dorsales, no en los brazos.'], '/exercises/v-bar-lat-pulldown-main.webp', '/exercises/v-bar-lat-pulldown-main.webp'),
  ('Extensión de Tríceps en Polea con Barra en V', 'v-bar-tricep-pushdown', 'triceps', NULL, 'cable', 'beginner', 'isolation', 'Una extensión de tríceps en polea con barra en V que fija las muñecas en posición pronada y ligeramente angulada, cargando la cabeza lateral.', ARRAY['Coloca una barra en V en la polea alta.','Párate frente a la pila y agarra la barra en V con ambas manos, palmas hacia abajo.','Comienza con los codos pegados a los costados y los antebrazos paralelos al suelo.','Empuja el mango hacia abajo hasta que los brazos estén completamente extendidos.','Aprieta los tríceps y vuelve de forma controlada a la posición inicial.','Repite el número de repeticiones recomendado.'], ARRAY['Mantén los codos pegados a los costados durante toda la serie.','No te apoyes en la barra; una pequeña inclinación hacia adelante está bien, pero deja que los tríceps hagan el trabajo.'], '/exercises/v-bar-tricep-pushdown-main.webp', '/exercises/v-bar-tricep-pushdown-main.webp'),
  ('Posición en V', 'v-sit', 'core', ARRAY['quads'], NULL, 'intermediate', 'compound', 'Un sostén estático del core en equilibrio sobre los isquiones, con las piernas y el torso elevados formando una V, que exige a los abdominales y los flexores de cadera.', ARRAY['Siéntate en el suelo con las piernas extendidas frente a ti.','Inclínate ligeramente hacia atrás y eleva las piernas del suelo.','Extiende los brazos hacia adelante para que el cuerpo forme una V.','Equilíbrate sobre los isquiones con el core firme.','Mantén la posición respirando de forma constante.','Baja las piernas y el torso para salir.'], ARRAY['Mantén el pecho elevado y la columna larga en lugar de redondear la espalda.','Flexiona las rodillas si aún no puedes mantener las piernas estiradas.'], '/exercises/v-sit-main.webp', '/exercises/v-sit-main.webp'),
  ('V-Ups', 'v-ups', 'core', NULL, NULL, 'intermediate', 'compound', 'Un ejercicio dinámico de core que eleva las piernas y el torso juntos formando una V, trabajando los abdominales y los flexores de la cadera.', ARRAY['Túmbate boca arriba con los brazos extendidos por encima de la cabeza y las piernas rectas.','Levanta simultáneamente las piernas y la parte superior del cuerpo hacia el centro.','Alcanza las manos hacia los pies en la parte superior, formando una V.','Mantén las piernas rectas durante todo el movimiento.','Baja ambos extremos de forma controlada hasta el suelo.','Repite el número de repeticiones deseado.'], ARRAY['Mantén las piernas estiradas mientras las elevas.','Lleva las manos hacia los pies en la parte alta.','Baja ambos extremos con control en lugar de dejarte caer plano.'], '/exercises/v-ups-main.webp', '/exercises/v-ups-main.webp'),
  ('Caminar', 'walking', 'calves', ARRAY['glutes','hamstrings','core'], NULL, 'beginner', 'cardio', 'Marcha natural sobre terreno llano, manteniendo siempre un pie en contacto con el suelo, lo que la convierte en la forma de menor impacto de acumular trabajo aeróbico.', ARRAY['Ponte erguido, con el peso sobre la parte media de los pies y los hombros relajados, sin llevarlos hacia atrás.','Da un paso al frente y apoya primero el talón, luego rueda sobre el pie y empuja con la almohadilla y los dedos.','Mantén al menos un pie en el suelo en todo momento — en cuanto ambos se despegan estás corriendo, no caminando.','Deja que los brazos oscilen con naturalidad desde el hombro, brazo contrario a pierna contraria, con los codos ligeramente flexionados.','Mira al frente en lugar de a los pies y respira con un ritmo constante y sostenible.','Continúa el tiempo o la distancia deseados, eligiendo un ritmo al que todavía podrías mantener una conversación.'], ARRAY['El ritmo lo es todo aquí. Un paseo y una caminata enérgica son estímulos distintos, así que elige uno a propósito en vez de dejarte llevar.','Alarga el empuje por detrás en lugar de estirar más hacia delante: la zancada larga te hace aterrizar con la pierna recta y frena cada paso.','Es el único trabajo de acondicionamiento que puedes hacer a diario sin necesitar recuperarte de él, y por eso merece la pena programarlo en vez de dejarlo al azar.'], '/exercises/walking-main.webp', '/exercises/walking-main.webp'),
  ('Zancada Caminando', 'walking-lunge', 'glutes', ARRAY['hamstrings'], NULL, 'intermediate', 'compound', 'Una zancada en movimiento que avanza pierna tras pierna, trabajando los cuádriceps y glúteos con un desafío de equilibrio adicional.', ARRAY['Párate erguido con los pies separados al ancho de las caderas y las manos en las caderas.','Da un paso adelante largo con un pie en zancada.','Baja hasta que ambas rodillas estén en torno a 90 grados.','Empuja con el talón delantero y lleva el pie trasero hacia adelante.','Continúa alternando piernas al avanzar.','Repite el número de repeticiones deseado.'], ARRAY['Baja hasta que ambas rodillas formen unos 90 grados.','Mantén el torso erguido al dar el paso.','Impulsa con el talón delantero para avanzar con fluidez.'], '/exercises/walking-lunge-main.webp', '/exercises/walking-lunge-main.webp'),
  ('Push-Ups en Pared', 'wall-push-ups', 'chest', ARRAY['shoulders','triceps'], NULL, 'beginner', 'compound', 'Una flexión de pie contra la pared apta para principiantes, que trabaja el pecho con carga reducida.', ARRAY['Párate frente a una pared y coloca las palmas sobre ella a la altura de los hombros.','Retrocede con los pies hasta que los brazos estén completamente extendidos.','Flexiona los codos para acercar el pecho a la pared.','Mantén el cuerpo en línea recta durante todo el movimiento.','Empuja de vuelta a la posición inicial.','Repite el número de repeticiones deseado.'], ARRAY['Apoya las palmas a la altura de los hombros.','Mantén el cuerpo en línea recta de la cabeza a los pies.','Acerca el pecho a la pared flexionando los codos.'], '/exercises/wall-push-ups-main.webp', '/exercises/wall-push-ups-main.webp'),
  ('Sentadilla en Pared', 'wall-sit', 'glutes', ARRAY['hamstrings'], NULL, 'beginner', 'compound', 'Un ejercicio isométrico estático que consiste en mantener la posición de sentadilla contra una pared para desarrollar la resistencia de los cuádriceps.', ARRAY['Párate con la espalda contra una pared.','Deslízate hacia abajo hasta que los muslos estén paralelos al suelo.','Mantén la posición.','Vuelve a ponerte de pie cuando termines.'], ARRAY['Mantén las rodillas a 90 grados.','Presiona la espalda plana contra la pared.'], '/exercises/wall-sit-main.webp', '/exercises/wall-sit-main.webp'),
  ('Guerrero I', 'warrior-one', 'glutes', ARRAY['shoulders','back'], NULL, 'intermediate', 'compound', 'Una postura en paso largo con el pie trasero apoyado en diagonal, la rodilla delantera flexionada y los brazos arriba, con las caderas mirando al frente.', ARRAY['Lleva un pie atrás y gíralo unos cuarenta y cinco grados, apoyando toda la planta.','Flexiona la rodilla delantera hasta que quede sobre el tobillo y mantén la pierna trasera estirada.','Lleva ambas caderas hacia el frente de la esterilla y eleva los brazos por encima de la cabeza.','Mantén la posición durante el tiempo indicado, con las costillas cerradas y el pecho alto.','Junta los pies y repite del otro lado.'], ARRAY['Separa los pies lateralmente para que ambas caderas miren al frente sin forzar la rodilla trasera.','Presiona el borde externo del pie trasero para mantener la base estable.','Separa los brazos a la anchura de los hombros si juntar las palmas te arquea la zona lumbar.'], '/exercises/warrior-one-main.webp', '/exercises/warrior-one-main.webp'),
('Guerrero III', 'warrior-three', 'glutes', ARRAY['back'], NULL, 'intermediate', 'compound', 'Un equilibrio sobre una pierna con el torso y la pierna elevada paralelos al suelo, formando una línea larga desde las yemas de los dedos hasta el talón elevado.', ARRAY['Ponte de pie sobre una pierna con la rodilla blanda y las caderas niveladas.','Bascula hacia delante desde las caderas mientras la otra pierna se eleva por detrás.','Continúa hasta que el torso y la pierna elevada queden aproximadamente paralelos al suelo.','Estira los brazos hacia delante, junto al cuerpo o hacia los lados, y mantén durante el tiempo indicado.','Baja la pierna y repite del otro lado.'], ARRAY['Evita que la cadera elevada se abra hacia arriba; ambas deben mirar al suelo.','Flexiona el pie elevado y empuja el talón hacia atrás para mantener la pierna activa.','Apoya las manos en bloques o en una pared mientras construyes el equilibrio.'], '/exercises/warrior-three-main.webp', '/exercises/warrior-three-main.webp'),
  ('Guerrero II', 'warrior-two', 'glutes', ARRAY['adductors','shoulders'], NULL, 'intermediate', 'compound', 'Una postura de base amplia con la rodilla delantera flexionada, las caderas abiertas al lado y los brazos extendidos a la altura de los hombros.', ARRAY['Sepárate en una base amplia con el pie delantero girado noventa grados y el trasero algo hacia dentro.','Flexiona la rodilla delantera hasta que quede sobre el tobillo y apunte hacia los dedos centrales.','Abre las caderas y el pecho hacia el lado y extiende los brazos paralelos al suelo.','Mantén la posición durante el tiempo indicado, con la mirada sobre la mano delantera.','Estira la pierna delantera y repite del otro lado.'], ARRAY['Evita que la rodilla delantera caiga hacia dentro; empújala hacia el lado del dedo meñique.','Alinea los hombros sobre las caderas en lugar de inclinarte hacia la pierna delantera.','Acorta la base si el muslo delantero no puede acercarse a la paralela.'], '/exercises/warrior-two-main.webp', '/exercises/warrior-two-main.webp'),
  ('Fondos Lastrados', 'weighted-dips', 'chest', ARRAY['shoulders'], 'bodyweight', 'advanced', 'compound', 'Un fondo en paralelas con carga añadida — normalmente un disco colgado de un cinturón de lastre entre las piernas — para mantener el ejercicio en un rango de fuerza cuando los fondos con el propio peso ya resultan fáciles.', ARRAY['Cuelga un disco del cinturón de lastre y ajústalo a la cintura de modo que el peso quede suelto entre las piernas.','Agarra las barras paralelas y súbete hasta la posición inicial con los brazos estirados y los pies separados del suelo.','Inclina ligeramente el torso hacia delante y baja el cuerpo flexionando los codos hasta que los hombros queden por debajo de ellos.','Empuja con las palmas para volver a subir hasta estirar los brazos, evitando que el disco colgante se balancee.','Repite el número de repeticiones deseado.'], ARRAY['Añade peso solo cuando hagas fondos limpios con el propio peso en todo el recorrido: saltos de 2,5 a 5 kg son suficientes, porque la carga se suma a tu propio peso corporal.','Mantén las piernas juntas y el core apretado para que el disco no empiece a balancearse; un peso que oscila estropea la parte baja de la repetición.','Mantén los hombros alejados de las orejas y detén el descenso si notas pinzamiento en la parte delantera del hombro.'], '/exercises/weighted-dips-main.webp', '/exercises/weighted-dips-main.webp'),
  ('Dominada Lastrada', 'weighted-pull-up', 'back', ARRAY['biceps','shoulders','traps'], 'bodyweight', 'advanced', 'compound', 'Una dominada con carga añadida — normalmente un disco colgado de un cinturón de lastre entre las piernas — para mantener el ejercicio en un rango de fuerza cuando las dominadas con el propio peso ya resultan fáciles.', ARRAY['Cuelga un disco del cinturón de lastre y ajústalo a la cintura de modo que el peso quede suelto entre las piernas; también puedes sujetar la carga entre los pies.','Agarra la barra en pronación algo más abierto que la anchura de los hombros y cuélgate con los brazos estirados y las piernas juntas.','Tira de los codos hacia abajo y hacia atrás llevando el pecho hacia la barra hasta que la barbilla la supere.','Baja de forma controlada hasta la suspensión completa, mantén la tensión en los dorsales y deja que el peso se estabilice antes de la siguiente repetición.','Repite el número de repeticiones deseado.'], ARRAY['Añade peso solo cuando hagas dominadas limpias con el propio peso en todo el recorrido: saltos de 2,5 a 5 kg son suficientes, porque la carga se suma a tu propio peso corporal.','Mantén las piernas juntas y el core apretado para que el disco colgante no empiece a balancearse; un peso que oscila convierte la repetición en un kipping.','No recortes la parte baja: vuelve a la suspensión completa en cada repetición y termina la serie cuando la barbilla deje de superar la barra, en lugar de forzar repeticiones parciales.'], '/exercises/weighted-pull-up-main.webp', '/exercises/weighted-pull-up-main.webp'),
  ('Crunch en Pared con Peso', 'weighted-wall-crunch', 'core', NULL, 'barbell', 'intermediate', 'isolation', 'Una variante del crunch con las piernas apartadas del movimiento —los pies apoyados contra una pared o un cajón, o simplemente las piernas en alto— para que la cadera no ayude y trabajen los abdominales.', ARRAY['Túmbate boca arriba y coloca las piernas de modo que la cadera no pueda ayudar: apoya los pies contra una pared o un cajón, o mantén las piernas en alto con las rodillas flexionadas.','Sujeta un peso contra el pecho con ambas manos: un disco, una mancuerna o una pesa rusa sirven igual.','Haz el crunch hacia arriba, despegando los omóplatos del suelo.','Baja de forma controlada.','Repite.'], ARRAY['Apoya los pies en la pared con las rodillas a 90 grados.','Sujeta el disco sobre el pecho durante todo el ejercicio.','Despega los omóplatos del suelo sin tirar del cuello.'], '/exercises/weighted-wall-crunch-main.webp', '/exercises/weighted-wall-crunch-main.webp'),
  ('Press de Banca en Agarre Ancho', 'wide-grip-bench-press', 'chest', ARRAY['shoulders','triceps'], 'barbell', 'intermediate', 'compound', 'Una variante del press de banca con un agarre más ancho que los hombros para maximizar la activación del pectoral.', ARRAY['Túmbate en un banco plano. Agarra la barra más ancha que los hombros.','Baja la barra hasta la mitad del pecho.','Empuja de vuelta a la extensión completa.','Repite.'], ARRAY['Un agarre más ancho reduce la participación de los tríceps.','Evita doblar las muñecas en exceso.'], '/exercises/wide-grip-bench-press-main.webp', '/exercises/wide-grip-bench-press-main.webp'),
  ('Dominadas en Agarre Ancho', 'wide-grip-pull-ups', 'back', ARRAY['biceps','shoulders','traps'], 'bodyweight', 'intermediate', 'compound', 'Una dominada con agarre prono más ancho que los hombros, que enfatiza el desarrollo de los dorsales.', ARRAY['Agarra la barra de dominadas con un agarre en pronación más ancho que los hombros.','Cuélgate con los brazos completamente extendidos y el core contraído.','Tira del pecho hacia la barra empujando los codos hacia abajo.','Mantén los hombros hacia atrás al subir.','Baja de forma controlada hasta la extensión completa.','Repite el número de repeticiones deseado.'], ARRAY['Cuelga con los brazos extendidos y el core firme.','Lleva el pecho hacia la barra bajando los codos.','Desciende con control hasta la extensión completa.'], '/exercises/wide-grip-pull-ups-main.webp', '/exercises/wide-grip-pull-ups-main.webp'),
  ('Flexiones con Agarre Ancho', 'wide-grip-push-ups', 'chest', ARRAY['shoulders','core','triceps'], NULL, 'intermediate', 'compound', 'Una variante de flexión con las manos colocadas más separadas para enfatizar el pecho.', ARRAY['Comienza en una plancha alta con las manos más separadas que el ancho de hombros.','Mantén el cuerpo en línea recta de la cabeza a los talones.','Baja el pecho hacia el suelo flexionando los codos.','Mantén el core activado y los glúteos contraídos.','Empuja de vuelta hasta extender los brazos.','Repite el número de repeticiones deseado.'], ARRAY['Mantén los codos a unos 45 grados respecto al torso.','Mantén una línea recta de la cabeza a los talones.','Baja hasta que el pecho quede cerca del suelo.'], '/exercises/wide-grip-push-ups-main.webp', '/exercises/wide-grip-push-ups-main.webp'),
  ('Remo en Polea Sentado en Agarre Ancho', 'wide-grip-seated-cable-row', 'back', ARRAY['biceps','shoulders'], 'cable', 'intermediate', 'compound', 'Una variante del remo sentado con agarre ancho que hace énfasis en la parte superior de la espalda.', ARRAY['Siéntate en la estación de remo con los pies en la plataforma.','Agarra la barra ancha con un agarre en pronación.','Tira de la barra hacia el abdomen superior apretando los omóplatos.','Extiende los brazos de vuelta a la posición inicial de forma controlada.','Repite.'], ARRAY['Sujeta la barra ancha con agarre prono.','Lleva la barra hacia el abdomen alto juntando los omóplatos.','Extiende los brazos al frente de forma controlada.'], '/exercises/wide-grip-seated-cable-row-main.webp', '/exercises/wide-grip-seated-cable-row-main.webp'),
  ('Flexión con Piernas Abiertas', 'wide-legged-forward-fold', 'adductors', ARRAY['back','calves'], NULL, 'beginner', 'mobility', 'Una flexión de pie desde una base amplia con las manos en el suelo, que alarga los isquiotibiales y la cara interna de los muslos mientras la columna cuelga larga.', ARRAY['Ponte de pie con los pies muy separados y los bordes externos paralelos.','Apoya las manos en las caderas, eleva el pecho y bascula hacia delante desde las articulaciones de la cadera.','Lleva las manos al suelo bajo los hombros y deja que la cabeza cuelgue.','Mantén la flexión durante el tiempo indicado, desplazando ligeramente el peso hacia las puntas de los pies.','Devuelve las manos a las caderas y sube con la espalda plana.'], ARRAY['Deja una micro flexión en las rodillas para que la flexión venga de las caderas y no de la zona lumbar.','Mantén los pies paralelos; girarlos hacia fuera quita el estiramiento de la cara interna de los muslos.','Apoya las manos en bloques cuando el suelo quede lejos.'], '/exercises/wide-legged-forward-fold-main.webp', '/exercises/wide-legged-forward-fold-main.webp'),
  ('Prensa de piernas con postura amplia', 'wide-stance-leg-press', 'adductors', ARRAY['glutes','hamstrings','quads'], 'machine', 'beginner', 'compound', 'Una prensa de piernas con una postura amplia y ligeramente abierta, que aumenta la participación de los aductores junto con la extensión de cadera y rodilla.', ARRAY['Ajusta el asiento y el respaldo para que la zona lumbar permanezca apoyada en la parte baja del recorrido.','Coloca los pies separados en la plataforma y gira las puntas hacia fuera solo hasta donde las rodillas puedan seguirlas.','Baja el carro flexionando caderas y rodillas y mantén las rodillas en la misma dirección que los pies.','Empuja con todo el pie y extiende caderas y rodillas sin forzar el bloqueo.','Baja el carro bajo control y repite el número deseado de repeticiones.'], ARRAY['Elige una anchura y un ángulo de los pies que puedas controlar desde la cadera; más ancho no siempre es mejor.','Mantén las rodillas siguiendo a los pies y evita que se hundan hacia dentro.','Detén el descenso antes de que la pelvis se despegue y la espalda pierda contacto con el respaldo.'], '/exercises/wide-stance-leg-press-main.webp', '/exercises/wide-stance-leg-press-main.webp'),
  ('Curl de Muñeca con Mancuernas Bilateral', 'wrist-curl', 'forearms', ARRAY['biceps'], 'dumbbell', 'beginner', 'isolation', 'Un curl de muñeca con mancuernas realizado con ambos brazos a la vez, que aísla los flexores del antebrazo para un entrenamiento eficiente.', ARRAY['Siéntate en un banco sujetando una mancuerna en cada mano, con los antebrazos apoyados sobre los muslos, palmas hacia arriba.','Deja que ambas mancuernas rueden hacia las puntas de los dedos.','Flexiona las muñecas para levantar ambas mancuernas.','Aprieta arriba y baja con control.','Repite el número deseado de repeticiones.'], ARRAY['Mantén los antebrazos apoyados en los muslos durante todo el movimiento — solo se mueven las muñecas.','Usa una carga por mano más ligera que en la versión unilateral, ya que ambos lados trabajan a la vez.'], '/exercises/wrist-curl-main.webp', '/exercises/wrist-curl-main.webp'),
  ('Rodillo de Muñeca', 'wrist-roller', 'forearms', ARRAY['shoulders'], 'bodyweight', 'intermediate', 'compound', 'Un ejercicio para el antebrazo que consiste en enrollar un peso con la cuerda mediante el giro de las muñecas.', ARRAY['Agarra el mango del rodillo con los brazos extendidos al frente a la altura de los hombros.','Deja que el peso cuelgue del cordón.','Enrolla el mango hacia adelante con movimientos alternos de muñeca para subir el peso.','Mantén los brazos rectos durante todo el movimiento.','Una vez enrollado por completo, invierte la rotación para bajar el peso.','Repite el número de repeticiones deseado.'], ARRAY['Mantén los brazos extendidos al frente a la altura de los hombros.','Enrolla la cuerda con giros alternos de las muñecas.','Invierte la rotación para bajar el peso de forma controlada.'], '/exercises/wrist-roller-main.webp', '/exercises/wrist-roller-main.webp'),
  ('Curl Zottman', 'zottman-curl', 'biceps', ARRAY['forearms'], 'dumbbell', 'intermediate', 'isolation', 'Un curl con mancuernas de pie que sube con agarre supinado, gira las palmas hacia abajo en la parte superior y desciende en pronación para combinar el trabajo del bíceps con una fase excéntrica centrada en los antebrazos.', ARRAY['Colócate de pie con los pies aproximadamente al ancho de las caderas, los brazos extendidos a los lados y una mancuerna en cada mano con las palmas hacia delante.','Mantén los brazos junto a las costillas y lleva ambas mancuernas hacia los hombros sin balancear el torso.','En la parte superior, conserva los codos flexionados y gira los antebrazos hasta que las palmas miren hacia abajo.','Baja lentamente las mancuernas con el agarre pronado hasta extender los brazos.','Vuelve a girar las palmas hacia delante en la parte inferior y repite las repeticiones deseadas.'], ARRAY['Usa menos peso que en un curl con mancuernas convencional; la bajada con las palmas hacia abajo suele ser la parte limitante.','Gira desde los antebrazos y mantén las muñecas rectas en lugar de doblarlas alrededor de las empuñaduras.','Mantén los codos cerca de las costillas y evita convertir el curl en un balanceo de hombros.'], '/exercises/zottman-curl-main.webp', '/exercises/zottman-curl-main.webp')
) as v(name, slug, muscle_slug, secondary_slugs, equipment_slug, difficulty, movement_type, description, instructions, tips, image_url, thumbnail_url)
on conflict (slug) do nothing;
